using mint = atcoder::modint998244353;

ll N;
ll h[100010];
mint fact[100010], inv[100010], dfact[100010];
std::map<ll, ll> cnt;

int main() {
  std::cin >> N;

  rep( i, 2*N ) {
    std::cin >> h[i];

    ++cnt[h[i]];
  }

  std::vector<ll> fs;

  for( auto m : cnt )
    fs.emplace_back( m.second );

  ll M = fs.size();

  fact[0] = mint(1);
  rep( i, 2*N )
    fact[i+1] = fact[i]*(i+1);

  inv[N] = fact[N].inv();
  repd( i, N )
    inv[i] = inv[i+1]*(i+1);

  // dfact[i] = (2*i-1)!!
  dfact[0] = mint(1);
  rep( i, N )
    dfact[i+1] = dfact[i]*(2*i+1);

  std::vector<std::vector<mint>> d( M );

  rep( i, M ) {
    ll k = fs[i]/2;

    rep( j, k+1 )
      d[i].emplace_back( fact[fs[i]]*inv[2*j]*inv[fs[i]-2*j]*dfact[j] );
  }

  while( d.size() != 1 ) {
    auto pd = d;

    d = std::vector<std::vector<mint>>();

    rep( i, pd.size() ) {
      auto a = pd[i];

      if( i == pd.size()-1 ) {
        d.emplace_back( a );

        break;
      }

      auto b = pd[++i];

      d.emplace_back( atcoder::convolution(a,b) );
    }
  }

  mint ans = 0;

  rep( i, d[0].size() ) {
    ans += d[0][i]*(i&1 ? -1 : 1)*dfact[N-i];
  }

  std::cout << ans.val() << endl;

  return 0;
}

