int f[N], xx[N], yy[N];


vector <int> mul(vector <int> a, vector <int> b) {
	vector <int> c(a.size() + b.size(), 0);
	for(int i = 0; i < a.size(); i++) {
		for(int j = 0; j < b.size(); j++) {
			c[i + j] += a[i] * b[j] % mod;
			c[i + j] %= mod;
		}
	}
	return c;
}

int get(int n, int y) {
	if(n < 0) return 0;
	if(!y) return 1;
	int k = n * (n - 1) / 2;
	k %= mod;
	return k * get(n - 2, y - 1) % mod;
}

