  NTT ntt;
  FPS<ModInt>::set_mul([&](const vector<ModInt> &a, const vector<ModInt> &b) {
    return ntt.convolution(a, b);
  });
  int n; cin >> n;
  Combinatorics<MOD> com(n * 2);
  vector<ModInt> p(n + 1, 1);
  FOR(i, 1, n + 1) p[i] = p[i - 1] * com.nCk(i * 2, 2);
  REP(i, n + 1) p[i] *= com.fact_inv[i];
  map<int, int> mp;
  REP(_, n * 2) {
    int h; cin >> h;
