    int per = pr.second;
    if (per < 2) continue;
    FPS<ModInt> f(per / 2);
    f[0] = 1;
    FOR(i, 1, per / 2 + 1) f[i] = com.nCk(per, i * 2) * p[i];
    fps.emplace_back(f);
  }
  auto comp = [&](int a, int b) {
    return fps[a].degree() > fps[b].degree();
  };
  priority_queue<int, vector<int>, decltype(comp)> que{comp};
  REP(i, fps.size()) que.emplace(i);
  while (que.size() >= 2) {
