    int b = que.top(); que.pop();
    fps[b] *= fps[a];
    que.emplace(b);
  }
  ModInt ans = 0;
  int a = que.top(), deg = fps[a].degree();
  REP(ban, deg + 1) ans += fps[a][ban] * p[n - ban] * (ban & 1 ? -1 : 1);
  cout << ans << '\n';
  return 0;
