		for(auto [hoge, cnt]: mp) {
			vector<mint>ret(cnt / 2 + 1, 1);
			REP(i, cnt / 2 + 1) {
				ret[i] = bc.C(cnt, cnt - i * 2) * (i ? fa[i * 2 - 1] : 1);
			}
			que.push({ret.size(), ret});
		}
	}
	while(que.size() >= 2) {
		auto a = que.top().second;
		que.pop();
		auto b = que.top().second;
		que.pop();
		auto c = convolution(a, b);
		que.push({c.size(), c});
	}
	auto dp = que.top().second;
	mint ans = 0;
	REP(i, dp.size()) {
		//out(i, dp[i].val());
		mint mul = (N * 2 - i * 2 - 1 >= 0 ? fa[N * 2 - i * 2 - 1] : 1);
		ans += (i % 2 ? -dp[i] : dp[i]) * mul;
	}
	out(ans.val());
}

