  using mint = modular<998244353>;
  constexpr int lim = 1e5;
  vector<mint> fact(lim + 1);
  for (int i = 0; i <= lim; ++i) fact[i] = i ? i * fact[i - 1] : 1;

  int n;
  cin >> n;
  n *= 2;
  map<int, int> mp;
  for (int _ = n; _--;) {
