  auto comp = [&](const poly& a, const poly& b) { return size(a) > size(b); };
  priority_queue<poly, vector<poly>, decltype(comp)> pq(comp);

  for (auto [h, sz] : mp) {
    vector<mint> t(sz / 2 + 1);
    for (int i = 0; 2 * i <= sz; ++i)
      t[i] = fact[sz] / fact[sz - 2 * i] / power<mint>(2, i) / fact[i];
