    sort(a.begin(), a.end());
    vector<vector<int>> dp;
    inv2[200004] = mint(1)/pow(mint(2),200004);
    for(int i = 200003; i >= 0; i--)inv2[i] = inv2[i+1] * 2;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    for(int x: a){
