            mint k =combi(x,2*i)*fact[2*i]*fact_inv[i]*inv2[i];
            dp2.push_back(k.a);
        }
        dp.push_back(dp2);
        pq.emplace(dp2.size(), dp.size()-1);
    }
    while(pq.size()>1){
        pii x = pq.top();pq.pop();
        pii y = pq.top();pq.pop();
        dp[x.second] = convolute(dp[x.second], dp[y.second]);
        pq.emplace(dp[x.second].size(), x.second);
    }
    mint ans = 0;
    auto dp2 = dp[pq.top().second];
    dp2.resize(n + 1);
    rep(i,n+1){
        mint k = fact[2*n-2*i]*fact_inv[n-i]*inv2[n-i] * dp2[i];
        if(i&1)ans -=k;
        else ans += k;
    }
    cout << ans << endl;
}

