inline int solve(){
    vector<modint> fact(2*N+1), revfact(2*N+1);
    fact[0] = fact[1] = 1;
    for (int i = 0; i < 2*N; i++) fact[i+1] = fact[i]*(i+1);
    revfact[2*N] = fact[2*N].inv();
    for (int i = 2*N-1; i >= 0; i--) revfact[i] = revfact[i+1]*(i+1);

