    int K = nums.size();
    sort(nums.begin(),nums.end());
    deque<vector<modint> > q;
    for (int k = 0; k < K; k++)
    {
        ll n = nums[k];
        vector<modint> tmp;
        for (int i = 0; 2*i <= n; i++)
        {
            tmp.push_back(fact[n]*revfact[i]*revfact[n-2*i]*modint(2).pow(i).inv());
        }
        q.push_back(tmp);
    }
    auto cmp = [](vector<modint> a, vector<modint> b){return a.size() < b.size();};
    sort(q.begin(), q.end(), cmp);

    while(q.size()>1){
        vector<modint> c = atcoder::convolution(q[0], q[1]);
