    {
        modint ans_k = d[k]*fact[2*N-2*k]*revfact[N-k]*modint(2).pow(N-k).inv();
        if(k%2) ans -= ans_k;
        else ans += ans_k;
    }
    cout << ans.val() << "\n";
    return 0;
}   

