  std::vector<T> finv(N);
  std::vector<T> inv(N);
  fact[0] = T(1);
  for(int i = 1;i < N;i++) {
    fact[i] = fact[i - 1] * T(i);
  }
  finv[N - 1] = T(1) / fact[N - 1];
  for(int i = N - 1; i --> 0;) {
    finv[i] = finv[i + 1] * T(i + 1);
  }
  for(int i = 0;i < N;i++) {
    inv[i] = fact[i - 1] * finv[i];
  }
  return std::make_tuple(std::move(fact), std::move(finv), std::move(inv));
}

using fp = modint<998244353>;
using fps = FPS<fp, fps_ntt_multiply<998244353, 3>>;

int main() {
  i64 N;
  cin >> N;
  vector<i64> cnt(101010);
  rep(i,0,N * 2) {
    i64 a;
    cin >> a;
    cnt[a - 1]++;
  }

  auto [fact, finv, inv] = build_factorial<fp>(101010);
  fps meth(vector<fp> { fp(1) });

  vector<fp> setting;

  {
    fp now(1);
    setting.push_back(now);
    rep(i,1,N + 1) {
      now *= fact[i * 2] * finv[i * 2 - 2] * finv[2];
      setting.push_back(now);
    }
  }
  rep(x,0,101010) {
    if(cnt[x] <= 1) continue;
    vector<fp> vec;
    i64 c = cnt[x];
    for(i64 i = 0; i * 2 <= c; i++) {
      vec.push_back(fact[c] * finv[i * 2] * finv[c - i * 2] * setting[i] * finv[i]);
    }
    meth = meth * fps(vec);
    meth.resize_zero();
  }
  fp ans(0);
  rep(i,0,meth.size()) {
    if(i > N) break;
    fp res = meth[i] * setting[N - i] * finv[N - i];
    if(i % 2 == 0) {
      ans += res;
    }
    else {
      ans -= res;
    }
  }
  cout << ans.value() << endl;
}

