using namespace atcoder;

using modint = modint998244353;

int main() {
  int N;
  io.read(N);
  vector<ll> h(2 * N);
  io.read(h);
  map<int, int> mp;
  REP(i, 2 * N) mp[h[i]]++;
  vector<int> ls;
  int mx = 0;
  for (auto p : mp)
    if (p.second >= 2) {
      ls.push_back(p.second);
      mx += p.second / 2;
    }
  Math<998244353> math(2 * N + 1);
  int n = ls.size();
  vector<modint> dp;
  dp.push_back(modint(1));
  for (ll x : ls) {
    vector<modint> tmp(x / 2 + 1);
    REP(i, x / 2 + 1) tmp[i] = math.C(x, i * 2), debug(x, i, tmp[i].val());
    dp = convolution(dp, tmp);
  }
  vector<modint> pre(2 * N + 1);
  pre[0] = 1;
  for (int i = 2; i < 2 * N + 1; i += 2) pre[i] = pre[i - 2] * (i - 1);
  modint ans = 0;
  for (int i = 0; i <= mx; ++i) {
    if (i % 2 == 0)
      ans += dp[i] * pre[2 * N - i * 2];
    else
      ans -= dp[i] * pre[2 * N - i * 2];
  }
  cout << ans.val() << endl;
  return 0;
}

