using mint = static_modint<998244353>;

int main() {
  ll n;
  cin >> n;
  vector<ll> h(2 * n);
  rep(i, 2 * n) cin >> h[i];
  sort(h.begin(), h.end());
  vector<mint> f(2 * n + 1), ff(2 * n), finv(2 * n + 1);
  f[0] = ff[0] = ff[1] = finv[0] = 1;
  repr(i, 1, 2 * n + 1) {
    f[i] = f[i - 1] * mint::raw(i);
    finv[i] = finv[i - 1] / mint::raw(i);
  }
  repr(i, 2, 2 * n) ff[i] = ff[i - 2] * i;
  vector<mint> forbidden({1});
  ll _fs = 0;
  rep(i, 2 * n) {
    if (i + 1 >= 2 * n || h[i] != h[i + 1]) {
      ll _fw = i + 1 - _fs;
      vector<mint> _fbs(_fw / 2 + 1);
      _fbs[0] = 1;
      repr(j, 1, _fw / 2 + 1) {
        _fbs[j] = f[_fw] * finv[j * 2] * finv[_fw - j * 2] * ff[j * 2 - 1];
      }
      forbidden = convolution(forbidden, _fbs);
      _fs = i + 1;
    }
  }
  ll fbs = forbidden.size();
  mint ans = 0;
  rep(i, n + 1) {
    if (i >= fbs) break;
    mint counts = forbidden[i];
    mint v = counts * (i == n ? 1 : ff[2 * n - 1 - i * 2]);
    if (i % 2 == 0) {
      ans += v;
    } else {
      ans -= v;
    }
  }
  cout << ans.val() << endl;
