const int MOD = 998244353;
void plusle(int &a, int b) {
    a += b;
    while (a >= MOD) a -= MOD;
}
void minun(int &a, int b) {
    a -= b;
    while (a < 0) a += MOD;
}
int add(int a, int b) {
    a += b;
    while (a >= MOD) a -= MOD;
    return a;
}
int sub(int a, int b) {
    a -= b;
    while (a < 0) a += MOD;
    return a;
}
int mul(int a, int b) {
    return int64_t(a) * b % MOD;
}
int power(int a, int64_t b) {
    int res = 1;
    for (; b > 0 ; b >>= 1, a = mul(a, a))
        if (b & 1) res = mul(res, a);
    return res;
}

const int MX = 2e5 + 10;
int fac[MX], invf[MX] ;
void prefact() {
    fac[0] = 1 ;
    for (int i = 1 ; i < MX ; i ++) {
        fac[i] = mul(fac[i - 1], i);
    }
    invf[MX - 1] = power (fac[MX - 1], MOD - 2);
    for (int i = MX - 2 ; i >= 0 ; i --) {
        invf[i] = mul(invf[i + 1], i + 1);
    }
}
int ncr(int N, int R) {
    if (R > N) return 0;
    if (R == 0 || R == N) return 1;
    return mul(fac[N], mul(invf[N - R], invf[R]));
}
const int nax = 2e5 + 10;


int h[nax];
int n;
int cnt[nax];

multiset < pair <int, vector <int>>> setik;

int main() {
    prefact();
    scanf("%d", &n);
    for (int i = 1 ; i <= 2 * n ; ++ i) {
        scanf("%d", h + i);
        cnt[h[i]] += 1;
    }

    for (int i = 1 ; i <= 100000 ; ++ i) {
        if (cnt[i] <= 1) continue;
        vector <int> foo(cnt[i] / 2 + 1);

        int cur = cnt[i];
        int f = 1;

        for (int j = 0 ; j < foo.size() ; ++ j) {
            foo[j] = f;
            f = mul(f, ncr(cur, 2));
            cur -= 2;
        }

        setik.emplace(foo.size(), foo);
    }

    while (setik.size() >= 2) {
        vector <int> p1 = setik.begin()->second;
        setik.erase(setik.begin());
        vector <int> p2 = setik.begin()->second;
        setik.erase(setik.begin());
        p1 = convolution(p1, p2);
        setik.emplace(p1.size(), p1);
    }

    vector <int> c = setik.empty() ? vector<int>(1, 1) : setik.begin()->second;

    if (c.size() <= n) c.resize(n + 2);


    const int INV2 = (MOD + 1) / 2;

    int ans = 0;

    for (int bar = 0 ; bar < c.size() ; ++ bar) {
        int v = c[bar];
        v = mul(v, fac[2 * (n - bar)]);
        v = mul(v, invf[n - bar]);
        v = mul(v, power(INV2, n - bar));
        if (bar % 2 == 0) {
            plusle(ans, v);
        } else minun(ans, v);
    }

    printf("%d\n", ans);

