vector<int> mergetech(vector<vector<int>> &a) {
	priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> q;
	int sz = a.size();
	for(int i = 0; i < sz; i++) {
		q.push({a[i].size(), i});
	}

	for(int i = 0; i < sz - 1; i++) {
		auto c = q.top();
		q.pop();
		auto b = q.top();
		q.pop();
		int k = min(c.second, b.second);
		q.push({b.first + c.first - 1, k});
		a[k] = convolute(a[b.second], a[c.second]);
	}

	return a[0];
}

