		auto b = PQ.top();
		PQ.pop();
		box[a.second] = convolution(box[b.second], box[a.second]);
		box[b.second].clear();
		PQ.push({ box[a.second].size() - 1,a.second });
	}
	long long int ans = 0;
	for (int i = 0; i <= PQ.top().first; i++) {
		if (i & 1) {
			ans += MOD - box[PQ.top().second][i] * by[N * 2 - i * 2] % MOD*rev[N - i] % MOD*power(rev[2], N - i, MOD) % MOD;
		}
		else {
			ans += box[PQ.top().second][i] * by[N * 2 - i * 2] % MOD*rev[N - i] % MOD*power(rev[2], N - i, MOD) % MOD;
		}
	}
	cout << ans % MOD << endl;
}

