using namespace std;
using ll = long long int;
using mint = atcoder::modint998244353;
constexpr int MAX_H = 100000;
constexpr int MAX_N = 50000;
mint f[2 * MAX_N + 1];

mint C(int n, int m) {
    return f[n] * (f[n - m] * f[m]).inv();
}

int main(int, char **) {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> h(2 * n);
    for (int i = 0; i < 2 * n; i++) {
        cin >> h[i];
    }
    f[0] = 1;
    for (int i = 1; i <= MAX_N * 2; i++) {
        f[i] = f[i - 1] * i;
    }

    int cnt[MAX_H + 1] = {0};
    for (int i = 0; i < 2 * n; i++) {
        cnt[h[i]]++;
    }
    vector<vector<mint>> b(MAX_N + 1);
    mint p[MAX_N + 1];
    p[0] = 1;
    for (int i = 1; i <= n; i++) {
        p[i] = p[i - 1] * (2 * i - 1);
    }

    vector<mint> a(1);
    a[0] = 1;

    for (int i = 0; i <= MAX_N; i++) {
        if (cnt[i] < 2) continue;
        if (b[cnt[i]].size() == 0) {
            b[cnt[i]].resize(cnt[i] / 2 + 1);
            for (int j = 0; 2 * j <= cnt[i]; j++) {
                b[cnt[i]][j] = C(cnt[i], 2 * j) * p[j];
            }
        }
        a = atcoder::convolution<mint>(a, b[cnt[i]]);
    }
    int size = a.size();
    mint ans = 0;
    for (int i = 0; i <= n; i++) {
        if ((n - i) >= size) continue;
        ans += p[i] * a[(n - i)] * ((n - i) % 2 == 0 ? 1 : -1);
    }

    cout << ans.val() << endl;
    return 0;
}

