using namespace std;

const int MOD = 998'244'353;
using Mint = atcoder::modint998244353;

template <class T = Mint>  // Usually used over ModInt.
struct Factorials {
  // factorials and inverse factorials.
  vector<T> fact, ifact;

  // n: max cached value.
  Factorials(int n) : fact(n + 1), ifact(n + 1) {
    assert(n < (int)MOD);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
  }

  // Combination (nCk)
  T C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * ifact[k] * ifact[n - k];
  }

  // Permutation (nPk)
  T P(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * ifact[n - k];
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);

  int N;
  cin >> N;
  V<int> H(2 * N);
  cin >> H;
  map<int, int> counts;
  REP(i, 2 * N) { ++counts[H[i]]; }
  Factorials fs(2 * N + 1);
  V<Mint> fact2(N + 1);  // = (2*k-1)!!
  {
    fact2[0] = fact2[1] = 1;
    for (int i = 2; i <= N; ++i) {
      fact2[i] = fact2[i - 1] * (2 * i - 1);
    }
  }

  int num_groups = counts.size();
  deque<V<Mint>> vs(num_groups);
  {
    int i = 0;
    for (auto [_, k] : counts) {
      int m = k / 2 + 1;
      vs[i].resize(m);
      vs[i][0] = 1;
      for (int j = 1; j < m; ++j) {
        vs[i][j] = fs.C(k, 2 * j) * fact2[j];
      }
      ++i;
    }
  }

  // Merge
  while (vs.size() > 1) {
    auto x = vs.front();
    vs.pop_front();
    auto y = vs.front();
    vs.pop_front();
    auto z = atcoder::convolution<>(x, y);
    vs.push_back(z);
  }

  Mint ans = 0;
  for (int i = 0; i < SIZE(vs[0]); ++i) {
    const Mint &x = vs[0][i];
    if (i % 2 == 0) {
      ans += x * fact2[N - i];
    } else {
      ans -= x * fact2[N - i];
    }
  }
  cout << ans.val() << endl;
}

