namespace atcoder {

    struct two_sat {
    public:
        two_sat() : _n(0), scc(0) {}
        two_sat(int n) : _n(n), _answer(n), scc(2 * n) {}

        void add_clause(int i, bool f, int j, bool g) {
            assert(0 <= i && i < _n);
            assert(0 <= j && j < _n);
            scc.add_edge(2 * i + (f ? 0 : 1), 2 * j + (g ? 1 : 0));
            scc.add_edge(2 * j + (g ? 0 : 1), 2 * i + (f ? 1 : 0));
        }
        bool satisfiable() {
            auto id = scc.scc_ids().second;
            for (int i = 0; i < _n; i++) {
                if (id[2 * i] == id[2 * i + 1]) return false;
                _answer[i] = id[2 * i] < id[2 * i + 1];
            }
            return true;
        }
        std::vector<bool> answer() { return _answer; }

    private:
        int _n;
        std::vector<bool> _answer;
        internal::scc_graph scc;
    };

}  // namespace atcoder

const int mod=998244353,MAX=200005,INF=1<<30;

using mint=atcoder::modint998244353;
//using mint=atcoder::modint1000000007;

mint inv[MAX],fac[MAX],finv[MAX];
mint rrr[MAX];

void make(){

    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;

    for(int i=2;i<MAX;i++){
        inv[i]=-inv[mod%i]*(mod/i);
        fac[i]=fac[i-1]*i;
        finv[i]=finv[i-1]*inv[i];
    }

    rrr[1]=1;
    for(int i=3;i<MAX;i+=2) rrr[i]=rrr[i-2]*i;
}

mint comb(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*finv[b]*finv[a-b];
}

mint perm(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*finv[a-b];
}

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    make();

    int N;cin>>N;
    vector<int> cnt(100005);
    for(int i=0;i<2*N;i++){
        int a;cin>>a;
        cnt[a]++;
    }

    vector<mint> ans(1);
    ans[0]=1;

    for(int i=1;i<=100000;i++){
        if(cnt[i]<=1) continue;

        vector<mint> kake(cnt[i]/2+1);
        kake[0]=1;

        for(int j=1;j<si(kake);j++){
            kake[j]=comb(cnt[i],2*j)*rrr[2*j-1];
        }

        vector<mint> c=atcoder::convolution(ans,kake);
        ans=c;
    }

    mint res=0;

    for(int i=0;i<si(ans);i++){
        if(i&1){
            res-=ans[i]*rrr[2*(N-i)-1];
        }else{
            res+=ans[i]*rrr[2*(N-i)-1];
        }
    }

    cout<<res.val()<<endl;
}

