using namespace std;

constexpr int M = 998244353;

class ModComb {
    long long *fact, *facti;
    const int mod;
public:
    explicit ModComb(int n, int m) : mod(m) {
        fact = new long long[n+1];
        facti = new long long[n+1];
        fact[0] = 1; facti[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = (fact[i-1] * i) % m;
        // calc 1/n!
        long long &inv = facti[n], pw = fact[n];
        inv = 1;
        for (int e = mod-2; e > 0; e /= 2) {
            if (e&1) inv = inv * pw % mod;
            pw = pw * pw % mod;
        }
        for (int i = n-1; i > 0; i--) facti[i] = (facti[i+1] * (i+1)) % m;
    }

    ~ModComb() {
        if (fact) delete[] fact;
        if (facti) delete[] facti;
    }

    long long getFact(int n) const {
        return fact[n];
    }

    long long getFactInv(int n) const {
        return facti[n];
    }

    long long getComb(int n, int k) const {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * facti[k] % mod * facti[n-k] % mod;
    }

    long long getPerm(int n, int k) const {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * facti[n-k] % mod;
    }
};

int main() {
    int n; cin >> n;
    ModComb mc(2*n, M);
    vector<int> c(100100, 0);
    for (int i = 0; i < 2*n; i++) {
        int h; cin >> h;
        c[h]++;
    }
    vector<int> f;
    for (int a : c) if (a > 1) f.push_back(a);
    sort(f.begin(), f.end());
    long long df[2*n+1];
    for (int i = 0; i <= 2*n; i++)
        df[i] = i < 2 ? 1 : df[i-2] * i % M;

    priority_queue<pair<int, vector<int> > > pq;
    pq.push({0, {1}});
    for (int a : f) {
        vector<int> v;
        v.push_back(1);
        for (int j = 1; 2*j <= a; j++)
            v.push_back(mc.getComb(a, 2*j) * df[2*j-1] % M);
        pq.push({-v.size(), move(v)});
    }
    while (pq.size() > 1) {
        vector<int> v = move(pq.top().second);
        pq.pop();
        vector<int> w = move(pq.top().second);
        pq.pop();
        vector<int> u = atcoder::convolution(v, w);
        pq.push({-u.size(), u});
    }
    vector<int> H = pq.top().second;
    long long ans = 0;
    for (int k = 0; k < H.size(); k++) {
        ans += (k % 2 ? -1 : 1) * df[2*(n-k)-1] * H[k] % M;
    }
    cout << (ans % M + M) % M << endl;
}

