vi rev;  // NOTICE: 2^18 = 262144 2^20 = 1048576 2^21 = 2097152
inline int init_ntt(int lena, int lenb) {
    int n = getlen(lena + lenb - 1);
    int l = 31 - __builtin_clz(n);
    rev.resize(n);
    rep(i, 0, n) rev[i] = (rev[i >> 1] | (i & 1) << l) >> 1;
    return n;
}
void ntt(VL& a, int op) {
    int n = sz(a);
    rep(i, 0, n) if (i < rev[i]) swap(a[i], a[rev[i]]);
    for (int k = 1; k < n; k <<= 1) {
        mint wn = mint(groot).pow( (nttmod - 1) / (k << 1) );
        for (int i = 0; i < n; i += (k << 1)) { mint w = 1; rep(j, 0, k) {
                mint u = a[i | j], v = w * a[i | j | k] ;
                a[i | j] = u + v, a[i | j | k] = u - v ;
                w = w * wn ;
    } } }
    if(op == -1) {
        reverse(1 + all(a));
        mint sinv = mint(n).inv();
        rep(i, 0, n) a[i] = a[i] * sinv ;
    }
}
VL conv(const VL& a, const VL& b) {
    if (a.empty() || b.empty()) return {};
    int n = init_ntt(sz(a), sz(b));
    VL L(a), R(b), out(n);
    L.resize(n), R.resize(n);
    ntt(L, 1), ntt(R, 1);
    rep(i, 0, n) out[i] = L[i] * R[i] ;
    ntt(out, -1);
    return {out.begin(), out.begin() + sz(a) + sz(b) - 1};
}

