VL Inv(VL& f, int n)
{
    if (n == 1) return {f[0].inv()};
    VL g = Inv(f, (n + 1) >> 1);
    VL ff = VL(f.begin(), f.begin() + min(sz(f), n));
    int nn = init_ntt(n, n);
    ff.resize(nn), g.resize(nn);
    ntt(ff, 1), ntt(g, 1);
    for (int i = 0; i < nn; ++i) g[i] = (2 - ff[i] * g[i]) * g[i];
    ntt(g, -1);
    g.resize(n);
    return g;
}

