  MinHeap<pair<int, int>> H;
  for (int i = 0; i < cs.size(); i++) {
    int c = cs[i];
    for (int j = 0; 2 * j <= c; j++) b[i].push_back(func(c, j).val);
    // dmp(b[i]);
    H.push(make_pair((int)b[i].size(), i));
    // dmp(b);
