    // dmp(b[q.second]);
    b[p.second] = atcoder::convolution<998244353>(b[p.second], b[q.second]);
    // dmp(b[p.second]);
    H.push(make_pair((int)b[p.second].size(), p.second));
  }
  assert(H.size() <= 1);
  vector<ll> ans;
  if (H.size() == 1)
    ans = b[H.top().second];
  else
    ans = vector<ll>(1, 1ll);
  // dmp(ans);
  mint answer(0);
