int get_premitive_root() {
	int primitive_root = 0;
	if (!primitive_root) {
		primitive_root = [&]() {
			set<int> fac;
			int v = mod - 1;
			for (ll i = 2; i * i <= v; i++) while (v % i == 0) fac.insert(i), v /= i;
			if (v > 1) fac.insert(v);
			for (int g = 1; g < mod; g++) {
				bool ok = true;
				for (auto i : fac) if (mod_pow(g, (mod - 1) / i) == 1) { ok = false; break; }
				if (ok) return g;
			}
			return -1;
		}();
	}
	return primitive_root;
}
const int proot = get_premitive_root();

typedef vector <modint> poly;
void dft(poly& f, bool inverse = false) {
	int n = f.size(); if (n == 1)return;

	static poly w{ 1 }, iw{ 1 };
	for (int m = w.size(); m < n / 2; m *= 2) {
		modint dw = mod_pow(proot, (mod - 1) / (4 * m)), dwinv = (modint)1 / dw;
		w.resize(m * 2); iw.resize(m * 2);
		for (int i = 0; i < m; i++)w[m + i] = w[i] * dw, iw[m + i] = iw[i] * dwinv;
	}
	if (!inverse) {
		for (int m = n; m >>= 1;) {
			for (int s = 0, k = 0; s < n; s += 2 * m, k++) {
				for (int i = s; i < s + m; i++) {
					modint x = f[i], y = f[i + m] * w[k];
					f[i] = x + y, f[i + m] = x - y;
				}
			}
		}
	}
	else {
		for (int m = 1; m < n; m *= 2) {
			for (int s = 0, k = 0; s < n; s += 2 * m, k++) {
				for (int i = s; i < s + m; i++) {
					modint x = f[i], y = f[i + m];
					f[i] = x + y, f[i + m] = (x - y) * iw[k];
				}
			}
		}
		modint n_inv = (modint)1 / (modint)n;
		for (modint& v : f)v *= n_inv;
	}
}
poly multiply(poly g, poly h) {
	int n = 1;
	int pi = 0, qi = 0;
	rep(i, g.size())if (g[i])pi = i;
	rep(i, h.size())if (h[i])qi = i;
	int sz = pi + qi + 2;
	while (n < sz)n *= 2;
	g.resize(n); h.resize(n);
	dft(g); dft(h);
	rep(i, n) {
		g[i] *= h[i];
	}
	dft(g, true);
	return g;
}

modint cntp[1 << 18];

void solve() {
	int n; cin >> n; n *= 2;
	cntp[0] = 1;
	cntp[2] = 1;
	for (int i = 4; i <= n; i += 2) {
		cntp[i] = cntp[i - 2] * (modint)(i - 1);
	}
	vector<int> h(n);
	rep(i, n) {
		cin >> h[i];
	}
	sort(all(h));
	vector<int> cs;
	rep(i, n) {
		int le = i;
		while (i + 1 < n && h[i] == h[i + 1])i++;
		cs.push_back(i - le + 1);
	}
	sort(all(cs));
	vector<poly> vs;
	vector<int> szs;
	set<P> st;
	rep(i, cs.size()) {
		poly z;
		for (int j = 0; j <= cs[i]; j += 2) {
			modint sum = comb(cs[i], j) * cntp[j];
			z.push_back(sum);
		}
		vs.push_back(z);
		szs.push_back(z.size());
	}
	rep(i, cs.size()) {
		st.insert({ szs[i],i });
	}
	while (st.size() > 1) {
		P pl = (*st.begin()); st.erase(st.begin());
		P pr = (*st.begin()); st.erase(st.begin());
		int lid = pl.second;
		int rid = pr.second;
		vs[lid] = multiply(vs[lid], vs[rid]);
		vs[rid].clear(); vs[rid].shrink_to_fit();
		szs[lid] = vs[lid].size();
		st.insert({ szs[lid],lid });
	}
	poly x = vs[(*st.begin()).second];
	modint ans = 0;
	rep(i, x.size()) {
		if (n - 2 * i < 0)continue;
		modint sum = x[i] * cntp[n - 2 * i];
		if (i % 2 == 0)ans += sum;
		else ans -= sum;
		//cout << i<<" "<<x[i]<<" "<<cntp[n-2*i] << "\n";
	}
	cout << ans << "\n"; 
}

