  struct Value { virtual ~Value() = default; };
  template <const int P> struct Mint : Value { int v;
    inline int trim(int _v) { return (_v % P + P) % P; }
    Mint (int _v = 0) : v(trim(_v)) { }
    bool operator == (const Mint &m) const { return v == m.v; }
    bool operator != (const Mint &m) const { return v != m.v; }
    bool operator < (const Mint &m) const { return v < m.v; }
    bool operator <= (const Mint &m) const { return v <= m.v; }
    bool operator > (const Mint &m) const { return v > m.v; }
    bool operator >= (const Mint &m) const { return v >= m.v; }
    friend bool operator == (const int &a, const Mint &m) { return Mint(a) == m.v; }
    friend bool operator != (const int &a, const Mint &m) { return Mint(a) != m.v; }
    friend bool operator < (const int &a, const Mint &m) { return Mint(a) < m.v; }
    friend bool operator <= (const int &a, const Mint &m) { return Mint(a) <= m.v; }
    friend bool operator > (const int &a, const Mint &m) { return Mint(a) > m.v; }
    friend bool operator >= (const int &a, const Mint &m) { return Mint(a) >= m.v; }
    Mint& operator += (const Mint &m) { v = trim(v + m.v); return *this; }
    Mint operator + (const Mint &m) const { Mint t = *this; return t += m; }
    friend Mint operator + (const int &a, const Mint &m) { return Mint(a) + m; }
    Mint& operator ++()  { return *this += 1; }
    Mint operator ++(int) { Mint t = *this; ++*this; return t; }
    Mint operator - () const { return Mint(-v); }
    Mint& operator -= (const Mint &m) { v = trim(v - m.v); return *this; }
    Mint operator - (const Mint &m) const { Mint t = *this; return t -= m; }
    friend Mint operator - (const int &a, const Mint &m) { return Mint(a) - m; }
    Mint& operator --()  { return *this -= 1; }
    Mint operator --(int) { Mint t = *this; --*this; return t; }
    Mint& operator *= (const Mint &m) { v = trim(1ll * v * m.v % P); return *this; }
    Mint operator * (const Mint &m) const { Mint t = *this; return t *= m; }
    friend Mint operator * (const int &a, const Mint &m) { return Mint(a) * m; }
    Mint pow(long long n) const { Mint m = *this, ans = 1; while (n) ans *= (n & 1 ? m : 1), m *= m, n >>= 1; return ans; }
    Mint pow(const Mint &n) const { return pow(n.v); }
    Mint inv() const { return pow(P - 2); }
    Mint& operator /= (const Mint &m) { *this = v * m.inv(); return *this; }
    Mint operator / (const Mint &m) { Mint t = *this; return t /= m; }
    friend Mint operator / (const int &a, const Mint &m) { return Mint(a) / m; }
    friend istream& operator >> (istream &in, Mint &m) { int v; in >> v; m = Mint(v); return in; }
    friend ostream& operator << (ostream &out, const Mint &m) { out << m.v; return out; }
  };
  template <typename T> T add(T a, T b) { return a + b; }
  template <typename T> T max(T a, T b) { return a < b ? b : a; }
  template <typename T> T min(T a, T b) { return a < b ? a : b; }
  unordered_map<int, vector<Value*>> fact_mp, inv_mp, fact_inv_mp;
  template <const int P> void _build(int n);
  template <const int P> Mint<P> fact(int n) {
    assert(0 <= n); _build<P>(n);
    auto &_fact = fact_mp[P];
    return *dynamic_cast<Mint<P>*>(_fact[n]);
  }
  template <const int P> Mint<P> fact_inv(int n) {
    assert(0 <= n); _build<P>(n);
    auto &_fact_inv = fact_inv_mp[P];
    return *dynamic_cast<Mint<P>*>(_fact_inv[n]);
  }
  template <const int P> Mint<P> C(int n, int m) {
    assert(0 <= n && m >= 0 && m <= n); _build<P>(n);
    return fact<P>(n) * fact_inv<P>(m) * fact_inv<P>(n - m);
  }
  template <const int P> Mint<P> inv(int n) {
    assert(0 <= n); _build<P>(n);
    auto &_inv = inv_mp[P];
    return *dynamic_cast<Mint<P>*>(_inv[n]);
  }
  template <const int P> void _build(int n) {
    auto &_fact = fact_mp[P];
    auto &_inv = inv_mp[P];
    auto &_fact_inv = fact_inv_mp[P];
    while ((int)_fact.size() <= n) {
      if ((int)_fact.size() <= 1) {
        _fact.push_back(new Mint<P>(1));
        _inv.push_back(new Mint<P>(1));
        _fact_inv.push_back(new Mint<P>(1));
        continue;
      }
      int x = _fact.size();
      _fact.push_back(new Mint<P>(fact<P>(x - 1) * x));
      _inv.push_back(new Mint<P>(-inv<P>(P % x) * Mint<P>(P / x)));
      _fact_inv.push_back(new Mint<P>(fact_inv<P>(x - 1) * inv<P>(x)));
    }
  }
  template <const int P = MOD998, const int R = 3, const int MAXN = (1 << 23)> struct Poly : vector<Mint<P>> {
    Poly (int n) { this->resize(n); }
    int extend(int x) { int N = 1; while (N < x) N <<= 1; return N; }
    Poly operator * (const Poly &rhs) {
      Poly a = *this, b = rhs;
      int N = extend(a.size() + b.size() - 1);
      a.resize(N); a.ntt(1);
      b.resize(N); b.ntt(1);
      for (int i = 0 ; i < N ; i++) a[i] *= b[i];
      return a.ntt(-1), a.resize(this->size() + rhs.size()), a;
    }
    void ntt(int op) { static vector<int> r(MAXN);
      int n = this->size();
      for (int i = 0 ; i < n ; i++) {
        r[i] = (i & 1) * (n >> 1) + (r[i >> 1] >> 1);
        if (r[i] < i) std::swap(this->at(i), this->at(r[i]));
      }
      for (int m = 2 ; m <= n ; m <<= 1) {
        int k = m >> 1; Mint<P> gn = Mint<P>(R).pow((P - 1) / m);
        for (int i = 0 ; i < n ; i += m) { Mint<P> g = 1;
          for (int j = 0 ; j < k ; j++, g *= gn) {
            Mint<P> tmp = this->at(i + j + k) * g;
            this->at(i + j + k) = this->at(i + j) - tmp;
            this->at(i + j) = this->at(i + j) + tmp;
          }
        }
      }
      if (op == -1) {
        reverse(this->begin() + 1, this->end());
        Mint<P> inv = Mint<P>(n).inv();
        for (int i = 0 ; i < n ; i++)
          this->at(i) *= inv;
      }
    }
    bool operator < (const Poly &rhs) const {
      return this->size() > rhs.size();
    }
  };
