namespace FFT // taken from https://www.codechef.com/viewsolution/11939789
{
#define fore(i, a, b) for(int i = (int)(a); i <= (int)(b); ++i)
#define forn(i, n) for(int i = 0; i < (int)(n); ++i)
typedef long double ld;
struct base
{
    typedef long double T;
    T re, im;
    base() :re(0), im(0) {}
    base(T re) :re(re), im(0) {}
    base(T re, T im) :re(re), im(im) {}
    base operator + (const base& o) const
    {
        return base(re + o.re, im + o.im);
    }
    base operator - (const base& o) const
    {
        return base(re - o.re, im - o.im);
    }
    base operator * (const base& o) const
    {
        return base(re * o.re - im * o.im, re * o.im + im * o.re);
    }
    base operator * (ld k) const
    {
        return base(re * k, im * k) ;
    }
    base conj() const
    {
        return base(re, -im);
    }
};
const int N = 20;
const int MAXN = (1<<N);
base w[MAXN];
base f1[MAXN];
int rev[MAXN];
void build_rev(int k)
{
    static int rk = -1;
    if( k == rk )return ;
    rk = k;
    fore(i, 1, (1<<k) )
    {
        int j = rev[i-1], t = k-1;
        while( t >= 0 && ((j>>t)&1) )
        {
            j ^= 1 << t;
            --t;
        }
        if( t >= 0 )
        {
            j ^= 1 << t;
            --t;
        }
        rev[i] = j;
    }
}
void fft(base *a, int k)
{
    build_rev(k);
    int n = 1 << k;
    forn(i, n) if( rev[i] > i ) swap(a[i], a[rev[i]]);
    for(int l = 2, lll = 1; l <= n; l += l, lll += lll)
    {
        if( w[lll].re == 0 && w[lll].im == 0 )
        {
            ld angle = PI_m / lll;
            base ww( cosl(angle), sinl(angle) );
            if( lll > 1 ) for(int j = 0; j < lll; ++j)
                {
                    if( j & 1 ) w[lll + j] = w[(lll+j)/2] * ww;
                    else w[lll + j] = w[(lll+j)/2];
                }
            else w[lll] = base(1, 0);
        }
        for(int i = 0; i < n; i += l) forn(j, lll)
        {
            base v = a[i + j], u = a[i + j + lll] * w[lll + j];
            a[i + j] = v + u;
            a[i + j + lll] = v - u;
        }
    }
}
vector<int> mul(const vector<int>& a, const vector<int>& b)
{
    int k = 1;
    while( (1<<k) < (a.size() + b.size()) ) ++k;
    int n = (1<<k);
    forn(i, n) f1[i] = base(0,0);
    forn(i, a.size()) f1[i] = f1[i] + base(a[i], 0);
    forn(i, b.size()) f1[i] = f1[i] + base(0, b[i]);
    fft(f1, k);
    forn(i, 1 + n/2)
    {
        base p = f1[i] + f1[(n-i)%n].conj();
        base _q = f1[(n-i)%n] - f1[i].conj();
        base q(_q.im, _q.re);
        f1[i] = (p * q) * 0.25;
        if( i > 0 ) f1[(n - i)] = f1[i].conj();
    }
    forn(i, n) f1[i] = f1[i].conj();
    fft(f1, k);
    vector<int> r(a.size() + b.size());
    forn(i, r.size() )
    {
        r[i] = ll (f1[i].re / n + 0.5) % MOD;
    }
    return r;
}
}



inline ll add(ll a, ll b) {
  a += b;
  if (a >= md) a -= md;
  return a;
}

inline ll sub(ll a, ll b) {
  a -= b;
  if (a < 0) a += md;
  return a;
}

inline ll mul(ll a, ll b) {
  return (ll) ((long long)((a%md) * (b%md)) % md);
}

inline ll power(ll a, long long b) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) {
      res = mul(res, a);
    }
    a = mul(a, a);
    b >>= 1;
  }
  return res;
}

inline ll inv(ll a) {
  a %= md;
  if (a < 0) a += md;
  ll b = md, u = 0, v = 1;
  while (a) {
    ll t = b / a;
    b -= t * a; swap(a, b);
    u -= t * v; swap(u, v);
  }
  assert(b == 1);
  if (u < 0) u += md;
  return u;
}

vector<int> fact(maxn+5);
void init (int n)
{
  fact[0] = 1;
  for(int i = 1;i<=n;i++)
  {
    fact[i] = mul(i,fact[i-1]);
  }
}
int nck(int n,int k)
{
  return mul(fact[n],mul(inv(fact[k]),inv(fact[n-k])));
}

vector<vector<int>> v;
vector<int> solve(int l, int r){
  if(l == r)
    return v[l];
  int mid = (l+r)>>1;
  vector<int> a = solve(l,mid);
  vector<int> b = solve(mid+1,r);
  return FFT::mul(a,b);
}

