using namespace atcoder;
int main(){
    setIO("");
//    freopen("file.out", "r", stdin);
    int n; re(n);
    vi h(2*n);
    f0r(i, 2*n) re(h[i]);
    n *= 2;
    sort(all(h));
    vmi fact(n+5);
    vmi ifact(n+5);
    fact[0] = ifact[0] = 1;
    f1r(i, 1, n+5){
        fact[i] = fact[i-1]*i;
        ifact[i] = ifact[i-1]/i;
    }
    auto choose = [&](int x, int y) -> mi {
        if(x<y) return 0;
        return fact[x]*ifact[x-y]*ifact[y];
    };
    map<int, int> cnt;
    f0r(i, n){
        cnt[h[i]]++;
    }
    vector<ll> res(1);
    res[0] = 1;
    multiset<pair<int, vl>> tmp;
    tmp.ins({1, res});
    for(auto x: cnt){
        int num = x.s;
        if(num==1)continue;
        vector<ll> use(num/2+1);
        int cur = num;
        mi run = 1;
        f0r(i, num/2+1){
            use[i] = (run*ifact[i]).val;
            run *= choose(cur,2);
            cur -= 2;
        }
        tmp.ins({sz(use), use});
    }
    while(sz(tmp)>=2){
        vector<ll> c = convolution<MOD>((*tmp.begin()).s, (*(next(tmp.begin()))).s);
        tmp.erase(tmp.begin());
        tmp.erase(tmp.begin());
        tmp.emplace(sz(c), c);
    }
    res = (*tmp.begin()).s;
    mi ans = 0;
    vmi comp(n+1);
    mi run = 1;
    for(int i = 0; i <= n; i += 2){
        comp[i] = run * ifact[i/2];
        run *= choose(i+2,2);
    }
    f0r(i, sz(res)){
        int num = n-2*i;
        ans += res[i]*comp[num]*(i%2==0?1:-1);
    }
    ps(ans);
    return 0;
}

