		if(co[i] == 1) {
			dp = NTT.multiply(dp, v);
			continue;
		}
		vector<ll> u(1, 1);
		while(co[i] > 0) {
			if(co[i] & 1) u = NTT.multiply(u, v);
			v = NTT.multiply(v, v);
			co[i] >>= 1;
		}
		dp = NTT.multiply(dp, u);
    }
	// cerr << dp[0] << " " << dp[1] << " " << dp[2] << endl;
	// cerr << ans << endl;
    for(int i = 1; i <= n; ++ i) {
        if(i % 2 == 1) {
            ans = ans + MOD - dp[i] * cc[2 * n - 2 * i] % MOD * finv[n - i] % MOD;
            ans %= MOD;
        } else {
            ans = ans + dp[i] * cc[2 * n - 2 * i] % MOD * finv[n - i] % MOD;
            ans %= MOD;
        }
    }
    cout << ans % MOD << endl;
}

