template<int X>
struct NTT{
  static constexpr int md = bmds(X);
  static constexpr int rt = brts(X);
  using M = ModInt<md>;
  vector< vector<M> > rts,rrts;

  void ensure_base(int n){
    if((int)rts.size()>=n) return;
    rts.resize(n);rrts.resize(n);
    for(int i=1;i<n;i<<=1){
      if(!rts[i].empty()) continue;
      M w=M(rt).power((md-1)/(i<<1));
      M rw=w.inverse();
      rts[i].resize(i);rrts[i].resize(i);
      rts[i][0]=M(1);rrts[i][0]=M(1);
      for(int k=1;k<i;k++){
        rts[i][k]=rts[i][k-1]*w;
        rrts[i][k]=rrts[i][k-1]*rw;
      }
    }
  }

  void ntt(vector<M> &as,bool f){
    int n=as.size();
    assert((n&(n-1))==0);
    ensure_base(n);

    for(int i=0,j=1;j+1<n;j++){
      for(int k=n>>1;k>(i^=k);k>>=1);
      if(i>j) swap(as[i],as[j]);
    }

    for(int i=1;i<n;i<<=1){
      for(int j=0;j<n;j+=i*2){
        for(int k=0;k<i;k++){
          M z=as[i+j+k]*(f?rrts[i][k]:rts[i][k]);
          as[i+j+k]=as[j+k]-z;
          as[j+k]+=z;
        }
      }
    }

    if(f){
      M tmp=M(n).inverse();
      for(int i=0;i<n;i++) as[i]*=tmp;
    }
  }

  vector<M> multiply(vector<M> as,vector<M> bs){
    int need=as.size()+bs.size()-1;
    int sz=1;
    while(sz<need) sz<<=1;
    as.resize(sz,M(0));
    bs.resize(sz,M(0));

    ntt(as,0);ntt(bs,0);
    for(int i=0;i<sz;i++) as[i]*=bs[i];
    ntt(as,1);

    as.resize(need);
    return as;
  }

  vector<int> multiply(vector<int> as,vector<int> bs){
    vector<M> am(as.size()),bm(bs.size());
    for(int i=0;i<(int)am.size();i++) am[i]=M(as[i]);
    for(int i=0;i<(int)bm.size();i++) bm[i]=M(bs[i]);
    vector<M> cm=multiply(am,bm);
    vector<int> cs(cm.size());
    for(int i=0;i<(int)cs.size();i++) cs[i]=cm[i].x;
    return cs;
  }
};
template<int X> constexpr int NTT<X>::md;
template<int X> constexpr int NTT<X>::rt;

int M=100000;
int n;
int h[100010];
int z[100010];
vector<modint> f[100000];
ModFac MF(200010);
modint v[100010];

modint gr(int k,int j){
    return MF.comb(k,2*j)*v[2*j]*MF.inv_factorial(j);
}

void solve(){
    cin >> n;
    v[0]=1;
    rep(i,n){
        v[2*i+2]=v[2*i]*MF.comb(2*(i+1),2);
    }
    rep(i,2*n){
        cin >> h[i];h[i]--;
        z[h[i]]++;
    }
    rep(i,M){
        f[i].resize(z[i]/2+1);
        rep(j,z[i]/2+1){
            f[i][j]=gr(z[i],j);
        }
    }
    sort(f,f+M,[](vector<modint> &a,vector<modint> &b){return a.size()<b.size();});
    vector<modint> F={1};
    NTT<2> ntt;
    rep(i,M){
        F=ntt.multiply(F,f[i]);
    }
    F.resize(n+1);
    vector<modint> G(n+1);
    G[n]=F[n];
    per(i,n){
        G[i]=F[i]*v[2*n-2*i]*MF.comb(n,i)-(modint)(i+1)*G[i+1];
    }
    // rep(i,n+1){
    //     cout << i << " " << G[i] << " " << F[i] << endl;
    // }
    cout << G[0]*MF.inv_factorial(n) << endl;
}

