    rep(i, 2 * n) {
        cnt[h[i]] ++;
    }
    static int co[100100];
    rep(i, 100100) co[i] = 0;
    rep(i, 100100) {
        co[cnt[i]] ++;
    }
    static ll cc[200200];
    rep(i, 200200) cc[i] = 0;
    cc[0] = 1;
    for(int i = 2; i <= 2 * n; i += 2) {
        cc[i] = cc[i - 2] * com(i, 2) % MOD;
    }
    ll ans = cc[2 * n] * finv[n] % MOD;
    vector<int> dp(100200, 0);
    dp[0] = 1;
    for(int i = 2; i <= 2 * n; ++ i) {
        if(co[i] == 0) continue;
        int k = i / 2;
		vector<ll> v(k + 1);
		v[0] = 1LL;
        for(int j = 1; j <= k; ++ j) {
            v[j] = v[j - 1] * fact[j - 1] % MOD * com(i + 2 - j * 2, 2) % MOD * finv[j] % MOD;
        }
		rep(j, co[i]) {
			dp = NTT.multiply(dp, v);
		}
    }
	// cerr << dp[0] << " " << dp[1] << " " << dp[2] << endl;
	// cerr << ans << endl;
    for(int i = 1; i <= n; ++ i) {
        if(i % 2 == 1) {
            ans = ans + MOD - dp[i] * cc[2 * n - 2 * i] % MOD * finv[n - i] % MOD;
            ans %= MOD;
        } else {
            ans = ans + dp[i] * cc[2 * n - 2 * i] % MOD * finv[n - i] % MOD;
            ans %= MOD;
        }
    }
    cout << ans % MOD << endl;
}

