  public:
    semifactorial(int N): data_(N + 1, 1){
      for(int i = 2; i <= N; i += 2) data_[i] = data_[i - 2] * i;
      for(int i = 3; i <= N; i += 2) data_[i] = data_[i - 2] * i;
    }

