struct Poly {
	vector<int> a;
	void NTT(int op, int len) {
		for (int i = 0; i < len; i++)
			if (i < r[i]) swap(a[i], a[r[i]]);
		for (int L = 2; L <= len; L <<= 1) {
			int p = L >> 1, g = op?power(3, (mod-1)/L):power(3,mod-1-(mod-1)/L);
			for (int i = 0; i < len; i += L) {
				int now = 1;
				for (int j = i; j < i + p; j++) {
					int tmp = 1ll*now*a[j+p]%mod;
					a[j+p] = (mod+a[j]-tmp)%mod;
					a[j] = (a[j]+tmp)%mod;
					now = 1ll*now*g%mod;
				}
			}
		}
		if (!op) {
			int invlen = power(len, mod-2);
			for (int i = 0; i < len; i++) a[i] = 1ll*a[i]*invlen%mod;
		}
	}
	int size() {
		return a.size();
	}
	int& operator[](int n) {
		return a[n];
	}
	void resize(int n) {
		while (a.size() < n) a.push_back(0);
		while (a.size() > n) a.pop_back();
	}
	void push_back(int n) {
		a.push_back(n);
	}
};
Poly operator*(Poly a, Poly b) {
	int la = a.size(), lb = b.size();
	int len = la + lb - 1, bac = len;
	while (len != (len&-len)) len += len & -len;
	a.resize(len), b.resize(len);
	for (int i = 1; i < len; i++) r[i] = (r[i>>1]>>1)|(i&1?len>>1:0);
	a.NTT(1, len), b.NTT(1, len);
	for (int i = 0; i < len; i++) a[i] = 1ll*a[i]*b[i]%mod;
	a.NTT(0, len);
	a.resize(bac);
	return a;
}
int inv[100001];
Poly v[100001];
Poly solve(int l, int r) {
	if (l == r) return v[l];
	int mid = (l + r) / 2;
	Poly l0 = solve(l, mid), r0 = solve(mid + 1, r);
	return l0 * r0;
}
