ll kaikai[100010];
void make_kaikai(){
  kaikai[0] = 1;
  kaikai[1] = 1;
  for(int i = 2; i < 100010; i++){
    kaikai[i] = kaikai[i-2] * i % MOD;
  }
}

ll N;
