ll cnt[100010];
vector<ll> A;

vector<ll> merge(vector<vector<ll>>& B){
  int n = len(B);
  if(n == 1){
    return B[0];
  }
  vector<vector<ll>> L, R;
  rep(i, n){
    if(i & 1) L.pb(B[i]);
    else R.pb(B[i]);
  }
  vector<ll> left = merge(L);
  vector<ll> right = merge(R);
  vector<ll> res = atcoder::convolution(left, right);
  return res;
}

void solve(){
  COMinit();
  make_kaikai();
  cin >> N;
  rep(i, 2*N) cin >> h[i];
  rep(i, 2*N) cnt[h[i]]++;

  rep(i, 100010){
    if(cnt[i] != 0) A.pb(cnt[i]);
  }


  vector<vector<ll>> B;
  rep(i, len(A)){
    vector<ll> a;
    rep(j, A[i]/2+1){
      //jペア
      a.pb(comb(A[i], 2*j) * kaikai[max(2*j-1, 0)]);
    }
    B.pb(a);
  }
  vector<ll> C = merge(B);

  ll ans = 0;
  rep(i, len(C)){
    if(i & 1) ans += MOD - C[i] * kaikai[max(2*N-i*2-1, 0LL)] % MOD;
    else ans += C[i] * kaikai[max((2*N-i*2-1), 0LL)] % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

