int solve(){
    vector<modint> fact(2*N+1), revfact(2*N+1), odd_fact(2*N+1);
    fact[0] = fact[1] = 1;
    for (int i = 0; i < 2*N; i++) fact[i+1] = fact[i]*(i+1);
    revfact[2*N] = fact[2*N].inv();
    for (int i = 2*N-1; i >= 0; i--) revfact[i] = revfact[i+1]*(i+1);
    // odd_fact[i] = (2*i-1)!!
    odd_fact[0] = 1;
    for (int i = 0; i < 2*N; i++) odd_fact[i+1] = odd_fact[i]*(2*i+1);
    auto combi = [&](int n, int k){ return fact[n]*revfact[n-k]*revfact[k];};
    // modint ans = fact[2*N]*revfact[N]*modint(2).pow(N).inv();
    map<int, int> cnt;
    for(auto h:H) cnt[h]++;
    vector<ll> nums;
    for(auto [h,c]:cnt) nums.emplace_back(c);
    int K = nums.size();
    sort(nums.begin(),nums.end());
    deque<vector<modint> > q;
    for (int k = 0; k < K; k++)
    {
        ll n = nums[k];
        vector<modint> tmp;
        for (int i = 0; 2*i <= n; i++)
        {
            // tmp.push_back(fact[n]*revfact[i]*revfact[n-2*i]*modint(2).pow(i).inv());
            tmp.push_back(combi(n,2*i)*odd_fact[i]);
        }
        q.push_back(tmp);
    }
    auto cmp = [](vector<modint> a, vector<modint> b){return a.size() < b.size();};
    sort(q.begin(), q.end(), cmp);

    while(q.size()>1){
        vector<modint> c = atcoder::convolution(q[0], q[1]);
        q.push_back(c);
        q.pop_front();
        q.pop_front();
    }

    vector<modint> pair_coff = q.front();
    modint ans = 0;
    // 同じグループ内のペアを少なくともk個つくる、でほう助原理をつかう。
    for (int k = 0; k < (int)pair_coff.size(); k++)
    {
        modint ans_k = pair_coff[k]*odd_fact[N-k];
        if(k%2) ans -= ans_k;
        else ans += ans_k;
    }
    cout << ans.val() << "\n";
    return 0;
}   

