int main()
{
    constexpr uint mod = 998244353;
    using mint         = modint<mod>;
    const auto N       = in.val<int>();
    constexpr int H    = 100000;
    std::vector<int> ns(H, 0);
    for (int i = 0; i < 2 * N; i++) { ns[in.val<int>(1)]++; }
    std::vector<mint> ips(N + 1, 1);
    for (int i = 1; i <= N; i++) { ips[i] = ips[i - 1] / 2; }

    auto comp = [&](const auto& f1, const auto& f2) { return f1.size() > f2.size(); };
    std::priority_queue<std::vector<mint>, std::vector<std::vector<mint>>, decltype(comp)> Q(comp);
    Q.push({1});
    for (int h = 0; h < H; h++) {
        const int n = ns[h];
        if (n <= 1) { continue; }
        std::vector<mint> f;
        for (int l = 0; 2 * l <= n; l++) { f.push_back(mint::comb(n, 2 * l) * mint::fact(2 * l) * mint::inv_fact(l) * ips[l]); }
        Q.push(f);
    }
    while (Q.size() >= 2) {
        const auto f1 = Q.top();
        Q.pop();
        const auto f2 = Q.top();
        Q.pop();
        Q.push(ntt<mod, 3>::convolute(f1, f2));
    }
    const auto dp = Q.top();
    mint ans      = 0;
    for (int l = 0; l < (int)dp.size(); l++) {
        const int p    = N - l;
        const mint way = mint::fact(2 * p) * mint::inv_fact(p) * ips[p];
        SHOW(l, way);
        ans += (l % 2 == 0 ? 1 : -1) * way * dp[l];
    }
    SHOW(dp);
    out.ln(ans);
    return 0;
}

