class FHeightsAndPairs {
public:

    vector<mint> get_vec(int n) {
      vector<mint> ret;
      ret.emplace_back(1);
      while(n >= 2) {
        ret.push_back(ret.back());
        ret.back() *= n*(n-1)/2;
        n -= 2;
      }
      return ret;
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;
      vector<int> a(2*n);
      vector<int> posa(100000);
      rep(i, 2*n) {
        cin >> a[i];
        a[i]--;
        posa[a[i]]++;
      }
      vector<int> v;
      rep(i, 100000) {
        if (posa[i] >= 1) {
          v.push_back(posa[i]);
        }
        if (posa[i] > n) {
          cout << 0 << endl;
          return;
        }
      }

      vector<mint> dp[v.size()];
      priority_queue<P, vector<P>, greater<>> que;
      rep(i, v.size()) {
        dp[i] = get_vec(v[i]);
        debug(i, dp[i].size());
        que.emplace(dp[i].size(), i);
      }

      while(que.size() >= 2) {
        auto p = que.top(); que.pop();
        auto q = que.top(); que.pop();
        int newPos = q.second;
        dp[newPos] = convolution(dp[p.second], dp[q.second]);
        que.emplace(dp[newPos].size(), newPos);
      }

      mint ans = 0;
      auto r = que.top();
      auto& ret = dp[r.second];
      vector<mint> pairs(n);
      pairs[0] = 1;
      for(int i=1; i<n; i++) {
        pairs[i] = pairs[i-1] * (i*2+1);
      }

      for(int i=0; i<ret.size(); i++) {
        mint now = ret[i];
        debug(i, now.val());
        if (i%2!=0) {
          now *= -1;
        }
        now *= pairs[n-1-i];
        ans += now;
      }
      cout << ans.val() << endl;
    }
};

