  using Mint = ModInt<998244353>;
  using FPS = FormalPowerSeries<Mint>;
  using Comb = Combination<Mint>;
  Comb::init(100000);
  int N;
  cin >> N;
  for (int i = 0; i < 2 * N; i++) {
    int h;
    cin >> h;
    cnt[h]++;
  }
  vector<FPS> fs;
  for (int i = 1; i < M; i++) {
    if (cnt[i] <= 1) continue;
    int m = cnt[i] / 2;
    FPS g(m + 1);
    for (int j = 0; j <= m; j++) {
      g[j] = Comb::nCr(cnt[i], 2 * j) * Comb::nPr(2 * j, j) / Mint(2).pow(j);
    }
    fs.emplace_back(g);
  }
  int n = fs.size();
  debug(n);
  int pw = 1;
  while (pw < n) pw *= 2;
  debug(pw);
  vector<FPS> buf(pw * 2, FPS({1}));
  for (int i = 0; i < n; i++) {
    buf[pw + i] = fs[i];
  }
  for (int i = pw - 1; i > 0; i--) {
    buf[i] = (buf[2 * i] * buf[2 * i + 1]).pre(N + 1);
  }
  auto h = buf[1];
  h.resize(N + 1, 0);
  Mint ans = 0;
  for (int i = 0; i <= N; i++) {
    Mint tmp = h[i] * Comb::nPr(2 * N - 2 * i, N - i) / Mint(2).pow(N - i);
