modint gr(int k,int j){
    return MF.comb(k,2*j)*v[2*j]*MF.inv_factorial(j);
}

void solve(){
    cin >> n;
    v[0]=1;
    rep(i,n){
        v[2*i+2]=v[2*i]*MF.comb(2*(i+1),2);
    }
    rep(i,2*n){
        cin >> h[i];h[i]--;
        z[h[i]]++;
    }
    rep(i,M){
        f[i].resize(z[i]/2+1);
        rep(j,z[i]/2+1){
            f[i][j]=gr(z[i],j);
        }
    }
    sort(f,f+M,[](vector<modint> &a,vector<modint> &b){return a.size()<b.size();});
    vector<modint> F={1};
    NTT<2> ntt;
    rep(i,M){
        if(f[i].size()==1) continue;
        F=ntt.multiply(F,f[i]);
    }
    F.resize(n+1);
    vector<modint> G(n+1);
    G[n]=F[n];
