        vector<vector<ll>> nvs;
        for(int i = 0; i < (int)vs.size(); i += 2) {
            if(i + 1 == (int)vs.size()) nvs.pb(vs[i]);
            else {
                vector<ll> v = atcoder::convolution(vs[i], vs[i + 1]);
                nvs.pb(v);
            }
        }
        vs = nvs;
    }
    vector<ll> x = vs[0];
    mi ans = 1;
    for(int j = 2; j <= 2 * n; j += 2) {
        ans *= mod_comb(2 * n - (j - 2), 2);
        ans *= mod_pow(j / 2, mod - 2);
    }
    vector<mi> pow(101010, 1);
    FOR(i, 1, 101010) pow[i] = pow[i - 1] * i;
    FOR(i, 1, x.size()) {
        int rem = 2 * n - 2 * i;
        mi coe = pow[rem];
        coe *= mod_pow(pow[rem / 2], mod - 2);
        coe *= mod_pow(mod_pow(2, rem / 2), mod - 2);
        if(i % 2) ans -= coe * x[i];
        else ans += coe * x[i];
    }
    cout << ans << endl;
    return 0;
}

