        vector<mint>& v = q.back();
        // cerr << "  ";
        for(ll j = 0; j <= np; ++j){
            v.at(j) = mc.factorial(k) / (mc.factorial(k - 2 * j) * mc.factorial(j) * mint(2).pow(j));
            // cerr << v.at(j).val() << " ";
        }
        // cerr << endl;
    }

    while(q.size() > 1){
