using vm = vector<mint>;

class NTT{
    const int root;

    void make_root_pow(int n, vm &root_pow){
        root_pow.resize(n + 1);
        mint new_root = mint(root).pow((mod1 - 1) / n);
        root_pow[0].x = 1;
        rep(i,n){
            root_pow[i + 1] = root_pow[i] * new_root;
        }
    }
    static void make_bit_reverse(int n, vector<int> &v){
        v.resize(n);
        iota(ALL(v), 0);
        for(int i = 1; (1<<i) <= n; ++i){
            int l = 1<<(i - 1), r = 1<<i;
            int plus = n >> i;
            for(int j = l; j < r; ++j){
                int temp = v[j - l] + plus;
                if(j < temp) swap(v[j], v[temp]);
            }
        }
    }
    static void dft(int n, vm &f, bool inv, vm &root_pow, vector<int> &id){
        vm g(n);
        rep(i,n) g[i] = f[id[i]];
        swap(f, g);
        for(int l = n / 2, len = 1; l >= 1; l /= 2, len *= 2){
            for(int i = 0; i < n; i += len * 2){
                rep(j, len){
                    mint z_f = (inv ? root_pow[n - l * j] : root_pow[l * j]) * f[i + len + j];
                    g[i + j] = f[i + j] + z_f;
                    g[i + len + j] = f[i + j] - z_f;
                }
            }
            swap(f, g);
        }
        if(inv) {
            mint n_inv = mint(n).inv();
            rep(i, n) f[i] *= n_inv;
        }
    }
public:
    NTT(int _x = 3) : root(_x){}
    vm convolution(vm &a, vm &b, int size_a = INT_MAX, int size_b = INT_MAX){
        if(size_a > (int)a.size()) size_a = (int)a.size();
        if(size_b > (int)b.size()) size_b = (int)b.size();
        int sz = size_a + size_b - 1, n = 1;
        while(sz > n) n *= 2;
        vm g(n), h(n), root_pow, gh(n);
        vector<int> id;
        copy(a.begin(), a.begin() + size_a, g.begin());
        copy(b.begin(), b.begin() + size_b, h.begin());
        make_root_pow(n, root_pow);
        make_bit_reverse(n, id);
        dft(n, g, false, root_pow, id);
        dft(n, h, false, root_pow, id);
        rep(i, n) gh[i] = g[i] * h[i];
        dft(n, gh, true, root_pow, id);
        gh.resize(sz);
        return gh;
    }
};

vm polynomial_product(vector<vm> &polys){
    //time complexity : O(N log^2 N) (N : sum of polys[i].size())
    if(polys.empty()){
        vm BLA(0);
        return BLA;
    }
    struct _cmp{
        int sz, id;
        _cmp(int _sz, int _id) : sz(_sz), id(_id){}
        bool operator > (const _cmp &b){ return sz > b.sz;}
    };
    vector<vm> poly_copy(polys);
    priority_queue<_cmp, vector<_cmp>, greater<> > pque;
    rep(i, (int)poly_copy.size()) pque.emplace((int)poly_copy[i].size(), i);
    NTT ntt;
    while(pque.size() > 1){
        _cmp c = pque.top(); pque.pop();
        _cmp d = pque.top(); pque.pop();
        poly_copy[c.id] = ntt.convolution(poly_copy[c.id], poly_copy[d.id]);
        poly_copy[d.id].clear();
        pque.emplace(c.sz + d.sz - 1, c.id);
    }
    return poly_copy[pque.top().id];
}

const ll MAX_N = ll(4e+5) + 10;
vm fact(MAX_N, mint(1)), fact_inv(MAX_N, mint(1)), n_inv(MAX_N, mint(1)), two_inv(MAX_N, mint(1));
void makefact(){
    two_inv[1] = (mod1 + 1) / 2;
    mint tmp;
    reps(i,2,MAX_N) {
        fact[i] = fact[i-1] * tmp.set_raw(i);
        two_inv[i] = two_inv[i-1] * two_inv[1];
    }
    fact_inv[MAX_N - 1] = fact[MAX_N - 1].inv();
    Rreps(i, MAX_N - 1, 1){
        fact_inv[i] = fact_inv[i + 1] * tmp.set_raw(i + 1);
        n_inv[i + 1] = fact[i] * fact_inv[i + 1];
    }
}
mint nCm(ll n, ll m){
    return fact[n] * fact_inv[n-m] * fact_inv[m];
}
mint nCm_inv(ll n, ll m){
    return fact[n-m] * fact[m] * fact_inv[n];
}

int main() {
    makefact();
    cin>>N;
    vec h(N * 2), num(100000, 0);
    rep(i, N * 2){
        cin>>h[i];
        --h[i];
        ++num[h[i]];
    }

    vector<vm> polys(0);
    rep(i, 100000){
        int k = 1;
        vm temp(1, 1);
        while(num[i] >= k * 2){
            temp.push_back(fact[num[i]] * fact_inv[k] * fact_inv[num[i] - k * 2] * two_inv[k]);
            ++k;
        }
        if(temp.size() != 1) polys.push_back(temp);
    }
    mint res = fact[N * 2] * two_inv[N] * fact_inv[N];

    vm polv = polynomial_product(polys);
    reps(k, 1, (int)polv.size()){
        if(k > N) break;
        res += mint(k&1 ? -1 : 1) * polv[k] * fact[(N - k) * 2] * two_inv[N - k] * fact_inv[N - k];
    }
    cout<<res<<endl;
}

