inline vector<int> mul(const vector<int> &aa,const vector<int> &bb){
    vector<int> ans;long long br=1ll*aa.size()*bb.size(),ft=1ll*(aa.size()+bb.size())*lg[aa.size()+bb.size()]*10+100;
    if (br<ft){
        while (ans.size()+1<aa.size()+bb.size()) ans.push_back(0);
        int i,j;rp0(i,aa.size()) rp0(j,bb.size()) inc(ans[i+j],1ll*aa[i]*bb[j]%mod);
    }
    else{
        int len=getrev(aa.size()+bb.size()),i;
        rp0(i,len) a[i]=b[i]=0;
        rp0(i,aa.size()) a[i]=aa[i];
        rp0(i,bb.size()) b[i]=bb[i];
