const int MOD = 998244353;
const int MAXN = 1e5+5;

ll fac[MAXN+1];
ll invfac[MAXN+1];

ll inverseModulo(ll a, ll b){
    return 1<a ? b - inverseModulo(b % a, a) * b / a : 1;
}
ll binomial(int n, int k) {
    assert(k>=0 && k<=n);
    if(k==0 || n-k==0) return 1;
    return fac[n] * invfac[k] % MOD * invfac[n-k] % MOD;
}

ll memo[MAXN]={0};
ll pairs(int x) {
    if(x<=1) return 1;
    if(x%2==0) return pairs(x-1);
    if(memo[x] > 0) return memo[x];
    return memo[x] = x * pairs(x-2) % MOD;
}

signed main() {
    FASTIO

    fac[0]=1;
    invfac[0]=1;
    RNG(i,1,MAXN) {
        fac[i] = 1LL*i*fac[i-1] % MOD;
        invfac[i] = inverseModulo(fac[i], MOD);
    }

    int n; cin>>n; n *= 2;
    vi h = READ(n);

    map<int,int> cnt;

    for(auto x : h)
        cnt[x]++;

    min_heap<vi> pq;

    for(auto e : cnt) {
        int ppl = e.second;
        vi poly = {1};
        for(int i=1; i<=ppl/2; i++) {
            ll ways = binomial(ppl, i*2) * pairs(i*2) % MOD;
            poly.push_back(ways);
        }
        pq.push(poly);
    }

    while(pq.size()>=2) {
        vi a = pq.top(); pq.pop();
        vi b = pq.top(); pq.pop();
        vi c = convolution<MOD>(a,b);
        pq.push(c);
    }

    vi poly = pq.top();

    ll ans=0;

    FOR(i,poly.size()) {
        int sgn = i%2 ? -1 : 1;
        ans = (ans + sgn * poly[i] * pairs(n-i*2)) % MOD;
    }

    cout<<ans<<endl;

}

