    if(cnt[i]==0) continue;
    fps tmp(cnt[i]/2+1, 0);
    tmp[0] = 1;
    ll m = cnt[i];
    for(ll j=1;j<=cnt[i]/2;j++){
      ll ret = (((fac[m] * finv[m - j*2])%Q) * (finv[j] * mpow(mpow(2, j, Q), Q-2, Q))%Q)%Q;
      tmp[j] = ret;
    }
    mp.emplace(tmp.size(), tmp);
  }

  mp.emplace(1, fps{1});
  while(mp.size()>1){
    auto L = *mp.begin();
    mp.erase(mp.begin());
    auto R = *(mp.begin());
    mp.erase(mp.begin());
    fps mg = L.second * R.second;
    mp.emplace(mg.size(), mg);
  }

  fps ans = (*mp.begin()).second;

  ll A = 0;
  for(ll i=0;i<ans.size();i++){
    if(ans[i]==0) continue;
    ll x = (((fac[2*n-2*i] * finv[n-i])%Q) * mpow(mpow(2, n-i, Q), Q-2, Q))%Q;
    if(i%2) A = (A + Q - (ans[i]*x)%Q)%Q;
    else A = (A + (ans[i]*x)%Q)%Q;
  }
  std::cout << A << '\n';
}

