struct S{
    mint a,i;
};

struct F{
    int x;
};

S e() { return S{0,0}; }

S op(S l , S r){ return S{l.a+r.a , l.i+r.i}; }

S mapping(F f,S s) {
    if (f.x != -1){
        return S{f.x*s.i , s.i};
    }else{
        return s;
    }
}

F composition(F f,F g) {
    if (f.x != -1){
        return f;
    }else{
        return g;
    }
}

F id() {return F{-1};}

ll nCr(ll n,ll r,vector<ll>& fac){
    if (r == 0 || n == r) return 1;
    else if (r==1 || n == r+1) return n;
    else if (n < r) return 0;
    ll ret = fac[n] * inv_mod(fac[n-r],mod) % mod;
    return ret * inv_mod(fac[r],mod) % mod;
}

