  for (auto pr : mp) {
    int per = pr.second;
    if (per < 2) continue;
    FPS<ModInt> f(per / 2);
    f[0] = 1;
    FOR(i, 1, per / 2 + 1) f[i] = com.nCk(per, i * 2) * p[i];
    fps.emplace_back(f);
  }
  auto comp = [&](int a, int b) {
    return fps[a].degree() > fps[b].degree();
  };
  priority_queue<int, vector<int>, decltype(comp)> que{comp};
  REP(i, fps.size()) que.emplace(i);
  while (que.size() >= 2) {
    int a = que.top(); que.pop();
    int b = que.top(); que.pop();
    fps[b] *= fps[a];
    que.emplace(b);
  }
  if (que.empty()) {
    fps.emplace_back(FPS<ModInt>{1});
    que.emplace(0);
  }
  ModInt ans = 0;
  int a = que.top(), deg = fps[a].degree();
  for (int ban = 0; ban <= deg && ban <= n; ++ban) ans += fps[a][ban] * p[n - ban] * (ban & 1 ? -1 : 1);
  cout << ans << '\n';
  return 0;
}

