}

struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

struct S{//モノイド
  ll zero;
  ll one;
  ll inversion;//転倒数
};

S op(S l, S r){//モノイド同士の演算
  return S{ l.zero+r.zero, l.one+r.one, l.inversion+r.inversion+l.one*r.zero };
};

S e(){//単位元
  return S{0,0,0};
};

struct F{
  bool b;
};

S mapping(F l, S r){//モノイドと作用素の演算
  if(l.b){
    return S{ r.one, r.zero, r.zero*r.one-r.inversion };
  }else{
    return r;
  }
};

F composition(F l, F r){//作用素同士の演算。右の引数が先に作用される。
  return F{ (l.b & !r.b) || (!l.b && r.b) };
};

F id(){//作用素の恒等写像
  return F{false};
};

