const int MOD = MOD998;
int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n; n *= 2;
    map<int, int> cnt;
    for (int i = 0 ; i < n ; i++) {
        int v; cin >> v;
        cnt[v]++;
    }
    priority_queue<Poly<MOD998, 3, 1 << 23>> pq;
    for (auto &p : cnt) {
        int k = p.S / 2;
        Poly poly(k + 1);
        for (int i = 0 ; i <= k ; i++)
            poly[i] = C<MOD>(p.S, 2 * i) * fact<MOD>(2 * i) * fact_inv<MOD>(i) / Mint<MOD>(2).pow(i);
        pq.push(poly);
    }
    while (pq.size() > 1) {
        auto a = pq.top(); pq.pop();
        auto b = pq.top(); pq.pop();
        pq.push(a * b);
    }
    auto res = pq.top(); pq.pop();
    Mint<MOD998> ans = 0;
    for (int i = 0 ; i <= n / 2 ; i++) {
        assert(n / 2 < res.size());
        if (i % 2 == 0) {
            ans += res[i] * fact<MOD>(n - 2 * i) / Mint<MOD>(2).pow(n / 2 - i) * fact_inv<MOD>(n / 2 - i);
        } else {
            ans -= res[i] * fact<MOD>(n - 2 * i) / Mint<MOD>(2).pow(n / 2 - i) * fact_inv<MOD>(n / 2 - i);
        }
    }
    cout << ans << '\n';
}

