    cin >> N;
    beki[0] = 1;
    Factorial[0] = 1;
    for(int i = 1; i <= 100000; i++) {
        beki[i] = beki[i-1] * 2;
        Factorial[i] = Factorial[i-1] * i;
    }
    for(int i = 0; i < 2 * N; i++) {
        ll a;
        cin >> a;
        num[a]++;
    }
    priority_queue<A> que;
    for(int i = 0; i <= 100000; i++) {
        if(num[i] <= 1) continue;
        vector<atcoder::modint998244353> v;
        atcoder::modint998244353 now = 1;
        v.push_back(1);
        for(int j = 1; j * 2 <= num[i]; j++) {
            now *= num[i] - j * 2 + 2;
            now *= num[i] - j * 2 + 1;
