        }
        que.push({v});
    }
    while(que.size() >= 2) {
        auto v = que.top();
        que.pop();
        auto w = que.top();
        que.pop();
        auto u = atcoder::convolution(v.v, w.v);
        que.push({u});
    }
    auto v = que.top().v;
    for(auto tmp : v) {
        cerr << tmp.val() << " ";
