				int l=i+j,r=l+mid;
				int L=F[l],R=1ll*F[r]*g%mod;
				F[l]=mo(L+R),F[r]=mo(mod-R+L);
			}
		}
	}
	if(!rv)return;reverse(F+1,F+N);int tmp=power(N,mod-2);
	for(int i=0;i<N;++i)F[i]=1ll*tmp*F[i]%mod;
