	inv[n]=fpow(fac[n],mod-2);for(int i=n-1;~i;i--) inv[i]=1ll*inv[i+1]*(i+1)%mod;
	cho[0]=1;for(int i=2;i<=n;i+=2) cho[i]=1ll*cho[i-2]*(i-1)%mod;
}

int C(int n,int m){
	if(n<m||m<0) return 0;
	return 1ll*fac[n]*inv[m]%mod*inv[n-m]%mod;
