void ntt(vector<int> &a,int op){
	for(int i=0;i<lim;i++) if(i<rev[i]) swap(a[i],a[rev[i]]);
	for(int mid=1;mid<lim;mid<<=1){
		int w0=fpow(op==1?G:Gi,(mod-1)/(mid<<1));
		for(int len=mid<<1,i=0;i<lim;i+=len){
			int w=1;
			for(int j=0;j<mid;j++,w=1ll*w*w0%mod){
				int x=a[i+j],y=1ll*w*a[i+mid+j]%mod;
				a[i+j]=(x+y)%mod;
				a[i+mid+j]=(x-y+mod)%mod;
			}
		}
	}
}

vector<int> convo(vector<int> &va,vector<int> &vb){
	int n=va.size()-1,m=vb.size()-1;
	for(lim=1,l=0;lim<=n+m;lim<<=1) l++;
	for(int i=0;i<lim;i++) rev[i]=(rev[i>>1]>>1)|((i&1)<<l-1);
	vector<int> res,a(lim+1),b(lim+1);
	for(int i=0;i<=n;i++) a[i]=va[i];
	for(int i=0;i<=m;i++) b[i]=vb[i];
	ntt(a,1);
	ntt(b,1);
	for(int i=0;i<=lim;i++) a[i]=1ll*a[i]*b[i]%mod;
	ntt(a,-1);
	int inv=fpow(lim,mod-2);
	for(int i=0;i<=n+m;i++) res.push_back((1ll*a[i]*inv+mod)%mod);
	return res;
}

