	int half = (d >> 1);
	for(int i = 1 ; i < d ; ++ i)
		rev[i] = ((rev[i >> 1] >> 1) | (i & 1 ? half : 0));
}
void ntt_core(Poly &a , int* wu){
	for(int i = 0 ; i < d ; ++ i)
		if(rev[i] > i)
			swap(a[i] , a[rev[i]]);
	for(int i = 1 ; i < d ; i <<= 1)
		for(int j = 0 ; j < d ; j += (i << 1))
			for(int k = 0 ; k < i ; k ++){
				int a1 = a[j + k] , a2 = 1ll * a[j + k + i] * wu[i + k] % p;
				a[j + k] = (a1 + a2) % p;
				a[j + k + i] = (a1 + p - a2) % p;
			}
}
void intt(Poly &a , int* wu){
	ntt_core(a , wu);
	int c = fpw(d , p - 2);
	for(int i = 0 ; i < d ; ++ i)
		a[i] = 1ll * a[i] * c % p;
}
void ntt(Poly &a , int* wu){
	ntt_core(a , wu);
}

Poly mul(Poly a , Poly b){
	int L = (int)a.size() + (int)b.size() - 1;
	getrev(L);
	a.resize(d) , ntt(a , wu1);
	b.resize(d) , ntt(b , wu1);
	Poly c(d);
	for(int i = 0 ; i < d ; ++ i)
		c[i] = 1ll * a[i] * b[i] % p;
	intt(c , wu2);
	c.resize(L);
	return c;
}

void init(){
	d = 65536;
	int c = fpw(g , (p - 1) / d) , half = (d >> 1);
	wu1[half] = 1;
	for(int i = half + 1 ; i < d ; ++ i)
		wu1[i] = 1ll * wu1[i - 1] * c % p;
	for(int i = half - 1 ; i ; -- i)
		wu1[i] = wu1[i << 1];
	c = fpw(c , p - 2);
	wu2[half] = 1;
	for(int i = half + 1 ; i < d ; ++ i)
		wu2[i] = 1ll * wu2[i - 1] * c % p;
	for(int i = half - 1 ; i ; -- i)
		wu2[i] = wu2[i << 1];
	r[0] = 1; r[1] = 1;
	for(int i = 2 ; i <= (d << 1) ; i += 2){
		r[i] = 1ll * (i - 1) * r[i - 2] % p;
		r[i + 1] = 1ll * (i + 1) * r[i] % p;
	}
	fac[0] = fac[1] = 1;
	for(int i = 2 ; i <= (d << 1) ; ++ i)
		fac[i] = 1ll * fac[i - 1] * i % p;
	ifac[0] = ifac[1] = 1;
	for(int i = 2 ; i <= (d << 1) ; ++ i)
		ifac[i] = p - 1ll * (p / i) * ifac[p % i] % p;
	for(int i = 2 ; i <= (d << 1) ; ++ i)
		ifac[i] = 1ll * ifac[i - 1] * ifac[i] % p;
}

