int sum(int a, int b) {
    return a + b >= MOD ? a + b - MOD : a + b;
}
int sub(int a, int b) {
    return a - b < 0 ? a - b + MOD : a - b;
}
int mul(int a, int b) {
    return (1LL*a*b)%MOD;
}
int pwr(int a, int b) {
	if (!b) return 1;
	int r = pwr(a, b/2);
	r = mul(r, r);
	if (b%2) r = mul(r, a);
	return r;
}


