    for (int i = MAXX-2; i >= 0; i--)   ifact[i] = mul(i+1, ifact[i+1]);

    pinv[0] = 1;
    pinv[1] = pwr(2, MOD-2);
    for (int i = 2; i < MAXX; i++) pinv[i] = mul(pinv[i-1], pinv[1]);

