template <int m> struct ModInt {
//Source: https://github.com/atcoder/ac-library/blob/master/atcoder/modint.hpp (modified)
    unsigned int _v=0;
    static const unsigned int umod = m;
    ModInt(): _v(0) {}
    ModInt(long long v) {auto x = v % (long long)m; if (x<0) x += m; _v = x; }
    unsigned int val() const { return _v;  }
    ModInt& operator++() {_v++; if (_v==umod) _v = 0; return *this; }
    ModInt& operator--() {if (_v==0) _v = umod; _v--; return *this; }
    ModInt& operator+=(const ModInt& rhs) { _v += rhs._v; if (_v>=umod) _v -= umod; return *this; }
    ModInt& operator-=(const ModInt& rhs) { _v -= rhs._v; if (_v>=umod) _v += umod; return *this; }
    ModInt& operator*=(const ModInt& rhs) {unsigned long long z = _v; z *= rhs._v; _v = (unsigned int)(z % umod); return *this; }
    ModInt operator-() const { return ModInt() - *this; }
    ModInt pow(long long n) const {assert(0<=n); ModInt x = *this, r = 1; while (n) {if (n & 1) r *= x; x *= x; n >>= 1; } return r; }
    ModInt inv(){assert(m==1000000007 || m==998244353); return pow(umod - 2);}
    friend ModInt operator+(const ModInt& lhs, const ModInt& rhs) {return ModInt(lhs) += rhs; }
    friend ModInt operator-(const ModInt& lhs, const ModInt& rhs) {return ModInt(lhs) -= rhs; }
    friend ModInt operator*(const ModInt& lhs, const ModInt& rhs) {return ModInt(lhs) *= rhs; }
    friend bool operator==(const ModInt& lhs, const ModInt& rhs) {return lhs._v==rhs._v; }
    friend bool operator!=(const ModInt& lhs, const ModInt& rhs) {return lhs._v!=rhs._v; }
};
