template<int N, typename mint> struct Combinatorics {
    mint _fac[N+1], _invfac[N+1];
    Combinatorics() {
        _fac[0] = _invfac[0] = 1;
        RNG(i,1,N) _invfac[i] = (_fac[i]=i*_fac[i-1]).inv();
    }
    mint fac(int n) {
        return _fac[n];
    }
    mint invfac(int n) {
        return _invfac[n];
    }
    mint binomial(int n, int k) {
        assert(k>=0 && k<=n);
        if(k==0 || n-k==0) return 1;
        return _fac[n] * _invfac[k] * _invfac[n - k];
    }
};
