        for(int j = 0; j <= nSum; j++) dp[v][j] = 0;
        for(int j = 0; j <= sum; j++){
            for(int k = 0; k <= min(j,count[i+1]); k++){
                int next = j+count[i+1]-2*k;
                long long add = dp[u][j]*getWay(j,count[i+1],k)%mod;
                dp[v][next] += add; if(dp[v][next]>=mod) dp[v][next] -= mod; 
            }
        }
    }
    printf("%lld\n",dp[size%2][0]);
    return 0;
}

