					t = tmp[i|j|k]*w[i|k]%mod, tmp[i|j|k] = tmp[j|k]+mod-t, tmp[j|k] += t;
		for(int i=0; i<l; i++) a[i] = tmp[i]%mod;
	}
	void IDFT(int *a, int l)
	{
		reverse(a+1, a+l); DFT(a, l);
		mul(a, l, mod-mod/l, a);
	}
