int n, h, sum[100005], F[100005], Finv[100005], G[100005], ANS;
int C(int M, int N)
{
    return F[M] * Finv[N] % MOD * Finv[M - N] % MOD;
}
int power(int A, int B)
{
    int res = 1;
    while (B)
    {
        if (B & 1)
        {
            res = res * A % MOD;
        }
        A = A * A % MOD;
        B >>= 1;
    }
    return res;
}
signed main()
{
