    for (int i = 1; i <= 100000; ++i)
    {
        F[i] = F[i - 1] * i % MOD;
    }
    Finv[100000] = power(F[100000], MOD - 2);
    for (int i = 100000; i; --i)
    {
        Finv[i - 1] = Finv[i] * i % MOD;
    }
    G[0] = 1;
    for (int i = 1; i <= 100000; ++i)
    {
        G[i] = G[i - 1] * (i + i - 1) % MOD;
    }
    for (int i = 1; i <= 100000; ++i)
    {
        if (sum[i])
        {
            tmp.clear();
            for (int j = 0; j <= sum[i] >> 1; ++j)
            {
                int v = C(sum[i], j << 1) * G[j] % MOD;
                if (j & 1)
                {
                    v = MOD - v;
                }
                tmp.push_back(v);
