        tmp = ans.top();
        ans.pop();
        tmp = atcoder::convolution(tmp, ans.top());
        ans.pop();
        ans.push(tmp);
    }
    tmp = ans.top();
    ans.pop();
    for (int i = 0; i < tmp.size(); ++i)
    {
        ANS = (ANS + tmp[i] * G[n - i]) % MOD;
    }
    cout << ANS << endl;
    return 0;
}

