const long long MOD = 998244353;
ll func(ll x){
  const ll max_len=100001;
  static vector<ll> cache(max_len);
  static bool f=false;
  if(f){
    return cache[x];
  }
  cache[1]=cache[0]=1;
  const ll inv2=inv_mod(2,MOD);
  FOR(i,2,max_len){
    cache[i]=cache[i-2]*i%MOD*(i-1)%MOD*inv2%MOD;
  }
  return cache[x];
}
ll factorial(ll x){
  static vector<ll> cache(1000001);
  static bool f=false;
  if(f){
    return cache[x];
  }
  cache[0]=cache[1]=1;
  FOR(i,2,1000001){
    cache[i]=cache[i-1]*i%MOD;
  }
  return cache[x];
}
void solve(long long N, std::vector<long long> h){
  vector<ll> mp(100000);
  REP(2*N){
    mp[h[i]]++;
  }
  vector<ll> st;
  REP(100000){
    if(mp[i]>1){
      st.push_back(mp[i]);
    }
  }
  sort(st.begin(),st.end());
  vector<vector<ll>> dp;
  for (auto &&i : st)
  {
    vector<ll> tmp{1};
    For(j,i/2){
      tmp.push_back(func(i-2*j));
    }
    dp.push_back(move(tmp));
  }
  while(dp.size()!=1){
    vector<vector<ll>> ndp;
    REP(dp.size()/2){
      ndp.push_back(convolution(dp[2*i],dp[2*i+1]));
    }
    if(dp.size()%2)ndp.push_back(dp.back());
    dp=move(ndp);
  }
  {
    vector<ll> dp2=dp[0];
    vector<ll> dp=dp2;
    ll ans=0;
    REP(dp.size()){
      if(i%2==0){
        ans=(ans+dp[i]*func(2*(N-i))%MOD*inv_mod(factorial(N-i),MOD)%MOD)%MOD;
      }else{
        ans=(ans+MOD-dp[i]*func(2*(N-i))%MOD*inv_mod(factorial(N-i),MOD)%MOD)%MOD;
      }
    }
    cout<<ans<<endl;

  }
}

