int solve() {
    ll n;cin>>n;

    vl h(2*n);
    auto z = zipper();
    rep(i, 2*n){
        cin>>h[i];
        z.add_value(h[i]);
    }
    z.build();
    sort(all(h));
    dump(h);
    auto x = z.zip(h);
    dump(x);
    vec<ll> cnt(2*n+1);
    rep(i, 2*n){
        cnt[x[i]]++;
    }
    vl y;
    rep(i, 2*n+1){
        dump(cnt[i]);
        if (cnt[i]>0) y.pb(cnt[i]);
    }
    dump(y);

    vec<mint> q(2*n);  // q[i] : i!!
    q[1] = 1;
    for(ll i=3; i<2*n; i+=2){
        q[i] = q[i-2] * i;
    }
    dump(q);

    auto f = [&](auto& z) -> vec<int> {
        vec<int> res = {1};
        rep(p, 1, z/2 + 1){
            res.pb((com(z, p*2)*q[2*p-1]).x);
        }
        return res;
    };

    deque<vec<int>> dq;
    rep(i, sz(y)){
        dq.push_back(f(y[i]));
        dump(y[i], f(y[i]));
    }
    while(sz(dq)>1){
        auto u = dq.front(); dq.pop_front();
        auto v = dq.front(); dq.pop_front();
        dq.push_back(convolution(u, v));
    }
    dump(dq.front());

    auto cntk = dq.front();  // cntk[p] : kペア選ぶ方法

    mint ans = 0;
    rep(p, sz(cntk)){
        ans += mint(cntk[p]) * pow(-1, p) * q[2*n-2*p-1];
    }
    cout << ans << endl;

    return 0; 
}


