// #define MOD   (1000000007LL)
#define MOD   (998244353LL)

ll mod_mlt(ll x, ll y, ll mod)
{
    ll ret = 0LL;
    x %= mod;

    while (y) {
        if (y & 1LL) {
            ret += x;
            ret %= mod;
        }
        y >>= 1;
        x <<= 1;
        x %= mod;
    }

    return ret;
}

// O(log(exp))
ll mod_pow(ll base, ll exp, ll mod)
{
    ll ret = 1LL;

    for ( ; exp; ) {
        if (exp & 1LL) {
            ret *= base;
            ret %= mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }

    return ret;
}

// O(log(mod))
ll mod_inv(ll x, ll mod)
{
    // available only when mod is prime
    return mod_pow(x, mod - 2LL, mod);
}

ull mod_combination(ll x, ll y, ll mod)
{
    if (y > x / 2LL) y = x - y;

    ll ret = 1;

    for (ll i = 0LL; i < y; ++i) {
        ret = (ret * x--) % mod;
        ret = (ret * mod_inv(i + 1LL, mod)) % mod;
    }

    return ret;
}

void make_perms(ll perms[], ll perm_invs[], ll size, ll mod)
{
    perms[0] = 1LL;
    srep (i, 1, size) {
        perms[i] = perms[i-1] * i;
        perms[i] %= mod;
    }

    perm_invs[size-1] = mod_inv(perms[size-1], mod);
    rrep (i, size-1) {
        perm_invs[i] = perm_invs[i+1LL] * (i+1LL);
        perm_invs[i] %= mod;
    }
}







// #define MOD (998244353LL)
#define SZ (1048576LL)
#define ROOT (646LL)

S map<ll, ll> units;
S map<ll, ll> units_inv;
S ll *buf = NULL;
S ll buf_offset;

void _ntt(ll coefs[], ll n, bool inverse, bool top)
{
    // pow of 2
    assert(((n - 1LL) & n) == 0LL);

    if (n == 1) return;

    ll *ncoefs[2];
    rep (i, 2) {
        // ncoefs[i] = new ll[n/2LL];
        ncoefs[i] = buf + buf_offset;
        buf_offset += n/2LL;
    }
    rep (i, n) ncoefs[i & 1LL][i/2LL] = coefs[i];

    _ntt(ncoefs[0], n/2LL, inverse, false);
    _ntt(ncoefs[1], n/2LL, inverse, false);

    ll unit;
    if (inverse) unit = units_inv[n];
    else unit = units[n];
    ll now = 1;

    rep (i, n) {
        coefs[i] = ncoefs[0][i%(n/2LL)];
        coefs[i] %= MOD;
        coefs[i] += now * ncoefs[1][i%(n/2LL)];
        coefs[i] %= MOD;
        now = now * unit;
        now %= MOD;
    }

    if (inverse && top) {
        ll mlt = mod_inv(n, MOD);
        rep (i, n) {
            coefs[i] = coefs[i] * mlt;
            coefs[i] %= MOD;
        }
    }
}

void ntt(ll coefs[], ll n, bool inverse)
{
    if (!buf) buf = new ll[30LL * 1024LL * 1024LL];
    buf_offset = 0;
    return _ntt(coefs, n, inverse, true);
}

void convolution(ll results[], const ll alist[], ll an, const ll blist[], ll bn)
{
    // must search appropriate root if an + bn > 1048576
    assert(an + bn <= SZ);

    ll sz = 1;
    while (sz < an + bn) sz <<= 1LL;
    ll unit = ROOT;
    rep (i, llround(log2(SZ / sz))) {
        unit *= unit;
        unit %= MOD;
    }
    ll unit_inv = mod_pow(unit, sz-1LL, MOD);

    ll ssz = sz;
    while (ssz > 1) {
        units[ssz] = unit;
        units_inv[ssz] = unit_inv;
        ssz >>= 1LL;
        unit *= unit;
        unit %= MOD;
        unit_inv *= unit_inv;
        unit_inv %= MOD;
    }

    ll *acs = new ll[sz];
    memset(acs, 0, sizeof(ll) * sz);
    rep (i, an) acs[i] = alist[i] % MOD;
    ntt(acs, sz, false);

    ll *bcs = new ll[sz];
    memset(bcs, 0, sizeof(ll) * sz);
    rep (i, bn) bcs[i] = blist[i] % MOD;
    ntt(bcs, sz, false);

    ll *mlts = new ll[sz];
    rep (i, sz) mlts[i] = (acs[i] * bcs[i]) % MOD;
    ntt(mlts, sz, true);

    rep (i, an+bn) results[i] = mlts[i] % MOD;

    delete [] acs;
    delete [] bcs;
    delete [] mlts;
}






