        Modint res = 1;
        while(b){
            if(b % 2){
                res *= a;
            }
            a *= a;
            b /= 2;
        }
        return res;
    }
};
using mint = Modint<998244353>;
const int NUM = 400005;
mint fact[NUM + 1], fact_inv[NUM + 1], inv[NUM + 1];
mint combi(long long N_, long long K_){
    static const int Mod_ = fact[0].getmod();
    static_assert(NUM < Mod_, "");
    if(fact[0] == 0){
        inv[1] = fact[0] = fact_inv[0] = 1;
        for(int i = 2; i <= NUM; i++){
            inv[i] = inv[Mod_ % i] * (Mod_ - Mod_ / i);
        }
        for(int i = 1; i <= NUM; i++){
            fact[i] = fact[i - 1] * i;
            fact_inv[i] = fact_inv[i - 1] * inv[i];
        }
    }
    if(K_ < 0 or K_ > N_) return 0;
    return fact_inv[K_] * fact[N_] * fact_inv[N_ - K_];
}
mint hcomb(long long N_, long long K_){
    return ((N_ | K_) == 0) ? 1 : combi(N_ + K_ - 1, K_);
}
const mint g = 3;
void fft(vector<mint> &a, const bool rev = false){
    const int n = (int) a.size();
    assert((n & (n - 1)) == 0);
    if(n == 1)return;
    vector<mint> b, c;
    rep(i,n){
        (i & 1 ? c : b).push_back(a[i]);
    }
    fft(b, rev);
    fft(c, rev);
    mint w = 1;
    const mint t = pow(g, rev ? (mint::getmod()-1 -(mint::getmod()-1)/n) : (mint::getmod()-1)/n);
    rep(i,n){
        a[i] = b[i & ((n >> 1) - 1)] + w * c[i & ((n >> 1) - 1)];
        w *= t;
    }
}
vector<mint> mul(const vector<mint> &a, const vector<mint> &b){
    int s = (int) a.size() + (int) b.size() - 1;
    int t = 1;
    while(t < s) t *= 2;
    vector<mint> A(t), B(t);
    rep(i,a.size())A[i] = a[i];
    rep(i,b.size())B[i] = b[i];
    fft(A);
    fft(B);
    rep(i,t)A[i] *= B[i];
    fft(A, true);
    vector<mint> res(s);
    const mint inv = mint(1)/t;
    rep(i,s)res[i] = A[i] * inv;
    return res;
}
