}

void solve() {
    int N;
    cin >> N;
    int lim = 100000;

    vector<int> cnt(lim + 1);
    REP(i, 2 * N) {
        int tmp;
        cin >> tmp;
        cnt[tmp]++;
    }

    vector<vector<ll>> g; // g[i][j] = 身長A[i]がjペア違反する方法

    for (int i = 0; i <= lim; ++i) {
        if (cnt[i] == 0) continue;
        vector<ll> v;
        for (int j = 0; j * 2 <= cnt[i]; ++j) {
//            mint tmp = fact(cnt[i]) / (mint(2).pow(j) * fact(j) * fact(cnt[i] - 2 * j));
            mint tmp = fact(cnt[i]) * inv_p2(j) * inv_fact(j) * inv_fact(cnt[i] - 2 * j);
            v.push_back(tmp.x);
        }
        g.push_back(v);
    }

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
    for (int i = 0; i < g.size(); ++i) {
        pq.push(make_pair((int) g[i].size(), i));
    }

    while (pq.size() > 1) {
        int i1 = pq.top().second;
        pq.pop();
        int i2 = pq.top().second;
        pq.pop();

        int s1 = g[i1].size();
        int s2 = g[i2].size();
//        int sn = s1 + s2 + 1;
        int sn = s1 + s2 + 1;

        vector<ll> v1(sn), v2(sn);
        for (int i = 0; i < s1; ++i) {
            v1[i] = g[i1][i];
        }

        for (int i = 0; i < s2; ++i) {
            v2[i] = g[i2][i];
        }

        vector<ll> vn = NTT<>::multiply(v1, v2);
        g[i1] = vn;
        pq.emplace(sn, i1);
    }

    auto f = g[pq.top().second];

    mint ans = 0;
    for (int i = 0; i <= N; ++i) {
        if (f.size() <= i) {
            break;
        }

        int sign = 1 - 2 * (i % 2);
//        mint tmp = mint(f[i]) * fact(2 * N - 2 * i) / (fact(N - i) * mint(2).pow(N - i));
        mint tmp = mint(f[i]) * fact(2 * N - 2 * i) * inv_fact(N - i) * inv_p2(N - i);
        ans += tmp * sign;
    }

    cout << ans << endl;


}


