vector<long> FFT(vector<long> A)
{
	int n = A.size();
	if(n == 1) return A;

	long Wn = pwr(2,119*pwr(2,23-int(log2(n)+1)));
	long W = 1;

	vector<long> Ae, Ao;
	vector<long> Ye, Yo, Y;
	Y.assign(n, 0);
	for(int i = 0; i < n; i+=2) Ae.push_back(A[i]); 
	for(int i = 1; i < n; i+=2) Ao.push_back(A[i]);
	Ye = FFT(Ae);
	Yo = FFT(Ao);
	for(int i = 0 ; i <= n/2-1; i++)
	{
		Y[i] = (Ye[i] + (W * Yo[i])%MOD)%MOD;
		Y[i+n/2] = dec(Ye[i],mul(W, Yo[i]));
		W = (W*Wn)%MOD;
	}
	return Y;
}

vector<long> IFFT(vector<long> Y)
{
	Y = FFT(Y);
	for(int i = 0; i < Y.size(); i++)
	{
		Y[i] *= pwr(Y.size(), MOD-2);
		Y[i] %= MOD;
	}
	reverse(Y.begin()+1, Y.end());
	return Y;
}

// multiplicaton of 2 polinomial in O(n log n) with FFT
