vector<long> operator* (vector<long> A, vector<long> B)
{
	int sz = A.size() + B.size();
	int x = 1;
	while(x < sz) x *= 2;
	while(A.size() < x) A.push_back(0);
	while(B.size() < x) B.push_back(0);

	vector<long> YA = FFT(A);
	vector<long> YB = FFT(B);
	vector<long> YC(YA.size());
	for(int i = 0; i < YA.size(); i++) { YC[i] = (YA[i]*YB[i])%MOD; }

	YC = IFFT(YC);
	while(YC.back() == 0) YC.pop_back();
	return YC;
}

