template<uint mod = 998244353, uint root = 3>
class ntt
{
private:
    static constexpr int depth = 30;
    static void transform(std::vector<modint<mod>>& as, const int lg, const bool rev)
    {
        const int N = as.size();
        static std::vector<modint<mod>> Rs[depth];
        if (Rs[lg].empty()) {
            Rs[lg].reserve(N), Rs[lg].resize(N, modint<mod>(1));
            const modint<mod> r = modint<mod>(root) ^ ((mod - 1) / N);
            for (int i = 1; i < N; i++) { Rs[lg][i] = Rs[lg][i - 1] * r; }
        }
        std::vector<modint<mod>> tmp(N);
        for (int w = (N >> 1); w > 0; w >>= 1) {
            for (int y = 0; y < (N >> 1); y += w) {
                const modint<mod> r = rev ? Rs[lg][y == 0 ? 0 : N - y] : Rs[lg][y];
                for (int x = 0; x < w; x++) {
                    const auto u = as[y << 1 | x], v = as[y << 1 | x | w]() * r;
                    tmp[y | x] = u + v, tmp[y | x | (N >> 1)] = u - v;
                }
            }
            std::swap(tmp, as);
        }
        if (rev) {
            for (int i = 0; i < N; i++) { as[i] /= modint<mod>(N); }
        }
    }

public:
    ntt() = delete;
    static std::vector<modint<mod>> convolute(const std::vector<modint<mod>>& as, const std::vector<modint<mod>>& bs)
    {
        const int need = as.size() + bs.size() - 1, lg = clog(need), sz = 1UL << lg;
        std::vector<modint<mod>> As(sz, 0), Bs(sz, 0);
        for (int i = 0; i < (int)as.size(); i++) { As[i] = as[i](); }
        for (int i = 0; i < (int)bs.size(); i++) { Bs[i] = bs[i](); }
        transform(As, lg, false), transform(Bs, lg, false);
        for (int i = 0; i < sz; i++) { As[i] *= Bs[i]; }
        transform(As, lg, true);
        std::vector<modint<mod>> ans(need);
        for (int i = 0; i < need; i++) { ans[i] = int(As[i]()); }
        return ans;
    }
};
