struct NTT {
	int N; vector<int> perm;
	int root, inv, pw;
    int invSz;
	NTT(int root, int inv, int pw) :
		root(root), inv(inv), pw(pw) {}
	void precalculate() {
		perm.resize(N); perm[0] = 0;
		for (int k=1; k<N; k<<=1) {
			for (int i=0; i<k; i++) {
				perm[i] <<= 1; perm[i+k] = 1 + perm[i];
			}
		}
		invSz = pwr(N, MOD-2);
	}
	void fft(vector<int> &v, bool invert = false) {
		if (v.size() != perm.size()) {
			N = v.size(); assert(N && (N&(N-1)) == 0);
			precalculate();
		}
		for (int i=0; i<N; i++)
			if (i < perm[i]) swap(v[i], v[perm[i]]);
		for (int len = 2; len <= N; len <<= 1) {
			int factor = invert ? inv : root;
			for (int i = len; i < pw; i <<= 1)
				factor = mul(factor, factor);
			for (int i=0; i<N; i+=len) {
				int w = 1;
				for (int j=0; j<len/2; j++) {
					int x=v[i+j], y = mul(w, v[i+j+len/2]);
					v[i+j] = sum(x, y);
					v[i+j+len/2] = sub(x, y);
					w = mul(w, factor);
				}
			}
		}
		if (invert) {
            for (int &x : v) x = mul(x, invSz);
		}
	}
	vector<int> multiply(vector<int> a, vector<int> b) {
		int n=1; while (n < a.size()+ b.size()) n<<=1;
		a.resize(n); b.resize(n);
		fft(a); fft(b);
		for (int i=0; i<n; i++) a[i] = mul(a[i], b[i]);
		fft(a, true);
		return a;
	}
};

