const Combination<mint> C(100000);

// マッチングの個数
mint f(int n, int k) {
    return C.perm(n, k * 2) / (mint(2).pow(k) * C.fact(k));
}

void solve() {
    int n;
    std::cin >> n;

    std::map<int, int> cnt;  // 各グループのサイズ
    for (int i = 0; i < n * 2; ++i) {
        int h;
        std::cin >> h;

        if (!cnt.count(h)) cnt[h] = 0;
        ++cnt[h];
    }

    std::queue<std::vector<mint>> que;
    // グループ毎の不正マッチングの数を求める
    for (auto [h, m] : cnt) {
        std::vector<mint> pat;
        for (int k = 0; k * 2 <= m; ++k) {
            pat.push_back(f(m, k));
        }
        que.push(pat);
    }

    // マージ
    while ((int)que.size() > 1) {
        auto p1 = std::move(que.front());
        que.pop();
        auto p2 = std::move(que.front());
        que.pop();
        que.push(ac::convolution(p1, p2));
    }

    auto p = std::move(que.front());

    // 包除原理
    mint ans = 0;
    for (int k = 0; k < (int)p.size(); ++k) {
        ans += mint(-1).pow(k) * p[k] * f(n * 2 - k * 2, n - k);
    }
    std::cout << ans.val() << "\n";
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    solve();

    return 0;
}

