struct cmp {
    bool operator () (const vector<M> &a, const vector<M> &b) {
        return a.size() > b.size();
    }
};

M fact[MAXN], inv[MAXN], power[MAXN];

M choose(int n, int k) {
    return fact[n] * inv[k] * inv[n-k];
}

int main() {
    ios_base::sync_with_stdio(false);
