    for (int i=1; i<=2*n; i++) {
        fact[i] = fact[i-1] * i;
        inv[i] = fact[i].inv();
        power[i] = power[i-1] / 2;
    }

    priority_queue<vector<M>, vector<vector<M>>, cmp> pq;
    for (int i=1; i<MAXN; i++)
        if (cnt[i] >= 2) {
            vector<M> cur{1};
            for (int j=1; j*2<=cnt[i]; j++)
