const int MAXX = 1e5+7;
int fact[MAXX], ifact[MAXX];

int nCr(int n, int r) {
    if (r < 0 || n < r) return 0;
    return mul(fact[n], mul(ifact[r], ifact[n-r]));
}

int fr[MAXX];
int pinv[MAXX];
int dfact[MAXX];

vector< vector< mint > >w;
typedef pair< int , int >PII;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    fact[0] = 1;
    for (int i = 1; i < MAXX; i++)      fact[i] = mul(i, fact[i-1]);
    ifact[MAXX-1] = pwr(fact[MAXX-1], MOD-2);
    for (int i = MAXX-2; i >= 0; i--)   ifact[i] = mul(i+1, ifact[i+1]);

    pinv[0] = 1;
    pinv[1] = pwr(2, MOD-2);
    for (int i = 2; i < MAXX; i++) pinv[i] = mul(pinv[i-1], pinv[1]);

    dfact[0] = 1;
    for (int i = 2; i < MAXX; i+=2) dfact[i] = mul(dfact[i-2], i-1);

    int n;
    cin >> n;

    for (int i = 0; i < n+n; i++) {
        int h;
        cin >> h;
        fr[h]++;
    }

    priority_queue< PII >pq;
    for (int i = 1; i < MAXX; i++) {
        if (fr[i] == 0) continue;
        w.emplace_back();
        for (int j = 0; j+j <= fr[i]; j++) {
            w.back().push_back(mul(fact[fr[i]], mul(ifact[j], mul(ifact[fr[i]-j-j], pinv[j]))));
        }
        if (w.size() > 1 && w.back().size() == 1) {
            w.pop_back();
        } else {
            pq.emplace(-w.size(), w.size()-1);
        }
    }

    while (pq.size() > 1) {
        PII u = pq.top(); pq.pop();
        PII v = pq.top(); pq.pop();
        w[u.second] = convolution(w[u.second], w[v.second]);
//        w[u.second] = ntt.multiply(w[u.second], w[v.second]);
        while (w[u.second].size() > 1 && w[u.second].back() == 0) w[u.second].pop_back();
        pq.emplace(-w[u.second].size(), u.second);
    }

    int z = pq.top().second;
//    for (int i = 0; i < w[z].size(); i++) {
//        cout << "ways[" << i << "] = " << w[z][i] << endl;
//    }

    int ans = 0;
    for (int i = 0; i <= n && i < w[z].size(); i++) {
        int tmp = mul(w[z][i].val(), dfact[(n-i)*2]);
        if (i&1) ans = sub(ans, tmp);
        else ans = sum(ans, tmp);
    }

    cout << ans << "\n";


    return 0;
}

