using modint = atcoder::modint998244353;

struct Compare_t{
    bool operator ()(const std::vector<modint>& A, const std::vector<modint>& B){
        if(A.size() != B.size()) return A.size() > B.size();
        return &A < &B;
    }
};



int main(void){
    std::cin.tie(nullptr); std::ios_base::sync_with_stdio(false); 
    std::cout << std::fixed << std::setprecision(16);
    int n; std::cin >> n; n *= 2;
    std::vector<int> A(n); for(auto& itr : A) std::cin >> itr;

    std::vector<modint> F(n + 1); F[0] = modint(1); for(int i = 1; i <= n; ++i) F[i] = F[i - 1] * modint::raw(i);
    std::vector<modint> iF(n + 1); iF[n] = F[n].inv();
    for(int i = n; i > 0; --i) iF[i - 1] = iF[i] * modint::raw(i);
    const auto combination = [&](const int arg_n, const int arg_k){
        if(arg_k < 0 or arg_k > arg_n) return modint(0);
        return F[arg_n] * iF[arg_k] * iF[arg_n - arg_k];
    };
    std::vector<modint> FF(n);
    FF[0] = 1; FF[1] = 1; for(int i = 2; i <= n; ++i) FF[i] = FF[i - 2] * modint::raw(i);
    const auto choose = [&](int t){
        if(t == 0) return modint(1);
        return FF[2 * t - 1];
    };

    std::sort(A.begin(), A.end());
    std::priority_queue<std::vector<modint>, std::vector<std::vector<modint>>, Compare_t> PQ;
    PQ.push(std::vector<modint>{1});
    for(int i = 0; i < n; ){
        int cnt = 1; while(i + cnt < n and A[i] == A[i + cnt]) ++cnt;
        std::vector<modint> V(cnt / 2 + 1);
        V[0] = 1;
        for(int idx = 1; 2 * idx <= cnt; ++idx){
            V[idx] = combination(cnt, 2 * idx) * choose(idx);
        }
        PQ.push(V);
        i += cnt;
    }
    while(PQ.size() > 1){
        const auto V1 = PQ.top(); PQ.pop();
        const auto V2 = PQ.top(); PQ.pop();
        PQ.push(atcoder::convolution(V1, V2));
    }
    const auto V = PQ.top();
    const int nn = n / 2;
    modint res(0);
    for(int i = 0; i < V.size(); ++i){
        if(i & 1) res -= V[i] * choose(nn - i);
        else res += V[i] * choose(nn - i);
    } std::cout << '\n';
    std::cout << res.val() << '\n';

    return 0;
}

