    queue<vector<mint>> q;
    for (int i = 0; i < 1<<17; i++) {
        if(cnt[i]){
            int sz = cnt[i] / 2;
            vector<mint> a(sz + 1);
            for (int j = 0; j <= sz; j++) {
                a[j] = mint(combi(cnt[i], 2 * j)) * f(j);
            }
            q.push(a);
        }
    }
    while(q.size() > 1){
        auto a = q.front();q.pop();
        auto b = q.front();q.pop();
        auto c = convolution(a, b);
        q.push(c);
    }
    auto d = q.front();q.pop();
    mint ans = 0;
    for (int i = 0; i < d.size(); i++) {
        int t = n - i;
        ans += mint(i % 2 ? -1 : 1) * d[i] * f(t);
    }
    cout << ans.val() << endl;
    return 0;
}

