namespace modular
{
    constexpr ll MOD = 998244353;
    const int MAXN = 1100000;
    template <ll Modulus>
    class modint
    {
        using u64 = ll;

    public:
        u64 a;

        constexpr modint(const u64 x = 0) noexcept : a(((x % Modulus) + Modulus) % Modulus) {}
        constexpr u64 &value() noexcept { return a; }
        constexpr const u64 &value() const noexcept { return a; }
        constexpr modint operator+(const modint rhs) const noexcept { return modint(*this) += rhs; }
        constexpr modint operator-(const modint rhs) const noexcept { return modint(*this) -= rhs; }
        constexpr modint operator*(const modint rhs) const noexcept { return modint(*this) *= rhs; }
        template <typename T>
        constexpr modint operator^(T rhs) const noexcept { return modint(*this) ^= rhs; }
        constexpr modint operator-() const noexcept { return modint() - *this; }
        constexpr modint &operator+=(const modint rhs) noexcept
        {
            a += rhs.a;
            if (a >= Modulus)
            {
                a -= Modulus;
            }
            return *this;
        }
        constexpr modint &operator-=(const modint rhs) noexcept
        {
            if (a < rhs.a)
            {
                a += Modulus;
            }
            a -= rhs.a;
            return *this;
        }
        constexpr modint &operator*=(const modint rhs) noexcept
        {
            a = a * rhs.a % Modulus;
            return *this;
        }
        constexpr bool operator==(const modint rhs) const noexcept { return a == rhs.a; }
        template <typename T>
        constexpr modint &operator^=(T n) noexcept
        {
            modint<Modulus> res = 1;
            modint<Modulus> x = a;
            while (n)
            {
                if (n & 1)
                    res *= x;
                x *= x;
                n >>= 1;
            }
            a = res.a;
            return *this;
        }
    };
#define mint modint<MOD>
#define vmint vector<mint>
    vmint Inv{0, 1}, Prd{1, 1}, Invprd{1, 1};
    mint inv(int n)
    {
        if (n > MAXN)
            return mint(n) ^ (MOD - 2);
        if (Inv.size() > n)
            return Inv[n];
        else
        {
            for (int i = Inv.size(); i <= n; ++i)
                Inv.emplace_back(Inv[MOD % i] * (-MOD / i));
            return Inv[n];
        }
    }
    mint inv(mint x) { return inv(x.a); }
    mint prd(int n)
    {
        if (Prd.size() > n)
            return Prd[n];
        else
            for (int i = Prd.size(); i <= n; ++i)
                Prd.emplace_back(Prd[i - 1] * i);
        return Prd[n];
    }
    mint invprd(int n)
    {
        if (Invprd.size() > n)
            return Invprd[n];
        else
            for (int i = Invprd.size(); i <= n; ++i)
                Invprd.emplace_back(Invprd[i - 1] * inv(i));
