class combination {
    vector<mint> fact, ifact;
public:

    combination(int n) : fact(n + 1), ifact(n + 1) {
        assert(n < mod);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
    }

    mint operator()(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * ifact[k] * ifact[n - k];
    }
} comb(100010);

// Number Theoretic Transform
namespace NTT {
    void trans(vector<mint> &v, bool inverse = false) {
        int sz = v.size();
        if (sz == 1) return;
        vector<mint> a, b;
        rep(i, sz / 2) {
            a.pb(v[2 * i]);
            b.pb(v[2 * i + 1]);
        }
        trans(a, inverse);
        trans(b, inverse);
        mint m = mint(3).pow((mod - 1) / sz);
        if (inverse) m = m.inv();
        mint now = 1;
        rep(i, sz) {
            v[i] = a[i % (sz / 2)] + now * b[i % (sz / 2)];
            now *= m;
        }
    }

    vector<mint> multiply(const vector<mint> &f, const vector<mint> &g) {
        assert(mod == 998244353);
        vector<mint> nf, ng;
        int sz = 1;
        while (sz < f.size() + g.size() - 1) sz *= 2;
        nf.resize(sz);
        ng.resize(sz);
        rep(i, f.size()) nf[i] = f[i];
        rep(i, g.size()) ng[i] = g[i];
        trans(nf);
        trans(ng);
        rep(i, sz) nf[i] *= ng[i];
        trans(nf, true);
        rep(i, sz) nf[i] /= mint(sz);
        return nf;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    int n;
    cin >> n;
    const int c = 100000;
    vi cnt(c);
    rep(i, n * 2) {
        int h;
        cin >> h;
        h--;
        cnt[h]++;
    }
    using vm = vector<mint>;
    auto cmp = [](const vm &a, const vm &b) { return a.size() > b.size(); };
    priority_queue<vm, vector<vm>, decltype(cmp)> pq{cmp};
    pq.push(vm(1, 1));
    rep(i, c) {
        if (cnt[i] <= 1) continue;
        vm temp(cnt[i] / 2 + 1);
        temp[0] = 1;
        mint now = 1;
        rep2(j, 1, cnt[i] / 2 + 1) {
            now *= comb(cnt[i] - 2 * (j - 1), 2);
            now /= j;
            temp[j] = now;
        }
        pq.push(temp);
    }
    while (pq.size() >= 2) {
        vm a = pq.top();
        pq.pop();
        vm b = pq.top();
        pq.pop();
        pq.push(NTT::multiply(a, b));
    }
    vm v = pq.top();
    mint ans = 0;
    mint m = 1;
    rep2(i, 1, n - v.size() + 1) {
        m *= 2 * i - 1;
    }
    rrep(i, v.size()) {
        if (i < n) m *= 2 * (n - i) - 1;

        mint now = m * v[i];
        if (i & 1) ans -= now;
        else ans += now;
    }
    cout << ans << endl;
}

