int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    vector<ll> f(2*n+1,1);
    for(ll i=1;i<=2*n;i++) f[i]=(f[i-1]*i)%mod;
    vector<ll> finv(2*n+1,1);
    finv[2*n]=fpow(f[2*n],mod-2);
    for(ll i=2*n-1;i>=0;i--) finv[i]=(finv[i+1]*(i+1))%mod;
    auto c=[&](int a,int b)->ll
    {
        ll res=f[a];
        res=(res*finv[b])%mod;
        res=(res*finv[a-b])%mod;
        return res;
    };
    vector<int> cnt(N+1,0);
    for(int i=0;i<2*n;i++)
    {
        int a;
        cin >> a;
        cnt[a]++;
    }
