    for(int i=1;i<=N;i++)
    {
        if(cnt[i]<2) continue;
        vector<ll> now={1};
        for(int j=2;j<=cnt[i];j+=2) now.push_back(c(cnt[i],j));
        bad=convolution<mod>(bad,now);
    }
    vector<ll> p(2*n+1,1);
    for(int i=1;i<=2*n;i++) p[i]=(2*p[i-1])%mod;
    ll res=0;
    for(int i=0;i<=n;i++)
    {
        if((int)bad.size()<=i) break;
        ll now=c(n,i);
        now=(now*f[i])%mod;
        now=(now*f[2*n-2*i])%mod;
        now=(now*p[i])%mod;
        now=(now*bad[i])%mod;
        if((i%2)==0) res=(res+now)%mod;
        else res=(res-now+mod)%mod;
    }
    res=(res*finv[n])%mod;
    res=(res*fpow(p[n],mod-2))%mod;
    cout << res << "\n";
    return 0;
}

