template<class T> inline T POW(T a,ll n){ T r=1; for (; n>0; n>>=1,a*=a){ if (n&1)r*=a; } return r; }
inline ll POW(int a,ll n){ return POW((ll)a,n); }


void solve()
{
	ll n;  cin >> n;
	vector<ll> h(n*2);  rep(i,0,n*2-1){ ll h_; cin>>h_; h[i]=h_; }

	map<ll,ll> cnt;
	each(e,h)cnt[e]++;

	Combination cmb(2*n+10);
	vmll twoinv(2*n+10); //twoinv[i]:2^-i
	twoinv[0]=1;
	twoinv[1]=mll(1)/mll(2);
	rep(i,2,2*n+10-1) twoinv[i]=twoinv[i-1]*twoinv[1];

	auto func=[&](ll N){
		if (N==0) return mll(1);
		return cmb.fact(2*N-1)*twoinv[N-1]*cmb.finv(N-1);
	};

	multimap<ll,vll> mp;
	each(e,cnt){
		ll nm=e.second;
		if (nm<=1)continue;
		auto it=mp.insert(pair<ll,vll>(nm/2,vll()));
		vll &v=it->second;
		rep(k,0,nm/2){
			mll tmp=cmb.P(nm,2*k)*cmb.finv(k)*twoinv[k];
			v.push_back(tmp.val);
		}
	}
	if (mp.empty()){
		cout << func(n) << '\n'; return;
	}

	while (sz(mp)>1){
		auto it=mp.begin();
		vll &v1=it->second;
		it++;
		vll &v2=it->second;

		vll vret=convolution(v1,v2);

		mp.erase(mp.begin());
		mp.erase(mp.begin());
		mp.emplace(move(sz(vret)),move(vret));
	}

	auto it=mp.begin();
	vll &v=it->second;


	mll ans=func(n);
	rep(k,1,sz(v)-1){
		ans += POW(mll(-1),k) * v[k] * func(n-k);
	}
	cout << ans << '\n';
}



