const int jt = 998244353, rg = 3;

int ho[20][1 << 19];

int ksmii(int a, int b) {
	if(!b) return 1;
	int x = ksmii(a, b >> 1);
	x = 1ll * x * x % jt;
	if(b & 1) x = 1ll * x * a % jt;
	return x;
}

void inline fft(vector<int> &a, int L, int l, int inv) {
	if(!ho[l][1]) {
		loop(i, L) ho[l][i] = (ho[l][i >> 1] >> 1) | ((i & 1) << (l - 1));
	}
	loop(i, L) if(ho[l][i] < i) swap(a[i], a[ho[l][i]]);
	range(i, 1, L - 1, i) {
		int omega = ksmii(rg, ~inv ? (jt - 1) / (i << 1) : (jt - 1) - (jt - 1) / (i << 1));
		range(j, 0, L - 1, i << 1) {
			int omg = 1;
			loop(k, i) {
				int x = a[j + k], y = 1ll * omg * a[j + k + i] % jt;
				a[j + k] = (x + y) % jt;
				a[j + k + i] = (x - y + jt) % jt;
				omg = 1ll * omg * omega % jt;
			}
		}
	}
	if(!~inv) {
		int fn = ksmii(L, jt - 2);
		loop(i, L) a[i] = 1ll * a[i] * fn % jt;
	}
}

