	}
	while (heap.size()>=2){
		int x=heap.top();
		heap.pop();
		int y=heap.top();
		heap.pop();
		NTT_times(colors[x],colors[y],colors[++sz]);
		colors[x].clear(),colors[y].clear();
		heap.push(sz);
	}
	ll ans=0;
	for(int i=0;i<colors[sz].size();++i){
		ll v=1ll*colors[sz][i]*cal(n-i)%mod;
		if(i&1){
			ans=(ans-v+mod)%mod;
		}
		else{
			ans=(ans+v)%mod;
		}
	}
	printf("%lld\n",ans);
	return 0;
}

