    int maxPair = 0;
    for (auto &x:v) {
        vector<ll> after = dp;
        for (int prev = 0; prev <= maxPair; prev++) {
            for (int pa = 1; pa <= x / 2; pa++) {
                after[prev + pa] += dp[prev] * (calc_comb(x, pa * 2) * match[pa] % MOD) % MOD;
                if (after[prev + pa] >= MOD)after[prev + pa] -= MOD;
            }
        }
        dp = after, maxPair += x / 2;
    }

    for (int i = 0; i <= n; i++)dp[i] *= match[n - i], dp[i] %= MOD;

    ll ret = 0;
    for (int i = 0; i <= n; i++) {
        if (i % 2 == 0) {
            ret += dp[i];
            if (ret >= MOD)ret -= MOD;
        } else {
            ret -= dp[i];
            if (ret < 0)ret += MOD;
        }
    }

    cout << ret << endl;
    return 0;
}

