  using mint = Mint<998244353>;
  Binomial<mint> C(200200);
  NTT<mint> ntt;
  using vm = FormalPowerSeries<mint>;
  //vm f{1};
  V<vm> fs;
  each(x, cnt) {
    if (x < 2) continue;
    vm v(x / 2 + 1);
    mint c = 1;
    int n = x;
    int m = 0;
    rep(i, x / 2 + 1) {
      if (i) {
        c *= C.C(n, 2);
        n -= 2;
        m += 1;
      }
      v[i] = c * C.finv(m);
    }
    fs.push_back(v);
    //f = ntt.multiply(f, v);
  }
  vm f = Pi<mint>(fs);
  vm pre(N + 1);
  {
    int n = 2 * N;
    int m = 0;
    mint c = 1;
    rep(i, N + 1) {
      if (i) {
        c *= C.C(i * 2, 2);
        m += 1;
      }
      pre[i] = c * C.finv(m);
    }
  }

  mint ans = 0;
  rep(i, sz(f)){
    mint c = f[i];
    c *= pre[N - i];
    ans += (i & 1) ? -c : c;
  }

  out(ans);
}

