int pow(int a, int b, int mod, int r = 1) {
	for(int i = b; i; i >>= 1, a = (1LL * a * a) % mod) if(i & 1) r = (1LL * r * a) % mod;
	return r;
}

int get(int n, int y) {
	int x = fact[n] * pow(fact[n - 2 * y], mod - 2, mod) % mod;
	x = x * pow(pwr[y], mod - 2, mod) % mod;
	return x * pow(fact[y], mod - 2, mod) % mod;
}


vector <int> PWR(int x) {
	vector <int> v(x + 1, 0), res(1, 1);
	v[0] = 1;
	for(int j = 1; j * 2 <= x; j++) {
		v[j * 2] = get(x, j);
	}

	for(int i = ff[x]; i > 0; i >>= 1, v = atcoder ::convolution <mod>(v, v)) if(i & 1) {
		res = atcoder::convolution<mod>(res, v);
	}
	return res;
}

