int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(15);
	srand((unsigned)time(NULL));

	cominit();

	INT(n);
	auto n2 = 2 * n;
	VEC(int, h, n2);
	sort(all(h));
	h = press(h);

	int b = h.back() + 1;
	vector<mint> dbf(n2 + 1);
	dbf[0] = 1;
	dbf[1] = 1;
	for(int i = 2; i < n2 + 1; i++) {
		dbf[i] = dbf[i - 2] * i;
	}

	vi cnt(b);
	rep(i, n2) cnt[h[i]]++;

	VV<int> a(b);


	rep(i, b) {
		int k = cnt[i];
		for(int j = 0; j * 2 <= k; j++) {
			if(j)
				a[i].push_back(((mint)commod(k, j * 2) * dbf[j * 2 - 1]).x);
			else
				a[i].push_back(1);
		}
	}

	auto res = merge_tech(a);

	int sz = res.size();
	mint ans = 0;
	rep(j, sz) {
		mint plus;
		if(j == n)
			plus = res[j];
		else
			plus = dbf[n2 - j * 2 - 1] * res[j];
		if(j % 2 == 1) plus *= -1;
		ans += plus;
	}
	drop(ans);

	return 0;
}

