struct CoordinateCompressor {
private:
    vector<ll> _i2v;
    map<ll, ll> _v2i;
public:
    CoordinateCompressor(const vector<ll>& v) : _i2v(v) {
        sort(_i2v.begin(), _i2v.end());
        _i2v.erase(unique(_i2v.begin(), _i2v.end()), _i2v.end());
        for(ll i = 0; i < _i2v.size(); ++i){ _v2i[_i2v.at(i)] = i; }
    }
    size_t size() const { return _i2v.size(); }
    ll i2v(ll i) const { return _i2v.at(i); }
    ll v2i(ll v) const { return _v2i.at(v); }
};

struct mintcomb{
    vector<mint> fact;
    vector<mint> ifact;
    mintcomb(ll n) : fact(n + 1, 1), ifact(n + 1, 1) {
        for(ll i = 2; i <= n; ++i){
            fact.at(i) = fact.at(i - 1) * i;
            ifact.at(i) = fact.at(i).inv();
        }
    }

    mint factorial(ll k) const { return fact.at(k); }
    mint combination(ll k, ll l) const {
        return fact.at(k) * ifact.at(l) * ifact.at(k - l);
    }
};


