	std::vector<LL> G(n + 1);
	G[0] = 1;
	for (int i = 1; i <= n; ++i) G[i] = G[i - 1] * (2 * i - 1) % M;
	LL ret = 0;
	for (int i = 0; i != r.size(); ++i) {
		ret += (i % 2 == 1 ? -1 : 1) * G[n - i] * r[i] % M;
	}
	print(ret);
	return 0;
}

