                    dp = NTT.multiply(dp, crse);
                }
            } else {
                crso[k] = crso[k - 1] * com(2 * k + 1, 2) * finv[k] % MOD * fact[k - 1] % MOD;
                rep(j, co[i]) {
                    dp = NTT.multiply(dp, crso);
                }
            }
            // dp.resize(100100);
