// @param n `0 <= n`
// @return minimum non-negative `x` s.t. `n <= 2**x`
    int ceil_pow2(int n) {
      int x = 0;
      while ((1U << x) < (unsigned int)(n)) x++;
      return x;
    }

// @param n `1 <= n`
// @return minimum non-negative `x` s.t. `(n & (1 << x)) != 0`
    int bsf(unsigned int n) {
#ifdef _MSC_VER
      unsigned long index;
    _BitScanForward(&index, n);
    return index;
#else
      return __builtin_ctz(n);
#endif
    }

}  // namespace internal




namespace internal {
    template<class mint, internal::is_static_modint_t<mint> * = nullptr>
    void butterfly(std::vector<mint> &a) {
      static constexpr int g = internal::primitive_root<mint::mod()>;
      int n = int(a.size());
      int h = internal::ceil_pow2(n);

      static bool first = true;
      static mint sum_e[30];  // sum_e[i] = ies[0] * ... * ies[i - 1] * es[i]
      if (first) {
        first = false;
        mint es[30], ies[30];  // es[i]^(2^(2+i)) == 1
        int cnt2 = bsf(mint::mod() - 1);
        mint e = mint(g).pow((mint::mod() - 1) >> cnt2), ie = e.inv();
        for (int i = cnt2; i >= 2; i--) {
          // e^(2^i) == 1
          es[i - 2] = e;
          ies[i - 2] = ie;
          e *= e;
          ie *= ie;
        }
        mint now = 1;
        for (int i = 0; i < cnt2 - 2; i++) {
          sum_e[i] = es[i] * now;
          now *= ies[i];
        }
      }
      for (int ph = 1; ph <= h; ph++) {
        int w = 1 << (ph - 1), p = 1 << (h - ph);
        mint now = 1;
        for (int s = 0; s < w; s++) {
          int offset = s << (h - ph + 1);
          for (int i = 0; i < p; i++) {
            auto l = a[i + offset];
            auto r = a[i + offset + p] * now;
            a[i + offset] = l + r;
            a[i + offset + p] = l - r;
          }
          now *= sum_e[bsf(~(unsigned int) (s))];
        }
      }
    }

    template<class mint, internal::is_static_modint_t<mint> * = nullptr>
    void butterfly_inv(std::vector<mint> &a) {
      static constexpr int g = internal::primitive_root<mint::mod()>;
      int n = int(a.size());
      int h = internal::ceil_pow2(n);

      static bool first = true;
      static mint sum_ie[30];  // sum_ie[i] = es[0] * ... * es[i - 1] * ies[i]
      if (first) {
        first = false;
        mint es[30], ies[30];  // es[i]^(2^(2+i)) == 1
        int cnt2 = bsf(mint::mod() - 1);
        mint e = mint(g).pow((mint::mod() - 1) >> cnt2), ie = e.inv();
        for (int i = cnt2; i >= 2; i--) {
          // e^(2^i) == 1
          es[i - 2] = e;
          ies[i - 2] = ie;
          e *= e;
          ie *= ie;
        }
        mint now = 1;
        for (int i = 0; i < cnt2 - 2; i++) {
          sum_ie[i] = ies[i] * now;
          now *= es[i];
        }
      }

      for (int ph = h; ph >= 1; ph--) {
        int w = 1 << (ph - 1), p = 1 << (h - ph);
        mint inow = 1;
        for (int s = 0; s < w; s++) {
          int offset = s << (h - ph + 1);
          for (int i = 0; i < p; i++) {
            auto l = a[i + offset];
            auto r = a[i + offset + p];
            a[i + offset] = l + r;
            a[i + offset + p] =
                (unsigned long long) (mint::mod() + l.val() - r.val()) *
                inow.val();
          }
          inow *= sum_ie[bsf(~(unsigned int) (s))];
        }
      }
    }
}

template<class mint, internal::is_static_modint_t<mint> * = nullptr>
std::vector<mint> convolution(std::vector<mint> a, std::vector<mint> b) {
  int n = int(a.size()), m = int(b.size());
  if (!n || !m) return {};
  if (std::min(n, m) <= 60) {
    if (n < m) {
      std::swap(n, m);
      std::swap(a, b);
    }
    std::vector<mint> ans(n + m - 1);
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ans[i + j] += a[i] * b[j];
      }
    }
    return ans;
  }
  int z = 1 << internal::ceil_pow2(n + m - 1);
  a.resize(z);
  internal::butterfly(a);
  b.resize(z);
  internal::butterfly(b);
  for (int i = 0; i < z; i++) {
    a[i] *= b[i];
  }
  internal::butterfly_inv(a);
  a.resize(n + m - 1);
  mint iz = mint(z).inv();
  for (int i = 0; i < n + m - 1; i++) a[i] *= iz;
  return a;
}

template <unsigned int mod = 998244353,
    class T,
    std::enable_if_t<internal::is_integral<T>::value>* = nullptr>
std::vector<T> convolution(const std::vector<T>& a, const std::vector<T>& b) {
  int n = int(a.size()), m = int(b.size());
  if (!n || !m) return {};

  using mint = static_modint<mod>;
  std::vector<mint> a2(n), b2(m);
  for (int i = 0; i < n; i++) {
    a2[i] = mint(a[i]);
  }
  for (int i = 0; i < m; i++) {
    b2[i] = mint(b[i]);
  }
  auto c2 = convolution(move(a2), move(b2));
  std::vector<T> c(n + m - 1);
  for (int i = 0; i < n + m - 1; i++) {
    c[i] = c2[i].val();
  }
  return c;
}

std::vector<long long> convolution_ll(const std::vector<long long>& a,
                                      const std::vector<long long>& b) {
  int n = int(a.size()), m = int(b.size());
  if (!n || !m) return {};

  static constexpr unsigned long long MOD1 = 754974721;  // 2^24
  static constexpr unsigned long long MOD2 = 167772161;  // 2^25
  static constexpr unsigned long long MOD3 = 469762049;  // 2^26
  static constexpr unsigned long long M2M3 = MOD2 * MOD3;
  static constexpr unsigned long long M1M3 = MOD1 * MOD3;
  static constexpr unsigned long long M1M2 = MOD1 * MOD2;
  static constexpr unsigned long long M1M2M3 = MOD1 * MOD2 * MOD3;

  static constexpr unsigned long long i1 =
      internal::inv_gcd(MOD2 * MOD3, MOD1).second;
  static constexpr unsigned long long i2 =
      internal::inv_gcd(MOD1 * MOD3, MOD2).second;
  static constexpr unsigned long long i3 =
      internal::inv_gcd(MOD1 * MOD2, MOD3).second;

  auto c1 = convolution<MOD1>(a, b);
  auto c2 = convolution<MOD2>(a, b);
  auto c3 = convolution<MOD3>(a, b);

  std::vector<long long> c(n + m - 1);
  for (int i = 0; i < n + m - 1; i++) {
    unsigned long long x = 0;
    x += (c1[i] * i1) % MOD1 * M2M3;
    x += (c2[i] * i2) % MOD2 * M1M3;
    x += (c3[i] * i3) % MOD3 * M1M2;
    // B = 2^63, -B <= x, r(real value) < B
    // (x, x - M, x - 2M, or x - 3M) = r (mod 2B)
    // r = c1[i] (mod MOD1)
    // focus on MOD1
    // r = x, x - M', x - 2M', x - 3M' (M' = M % 2^64) (mod 2B)
    // r = x,
    //     x - M' + (0 or 2B),
    //     x - 2M' + (0, 2B or 4B),
    //     x - 3M' + (0, 2B, 4B or 6B) (without mod!)
    // (r - x) = 0, (0)
    //           - M' + (0 or 2B), (1)
    //           -2M' + (0 or 2B or 4B), (2)
    //           -3M' + (0 or 2B or 4B or 6B) (3) (mod MOD1)
    // we checked that
    //   ((1) mod MOD1) mod 5 = 2
    //   ((2) mod MOD1) mod 5 = 3
    //   ((3) mod MOD1) mod 5 = 4
    long long diff =
        c1[i] - internal::safe_mod((long long)(x), (long long)(MOD1));
    if (diff < 0) diff += MOD1;
    static constexpr unsigned long long offset[5] = {
        0, 0, M1M2M3, 2 * M1M2M3, 3 * M1M2M3};
    x -= offset[diff % 5];
    c[i] = x;
  }

  return c;
}


using mint = modint998244353;

class FHeightsAndPairs {
public:

    vector<mint> get_vec(int n) {
      vector<mint> ret;
      ret.emplace_back(1);
      while(n >= 2) {
        ret.push_back(ret.back());
        ret.back() *= n*(n-1)/2;
        n -= 2;
      }
      return ret;
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;
      vector<int> a(2*n);
      vector<int> posa(100000);
      rep(i, 2*n) {
        cin >> a[i];
        a[i]--;
        posa[a[i]]++;
      }
      vector<int> v;
      rep(i, 100000) {
        if (posa[i] >= 1) {
          v.push_back(posa[i]);
        }
      }

      vector<mint> dp[v.size()];
      priority_queue<P, vector<P>, greater<>> que;
      rep(i, v.size()) {
        dp[i] = get_vec(v[i]);
        debug(i, dp[i].size());
        que.emplace(dp[i].size(), i);
      }

      while(que.size() >= 2) {
        auto p = que.top(); que.pop();
        auto q = que.top(); que.pop();
        int newPos = q.second;
        dp[newPos] = convolution(dp[p.second], dp[q.second]);
        que.emplace(dp[newPos].size(), newPos);
      }

      mint ans = 0;
      auto r = que.top();
      auto& ret = dp[r.second];
      vector<mint> pairs(n);
      pairs[0] = 1;
      for(int i=1; i<n; i++) {
        pairs[i] = pairs[i-1] * (i*2+1);
      }

      for(int i=0; i<ret.size(); i++) {
        mint now = ret[i];
        debug(i, now.val());
        if (i%2!=0) {
          now *= -1;
        }
        now *= pairs[n-1-i];
        ans += now;
      }
      cout << ans.val() << endl;
    }
};

signed main() {
  FHeightsAndPairs solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

