	tatamikomi.at(0) = 1LL; 
	for(int i = 1; i <= 100000; i++){
		if(H[i] >= 2){
			vector<long long> V(H[i] / 2 + 1);
			for(int t = 0; t <= H[i] / 2; t++){
				V[t] = COM(H[i], t*2) * P[t] % MOD; 
			}
			tatamikomi = convolution(tatamikomi, V); 
		}
	}
	long long ans = 0; 
	for(int i = 0; i < (int) tatamikomi.size(); i++){
		long long c = tatamikomi.at(i) % MOD; 
		c *= P[N - i]; c %= MOD; 
		if(i % 2) c *= -1; 
		ans += c; 
		ans += MOD; ans %= MOD; 
	}
	cout << ans << "\n"; 
}

