binomial<modint<998244353>> b;

void main() {
  // start here!
  int n;
  cin >> n;
  const int maxh = 100000;
  vector<int> cnt(maxh);
  for (auto i = 0; i != n * 2; ++i) {
    int h;
    cin >> h;
    --h;
    cnt[h]++;
  }
  auto comp = [](const auto& v1, const auto& v2) {
    return v1.size() > v2.size();
  };
  vector<mint> np{1};
  priority_queue<vector<mint>, decltype(comp)> q(comp);
  for (auto i = 0; i != maxh; ++i) {
    auto nc = cnt[i];
    if (!nc) continue;
    vector<mint> pol{1};
    mint way = 1;
    for (int x = 1; x * 2 <= nc; x++) {
      way *= (x * 2 - 1);
      pol.push_back(way * (int)b(nc, x * 2));
    }
    // np = atcoder::convolution(np, pol);
    q.emplace(pol);
  }
  while (q.size() > 1) {
    auto p1 = q.top();
    q.pop();
    auto p2 = q.top();
    q.pop();
    q.emplace(atcoder::convolution(p1, p2));
  }
  np = q.top();
  mint ans;
  vector<mint> ways(n + 1);
  ways[0] = 1;
  for (int i = 0; i < n; i++) {
    ways[i + 1] = ways[i] * (2 * i + 1);
  }
  for (int j = size(np) - 1; j >= 0; j--) {
    auto now = np[j] * ways[n - j];
    if (j & 1)
      ans -= now;
    else
      ans += now;
  }
  cout << ans.val() << eol;
}
