int main() {
  ll n;
  cin >> n;
  vector<ll> h(2 * n);
  rep(i, 2 * n) cin >> h[i];
  sort(h.begin(), h.end());
  vector<mint> f(2 * n + 1), ff(2 * n);
  f[0] = ff[0] = ff[1] = 1;
  repr(i, 1, 2 * n + 1) f[i] = f[i - 1] * i;
  repr(i, 2, 2 * n) ff[i] = ff[i - 2] * i;
  vector<vector<mint>> forbidden({vector<mint>({1})});
  ll fls = 0;
  ll _fs = 0;
  rep(i, 2 * n) {
    if (i + 1 >= 2 * n || h[i] != h[i + 1]) {
      ll _fw = i + 1 - _fs;
      vector<mint> _fbs(_fw / 2 + 1);
      _fbs[0] = 1;
      repr(j, 1, _fw / 2 + 1) {
        _fbs[j] = f[_fw] / (f[j * 2] * f[_fw - j * 2]) * ff[j * 2 - 1];
      }
      forbidden.push_back(convolution(forbidden[fls], _fbs));
      ++fls;
      _fs = i + 1;
    }
  }
  mint ans = 0;
  rep(i, n + 1) {
    mint counts = i < forbidden[fls].size() ? forbidden[fls][i] : 0;
    mint v = counts * (i == n ? 1 : ff[2 * n - 1 - i * 2]);
    if (i % 2 == 0) {
      ans += v;
    } else {
      ans -= v;
    }
  }
  cout << ans.val() << endl;
}

