void decline(vector<li>& g,int n){
  while(g.size()>n) g.pop_back();
}
vector<li> operator*(const vector<li>& a,const vector<li> & b){
  vector<li> g=atcoder::convolution<MOD>(a,b);
  decline(g,max(a.size(),b.size()));
  return g;
}
vector<li>& operator*=(vector<li>& a,const vector<li> & b){
  auto n=a.size();
  a=atcoder::convolution<MOD>(a,b);
  decline(a,max(n,b.size()));
  return a;
}

vector<li> pow(vector<li> a,int r,int dec=1){
  int n=a.size();
  vector<li> b=a,ans(1,1);
  while(r){
    if(r%2) ans=atcoder::convolution<MOD>(ans,b);
    b=atcoder::convolution<MOD>(b,b);
    if(dec){
      decline(ans,n);
      decline(b,n);
    }
    r/=2;
  }
  return ans;
}

