void solve(int p, int l, int r)
{
	f[p] = np, np += sd[r] - sd[l-1] + 1;
	if(l==r)
	{
		int cur = 1;
		for(int i=0; i<=d[l]; i++)
		{
			f[p][i] = cur;
			cur = 1ll*cur*comb(cnt[l]-2*i, 2)%mod;
		}
		return;
	}
	int mid = (l+r)>>1;
	solve(p<<1, l, mid); solve(p<<1|1, mid+1, r);
	poly::mul(f[p<<1], sd[mid]-sd[l-1], f[p<<1|1], sd[r]-sd[mid], f[p]);
}
