  for(int i=0;i<2*n;i++){
    ll a;scanf("%lld", &a);
    cnt[a]++;
  }

  multimap<int, fps> mp;

  auto binom = [&](ll l, ll r){
    return (((fac[l] * finv[r])%Q) * finv[l-r])%Q;
  };


  vll dfc(n+1, 1);
  for(ll i=0;i<n;i++) dfc[i+1] = (dfc[i] * (2*i+1))%Q;

  //fps t{1};
  for(int i=0;i<500000;i++){
    if(cnt[i]==0) continue;
    fps tmp(cnt[i]/2+1);
    for(ll j=0;j<=cnt[i]/2;j++){
      ll ret = (dfc[0] * binom(cnt[i], 2*j));
      tmp[j] = ret;
    }
    mp.emplace(tmp.size(), tmp);
  }

  mp.emplace(1, fps{1});
  while(mp.size()>1){
    auto L = *mp.begin();
    mp.erase(mp.begin());
    auto R = *mp.begin();
    mp.erase(mp.begin());
    fps mg = L.second * R.second;
    mp.emplace(mg.size(), mg);
  }

  fps ans = (*mp.begin()).second;

  ll A = 0;
  for(ll i=0;i<ans.size();i++){
    if(ans[i]==0) continue;
    ll x = dfc[n-i];
    if(i%2) A = (A + Q - ((ans[i]*x)%Q))%Q;
    else A = (A + (ans[i]*x)%Q)%Q;
    assert(A>=0&&A<Q);
  }

  std::cout << A << '\n';
}

