using namespace std;

const int LOGN = 22;
const int N = (1 << LOGN);
const int mod = 998244353;
const int g = 3;
vector<int> w[LOGN];
vector<int> iw[LOGN];
vector<int> rv[LOGN];

inline int mul(int a, int b){
    return (a * 1ll * b) % mod;
}
inline int norm(int a){
    while(a >= mod)
        a -= mod;
    while(a < 0)
        a += mod;
    return a;
}
inline int binPow(int a, int k){
    int ans = 1;
    while(k > 0){
        if(k & 1)
            ans = mul(ans, a);
        a = mul(a, a);
        k >>= 1;
    }
    return ans;
}
inline int inv(int a){
    return binPow(a, mod - 2);
}

void precalc(){
    int wb = binPow(g, (mod - 1) / (1 << LOGN));

    for(int st = 0; st < LOGN - 1; st++){
        w[st].assign(1 << st, 1);

        int bw = binPow(wb, 1 << (LOGN - st - 1));
        int cw = 1;

        for(int k = 0; k < (1 << st); k++) {
            w[st][k] = cw;
            cw = mul(cw, bw);
        }
    }
    for(int st = 0; st < LOGN; st++){
        rv[st].assign(1 << st, 0);

        if(st == 0){
            rv[st][0] = 0;
            continue;
        }
        int h = (1 << (st - 1));
        for(int k = 0; k < (1 << st); k++)
            rv[st][k] = (rv[st - 1][k & (h - 1)] << 1) | (k >= h);
    }
}

inline void fft(int a[N], int n, bool inverse){
    int ln = 0;
    while((1 << ln) < n)
        ln++;

    assert((1 << ln) < N);
    n = (1 << ln);

    for(int i=0;i<n;i++){
        int ni = rv[ln][i];
        if(i < ni)
            swap(a[i], a[ni]);
    }

    for(int st = 0; (1 << st) < n; st++) {
        int len = (1 << st);
        for(int k = 0; k < n; k += (len << 1)) {
            for(int pos = k; pos < k + len; pos++) {
                int l = a[pos];
                int r = mul(a[pos + len], w[st][pos - k]);

                a[pos] = norm(l + r);
                a[pos + len] = norm(l - r);
            }
        }
    }

    if(inverse) {
        int in = inv(n);
        for(int i=0;i<n;i++)
            a[i] = mul(a[i], in);
        reverse(a + 1, a + n);
    }
}

int aa[N], bb[N], cc[N];
inline vector<int> multiply(const vector<int> a, const vector<int> b) {
    int n = 1;
    while(n < (a.size() + b.size()))
        n <<= 1;

    for(int i=0;i<n;i++)
        aa[i] = (i < a.size() ? a[i] : 0);

    for(int i=0;i<n;i++)
        bb[i] = (i < b.size() ? b[i] : 0);

    fft(aa, n, false);
    fft(bb, n, false);

    for(int i=0;i<n;i++)
        cc[i] = mul(aa[i], bb[i]);

    fft(cc, n, true);

    vector<int> c(n, 0);
    for(int i=0;i<c.size();i++)
        c[i] = cc[i];

    while(c.size() > 1 && c.back() == 0)
        c.pop_back();
    return c;
}

