struct Pint{
	int x;
	inline Pint(){x=0;}
	inline Pint(int b){x=(b%P+P)%P;}
	inline void operator=(int b){x=(b%P+P)%P;}
    inline bool operator==(const Pint &b) const {return x==b.x;}
    inline bool operator!=(const Pint &b) const {return x!=b.x;}
    inline Pint operator+(const Pint &b)const {return x+b.x>=P?x+b.x-P:x+b.x;}
	inline Pint operator-(const Pint &b)const {return x-b.x<0?x-b.x+P:x-b.x;}
	inline Pint operator*(const Pint &b)const {return 1LL*x*b.x%P;}
	inline void operator+=(const Pint &b){x=x+b.x>=P?x+b.x-P:x+b.x;}
	inline void operator-=(const Pint &b){x=x-b.x<0?x-b.x+P:x-b.x;}
	inline void operator*=(const Pint &b){x=1LL*x*b.x%P;}
	inline void read(){
		char c;int a, b;
	    for(c=getchar(),a=0,b=1;c<48||57<c;c=getchar()){
	        if(c==EOF){x=0;return;}
	        if(c=='-')b=-1;
	    }
	    for(;48<=c&&c<=57;c=getchar())a=((a+(a<<2))<<1)+(c^'0');
	    *this=a*b;
	}
};
Pint a[N],b[N],o[N],fac[N],inv[N],ans;
int lim,l,n,m,r[N],h[N],p[N];
inline Pint ksm(Pint x,int y=P-2){
	Pint ans=1;
	for(;y;y>>=1,x*=x)
		if(y&1)ans*=x;
	return ans;
}
inline void init(int len){
    lim=1,l=-1;
    while(lim<=len)lim<<=1,++l;
    for(int i=1;i<lim;i++)r[i]=(r[i>>1]>>1)|((i&1)<<l);
}
inline void NTT(Pint *A,int ty){
    for(int i=0;i<lim;i++)
        if(i<r[i])swap(A[i],A[r[i]]);
    for(int p=1;p<lim;p<<=1){
        int D=p<<1;
		Pint wn=ksm(ty==1?3:Gi,(P-1)/D);
        o[0]=1;
        for(int i=1;i<p;i++)o[i]=o[i-1]*wn;
        for(int i=0;i<lim;i+=D){
            for(int j=0;j<p;j++){
                Pint x=A[i+j],y=A[i+j+p]*o[j];
                A[i+j]=x+y,A[i+j+p]=x-y;
            }
        }
    }
    if(ty==-1){
    	Pint INV__=ksm(lim);
        for(int i=0;i<lim;i++)
            A[i]*=INV__;
    }
}
Pint C(int x,int y){
	return fac[y]*inv[x]*inv[y-x];
}
Pint A(int x,int y){
	return fac[y]*inv[y-x];
}
vector<Pint>f[N];
priority_queue<PII,vector<PII>,greater<PII> >Q;

int main(){
	scanf("%d",&n),n*=2;
    for(int i=1;i<=n;i++)scanf("%d",&h[i]);
    sort(h+1,h+1+n);
    for(int i=1;i<=n;i++){
    	if(h[i]!=h[i-1])p[++m]=1;
    	else p[m]++;
	}
	fac[0]=1;
	for(int i=1;i<=n;i++)fac[i]=fac[i-1]*i;
	inv[n]=ksm(fac[n]);
	for(int i=n-1;~i;i--)inv[i]=inv[i+1]*(i+1);
	for(int i=1;i<=m;i++){
    	for(int j=0;j<=(p[i]>>1);j++){
    		f[i].push_back(A(j,p[i])*C(j,p[i]-j)*ksm(ksm(2,j)));
		}
		Q.push(PII(f[i].size(),i));
	}
	while(Q.size()>1){
		int u=Q.top().second;
		Q.pop();
		int v=Q.top().second;
		Q.pop(); 
		int su=f[u].size(),sv=f[v].size();
		init(su+sv-2);
		for(int i=0;i<=lim;++i) a[i]=0,b[i]=0;
		for(int i=0;i<su;++i) a[i]=f[u][i];
		for(int i=0;i<sv;++i) b[i]=f[v][i];
		NTT(a,1),NTT(b,1);
		for(int i=0;i<lim;i++) a[i]=a[i]*b[i];
		NTT(a,-1);
		++m;
		if(!Q.size()){
			for(int i=0;i<=su+sv-2;++i)
				ans+=ksm(-1,i)*a[i]*A((n-2*i)>>1,n-2*i)*ksm(ksm(2,(n-2*i)>>1));
			break;
		}
		for(int i=0;i<=su+sv-2;++i) f[m].push_back(a[i]);
		Q.push(PII(f[m].size(),m));
	}
	printf("%d\n",ans.x);
}

