	while(q.size() > 1){
		int a = q.top().x; q.pop();
		int b = q.top().x; q.pop();
		r[a] = convolution(r[a], r[b]);
		std::vector<int>().swap(r[b]);
		q.push((Node){a});
	}
	std::vector<int> res(r[q.top().x]);
	int ans = 0;
	for(int i = 0; i < res.size(); ++i){
		res[i] = (ll)res[i] * pair_count(n - i) % MOD;
		if(i & 1) ans = (ans - res[i]) % MOD;
		else ans = (ans + res[i]) % MOD;
	}
	std::printf("%d\n", (ans + MOD) % MOD);
}

