ll bigmod(ll a, ll p, ll m){
    ll res=1,x=a;
    while(p){
        if(p&1) res=(res*x)%m;
        x=(x*x)%m;
        p=p>>1;
    }
    return res;
}

void precalc(){
    fact[0]=1;
    for(int i=1;i<mx;i++) fact[i]=(fact[i-1]*i)%mod;
    inv[mx-1]=bigmod(fact[mx-1],mod-2,mod);
    for(int i=mx-2;i>=0;i--) inv[i]=(inv[i+1]*(i+1))%mod;
}

ll nCr(ll n, ll r){
    return ((fact[n]*inv[n-r])%mod*inv[r])%mod;
}

bool cmp(vector<int> a, vector<int> b){
    return (int)a.size()<(int)b.size();
}

vector<int> call(int l, int r){
    if(l==r) return c[l];
    int mid=(l+r)>>1;
    return multiply(call(l,mid),call(mid+1,r),mod);
}

