    for(int i=0;i<=100000;i+=2){
        f[i]=((fact[i]*inv[i/2])%mod*bigmod(bigmod(2,i/2,mod),mod-2,mod))%mod;
    }
    for(int i=1;i<=100000;i++){
        c[i]=vector<int> (cnt[i]+1,0);
        c[i][0]=1;
        for(int j=2;j<=cnt[i];j+=2){
            c[i][j]=(nCr(cnt[i],j)*f[j])%mod;
        }
    }
    vector<int> res=call(1,100000);
    res.resize(2*n+1);
    ll ans=0;
    for(int i=0;i<=2*n;i+=2){
        int sgn=(i/2)&1?mod-1:1;
        ll tmp=(res[i]*f[2*n-i]*sgn)%mod;
        (tmp+=mod)%=mod;
        ans=(ans+tmp)%mod;
    }
    cout<<ans<<endl;
    return 0;
}

