    NumberTheoreticTransform<MOD> NTT;
    auto dfs=[&](auto self,int l,int r)->vector<mint>{
        if (r-l==1) return a[l];
        int mid=(l+r)>>1;
        return NTT.multiply(self(self,l,mid),self(self,mid,r));
    };
    vector<mint> dp=dfs(dfs,0,MAX_H);

    mint ans=0;
    for (int i=0;i<dp.size();++i){
        dp[i]*=COM.fac(2*N-2*i)*COM.finv(N-i)/POW[N-i];
        if (i&1) ans-=dp[i];
        else ans+=dp[i];
    }

    cout << ans << '\n';
}

