        cnt[x]++;
    }
    mod_build();
    priority_queue<P,vector<P>,greater<P>> pq;
    rep(i,101010){
        int m=cnt[i];
        if(m<2)continue;
        vector<int> a(m/2+1);
        ll ret = 1;
        rep(j,m/2+1){
            a[j]=ret;
            ret *= comb(m-2*j,2);
            ret %= mod;
            ret *= inv[j+1];
            ret%=mod;
        }
        pq.push({m,a});
    }
    auto ntt = NumberTheoreticTransform(mod,3);
    while(pq.size()>1){
        auto p1 = pq.top();pq.pop();
        auto p2 = pq.top();pq.pop();
        auto res = ntt.Multiply(p1.v, p2.v);
        pq.push({(int)res.size(),res});
