using ssegmenttree = ssegment_tree<ll>;

ll minleftl(lsegmenttree& lst, ll l0, ll r0, ll K, ll x) {
    ll left = l0;
    ll right = l0 + 1;
    for (ll i = 0; i < 100; i++) {
        ll maxval = lst.query(left, right);
        if (x - K <= maxval && maxval <= x + K) {
            if (right - left <= 1) {
                ll a = lst.query(left, left);
                if (a == maxval) {
                    return left;
                } else {
                    return right;
                }
            }
            left = left + (right - left) / 2;
        } else {
            right = left + (right - left) * 2;
            right = min(right, r0);
        }
    }
    return INF;
}

ll minlefts(ssegmenttree& sst, ll l0, ll r0, ll K, ll x) {
    ll left = l0;
    ll right = l0 + 1;
    for (ll i = 0; i < 100; i++) {
        ll minval = sst.query(left, right);
        if (x - K <= minval && minval <= x + K) {
            if (right - left <= 1) {
                ll a = sst.query(left, left);
                if (a == minval) {
                    return left;
                } else {
                    return right;
                }
            }
            left = left + (right - left) / 2;
        } else {
            right = left + (right - left) * 2;
            right = min(right, r0);
        }
    }
    return INF;
}

int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }

    auto lst = lsegmenttree(N, -INF);
    auto sst = ssegmenttree(N, INF);
    for (ll i = 0; i < N; i++) {
        lst.update(i, A[i]);
        sst.update(i, A[i]);
    }

    vector<ll> dp(N, 0);
    dp[N - 1] = 1;
    for (ll i = N - 2; i >= 0; i--) {
        ll minnext = min(minleftl(lst, i + 1, N - 1, K, A[i]), minlefts(sst, i + 1, N - 1, K, A[i]));
        //      print(i, minnext);
        if (minnext == INF) {
            dp[i] = dp[i + 1];
        } else {
            dp[i] = max(dp[i + 1], 1 + dp[minnext]);
        }
    }
    print(dp[0]);
}

