		++cnt[x];
	}
	std::vector<LL> r(1, 1);
	LL inv2 = (M + 1) / 2;
	std::sort(cnt.begin(), cnt.end());
	auto start = std::lower_bound(cnt.begin(), cnt.end(), 1);
	cnt = std::vector<int>(start, cnt.end());
	for (auto x : cnt) if (x > 0) {
		std::vector<LL> a(x / 2 + 1);
		LL p2j = 1;
		for (int j = 0; j <= x / 2; ++j) {
			a[j] = fac[x] * ifac[x - 2 * j] % M * ifac[j] % M * p2j % M;
			p2j = p2j * inv2 % M;
		}
		mul(r, a);
	}
	std::vector<LL> G(n + 1);
	G[0] = 1;
	for (int i = 1; i <= n; ++i) G[i] = G[i - 1] * (2 * i - 1) % M;
	LL ret = 0;
	for (int i = 0; i < r.size() && i <= n; ++i) {
		ret += (i % 2 == 1 ? -1 : 1) * G[n - i] * r[i] % M;
	}
	print((ret % M + M) % M);
	return 0;
}

