    reps(i, 2 * N) { fact[i] = fact[i - 1] * i; }
    reps(i, N) { dfact[i] = dfact[i - 1] * (i * 2 - 1); }
    auto rec = [&](auto &&rec, int l, int r) -> vector<mint> {
        if (r - l == 1) {
            int K = cnt[l] / 2 + 1;
