mint inv[100001];
mint fact[100001];
mint finv[100001];
mint _fact2[100001];

void compare_fact(int n, int mod) {
	int i;

	inv[1] = 1;
	for (i = 2; i <= n; i++) {
		inv[i] = -inv[mod % i] * (mod / i);
	}

	fact[0] = finv[0] = 1;
	for (i = 1; i <= n; i++) {
		fact[i] = i * fact[i - 1];
		finv[i] = inv[i] * finv[i - 1];
	}

	_fact2[0] = _fact2[1] = 1;
	for (i = 2; i <= n; i++) {
		_fact2[i] = i * _fact2[i - 2];
	}
}

mint fact2(int n) {
	if (n < 0) return 1;
	return _fact2[n];
}

mint comb(int n, int k) {
	return fact[n] * finv[k] * finv[n - k];
}

int n;
int h[100000];		//高さは0～99999の範囲にする
int cnt[100000];	//cnt[h] = 高さhの人数
mint dp[2][50001];	//dp(i)[j] = 高さ<iまでで、同じ身長のペアをjペア指定し、それらを全て使う方法の数

mint f(int i, int k) {
	return comb(cnt[i], 2 * k) * fact2(2 * k - 1);
}

int main() {
	int i, j, k;

	int hmax = 0;

	cin >> n;
	rep(i, 2 * n) {
		cin >> h[i];
		h[i]--;
		cnt[h[i]]++;
		hmax = max(hmax, h[i]);
	}

	compare_fact(2 * n, 998244353);

	dp[0][0] = 1;
	rep(i, hmax + 1) {
		rep(j, n + 1) dp[1][j] = 0;
		rep(j, n + 1) {
			rep(k, cnt[i] / 2 + 1) {
				if (j + k > n) break;
				dp[1][j + k] += f(i, k) * dp[0][j];
			}
		}
		rep(j, n + 1) dp[0][j] = dp[1][j];
	}

	mint ans = 0;
	rep(i, n + 1) {
		if (i % 2 == 0) {
			ans += dp[0][i] * fact2(2 * n - 2 * i - 1);
		}
		else {
			ans -= dp[0][i] * fact2(2 * n - 2 * i - 1);
		}
	}
	cout << ans.val() << endl;

	return 0;
}

