  static uint64_t reduce(const u128 w) {
    return uint64_t(w >> 64) + mod - ((u128(uint64_t(w) * inv) * mod) >> 64);
  }
  static UnsafeMod omega() {
    return UnsafeMod(prim_root).pow((mod - 1) >> level);
