const int mod = 998244353, g = 3, mxn = 1 << 17;

int qp(int x, int n) {
	int ans = 1;
	for (; n; n >>= 1, x = 1LL * x * x % mod)
		if (n & 1) ans = 1LL * ans * x % mod;
	return ans;
}

inline int inv(int x) { return qp(x, mod - 2); }

void FFT(vector <int>& a, bool flag = 0) {
	static int r[mxn];
	int n = a.size(), k = __builtin_ctz(n);
	for (int i = 1; i < n - 1; ++ i) {
		r[i] = (r[i >> 1] >> 1) | (i & 1) << (k - 1);
		if (i < r[i]) swap(a[i], a[r[i]]);
	}
	for (int h = 2; h <= n; h <<= 1) {
		int w = qp(g, (mod - 1) / h);
		for (int i = 0; i < n; i += h) {
			int wn = 1;
			rep(j, h >> 1) {
				int u = a[i + j], v = 1LL * a[i + j + (h >> 1)] * wn % mod;
				a[i + j] = (u + v) % mod;
				a[i + j + (h >> 1)] = (u + mod - v) % mod;
				wn = 1LL * wn * w % mod;
			}
		}
	}
	if (flag) {
		reverse(a.begin() + 1, a.end());
		int in = inv(n);
		rep(i, n) a[i] = 1LL * a[i] * in % mod;
	}
}

struct poly : vector <int> {
	poly(int n) { clear(); resize(n, 0); }
	poly operator* (const poly& rhs) const {
		int sz = 1, n = size() + rhs.size() - 1;
		while (sz < n) sz <<= 1;
		vector <int> A(sz), B(sz), C(sz);
		rep(i, size()) A[i] = at(i);
		rep(i, rhs.size()) B[i] = rhs.at(i);
		FFT(A); FFT(B);
		rep(i, sz) C[i] = 1LL * A[i] * B[i] % mod;
		FFT(C, 1);
		poly ans(n);
		rep(i, ans.size()) ans[i] = C[i];
		return ans;
	}
};

int fac[mxn], ifac[mxn], ways[mxn];

struct __INIT {
	__INIT() {
		rep(i, mxn) ways[i] = i ? 1LL * (i * 2 - 1) * ways[i - 1] % mod : 1;
		rep(i, mxn) fac[i] = i ? 1LL * i * fac[i - 1] % mod : 1;
		ifac[mxn - 1] = inv(fac[mxn - 1]);
		for (int i = mxn - 1; i; -- i) ifac[i - 1] = 1LL * i * ifac[i] % mod;
	}
} __init;

int comb(int n, int m) {
	if (m < 0 || m > n) return 0;
	return 1LL * fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}

vector <int> solve(const vector <int>& a) {
	priority_queue <pair <int, poly> > pq;
	rep(i, a.size()) {
		poly p(a[i] / 2 + 1);
		rep(j, a[i] / 2 + 1)
			p[j] = 1LL * comb(a[i], j * 2) * ways[j] % mod;
		pq.push(mp(-a[i], p));
	}
	while (pq.size() > 1) {
		pair <int, poly> p = pq.top(); pq.pop();
		pair <int, poly> q = pq.top(); pq.pop();
		int nw = p.first + q.first;
		poly po = p.second * q.second;
		pq.push(mp(nw, po));
	}
	return pq.top().second;
}

