		cnt[a] ++;
	}
	vector <int> a;
	rep(i, cnt.size()) if (cnt[i]) a.pb(cnt[i]);
	vector <int> po = solve(a);
	int ans = 0;
	rep(i, po.size()) {
		int cur = po[i];
		cur = 1LL * cur * ways[n - i] % mod;
		// cerr << i << " " << cur << endl;
		if (i & 1) ans = (ans + mod - cur) % mod;
		else ans = (ans + cur) % mod;
	}
	printf("%d\n", ans);
	return 0;
}

