        vec r1 = res1.second, r2 = res2.second;

        vec c = atcoder::convolution(r1, r2);
        st.insert({res1.first + res2.first - 1, c});
    }

    vec finaldp = (*st.begin()).second;

    for (int i = 0; i <= n; i++) {
        if (i + 1 > finaldp.size()) {
            dp[i] = 0;
        } else {
            dp[i] = finaldp[i];
        }
    }

    ll value = 1ll, s = 2 * n;
    ll chose = n;
    for (int i = 0; i <= n; i++) {

        dp[i] *= ((value * c2table[s]) % mod);
        dp[i] %= mod;

        value *= chose;
        chose --;

        value %= mod;

        s -= 2;
    }
    ll sign = 1ll, ans = 0;
    for (int i = 0; i <= n; i++) {
        ans += (sign * dp[i] + mod);
        ans %= mod;
        sign *= -1;
    }
    ans *= mypow(fact[n], mod - 2, mod);
    ans %= mod;
    p(ans);
    return;
}


