int64_t jyo(int64_t x,int64_t y,int64_t z){
  int64_t H=y; //ここから
       int64_t a=1,b=x,c=1;
       while(H>0){
         a*=2;
         if(H%a!=0){
           H-=a/2;
           c*=b;
           c%=z;
         }
        b*=b;
         b%=z;
      } //ここまで
 return c;
}

