    int n;
    cin>>n;
    ll h[100001]={};
    int n2 = n+n;
    for(int i=0;i<n2;i++){
        int a; cin>>a; h[a]++;
    }
    vector<vector<mint>> v;
    mint fac[n2+1],beki[n2+1];
    fac[0] = 1;
    beki[0] = 1;
    mint m2 = 2;
    for(int i=0;i<n2;i++){
        beki[i+1] = beki[i] * m2;
        fac[i+1] = fac[i] * mint(i+1);
    }
    mint finv[n2+1], inv2 = beki[n].inv();
    finv[n2] = fac[n2].inv();
    for(int i=n2;i>=1;i--){
        finv[i-1] = finv[i] * i;
    }
    for(int i=0;i<=100000;i++){
        if(h[i]){
            vector<mint> ret;
            ret.push_back(1);
            mint now = 1;
            mint cnt = 1;
            while(h[i] >= 2){
                now *= mint(h[i]*(h[i]-1));
                now /= cnt;
                cnt++;
                ret.push_back(now);
                h[i] -= 2;
            }
            v.push_back(ret);
        }
    }
    int r = 0;
    while(r+1 < v.size()){
        auto c = convolution(v[r],v[r+1]);
        r += 2;
        v.push_back(c);
    }
    mint ans = 0;
    for(int i=0;i<v[r].size();i++){
        mint ret = v[r][i] * finv[n-i] * inv2 * fac[n2-i*2];
        if(i%2)ans-=ret;
        else ans += ret;
    }
    cout << ans.val() << endl;


}

