struct Combination
{
    std::vector<long long> fac, inv;
    int maxN;
    long long mod;

    Combination(int maxN, long long mod) : maxN(maxN), mod(mod)
    {
        fac = std::vector<long long>(maxN + 1, 1);
        inv = std::vector<long long>(maxN + 1, 1);

        for (int i = 2; i <= maxN; ++i)
            fac[i] = fac[i - 1] * i % mod;

        long long pow = mod - 2, x = fac[maxN];
        while (pow > 0)
        {
            if (pow & 1)
                inv[maxN] = (inv[maxN] * x) % mod;
            x = x * x % mod;
            pow >>= 1;
        }

        for (int i = maxN; i > 0; --i)
            inv[i - 1] = inv[i] * i % mod;
    }

    long long combination(int n, int r)
    {
        assert(n <= maxN);
        return n < r || r < 0 ? 0 : (fac[n] * inv[r] % mod) * inv[n - r] % mod;
    }

    long long permutation(int n, int r)
    {
        assert(n <= maxN);
        return n < r || r < 0 ? 0 : fac[n] * inv[r] % mod;
    }
};

