    }

    auto comb = Combination(100000, mod);

    vector<ll> acc(n + 1, 1);
    for (ll i = 4; i <= n; i += 2)
    {
        acc[i] = acc[i - 2] * comb.combination(i, 2) % mod;
    }
    ll ans = acc[n] * comb.inv[n >> 1] % mod;

    for (auto &[_, v] : cnt)
    {
        for (ll i = 2; i <= v; i += 2)
        {
            ll sign = ((i >> 1) & 1) ? -1 : 1;
            ans += ((comb.combination(v, i) * comb.inv[i >> 1] % mod) * (acc[n - i] * comb.inv[(n - i) >> 1] % mod) % mod) * sign;
            ans = (ans + mod) % mod;
        }
    }

    cout << (ans + mod) % mod << endl;
}

