const ll INF=0x3f3f3f3f;

using mint = modint998244353;
using poly = vector<mint>;

int cnt[MAXn];
mint fac[MAXn],inv[MAXn];
mint p[MAXn];
mint p2 = mint(1) / mint(2);
mint C(int n,int k){
    return fac[n] * inv[n-k] * inv[k];
}
mint gtp(int x){
    return fac[x] * p[x/2] * inv[x/2];
}
int main(){
    IOS();
    int n;
    cin >> n;
    fac[0] = 1;
    p[0] = 1;
    for (int i=1;i<MAXn;++i) {
        fac[i] = fac[i-1] * i;
        p[i] = p[i-1] * p2;
    }
    inv[MAXn-1] = mint(1) / fac[MAXn-1];
    for (int i=MAXn-2;i>=0;i--) {
        inv[i] = inv[i+1] * mint(i+1);
    }
    for (int i=0;i<2*n;++i) {
        int x;
        cin >> x;
        cnt[x]++;
    }
    struct cmp {
        bool operator () (const poly &a,const poly &b){
            return SZ(a) > SZ(b);
        }
    };
    priority_queue<poly,vector<poly>,cmp> pq;
    for (int i=1;i<MAXn;++i) {
        if (cnt[i] == 0) continue;
        poly tmp = {1};
        for (int j=1;j * 2 <= cnt[i];++j) {
            tmp.eb(C(cnt[i],2*j) * gtp(2*j));
        }
        pq.emplace(tmp);
    }
    while (SZ(pq) > 1) {
        poly a = pq.top();
        pq.pop();
        poly b = pq.top();
        pq.pop();
        poly c = convolution(a,b);
        pq.emplace(c);
    }
    poly ans = pq.top();
    mint tt = 0;
    for (int i=0,sign=1;i<SZ(ans);++i,sign*=-1) {
        tt = tt + sign * ans[i] * gtp(2 * (n-i));
    }
    cout << tt.val()  << endl;
}

