#include<bits/stdc++.h>
using namespace std;
using LL = long long;
using ULL = unsigned long long;
#define rep(i,n) for(int i=0; i<(n); i++)

using MLL = static_modint<998244353>;

const int FZ = 200000;
MLL F[FZ + 1];
MLL I[FZ + 1];
MLL iF[FZ + 1];
MLL G[FZ + 1];

void init() {
    F[0] = I[1] = iF[0] = 1;
    for (int i = 1; i <= FZ; i++) F[i] = F[i - 1] * i;
    for (int i = 2; i <= FZ; i++) I[i] = MLL(i).inv();
    for (int i = 1; i <= FZ; i++) iF[i] = iF[i - 1] * I[i];
    G[0] = 1;
    for (int i = 1; i <= FZ; i++) G[i] = G[i - 1] * (i * 2 - 1);
}
MLL C(int n, int r) { return F[n] * iF[r] * iF[n - r]; }

const int xH = 100001;

int N;
int H[xH] = {};
vector<MLL> X[xH];

int main() {
    cin >> N; N *= 2;
    rep(i, N) { int h; cin >> h; H[h - 1]++; }

    init();

    rep(i, xH) {
        X[i].push_back(1);
        rep(j, H[i] / 2) {
            MLL tmp = X[i].back();
            tmp *= C(H[i] - 2 * j, 2) * I[j + 1];
            X[i].push_back(tmp);
        }
    }

    priority_queue<pair<int, int>> Q;
    rep(i, xH) Q.push({ -int(X[i].size()),i });
    while (Q.size() != 1) {
        auto a = Q.top().second; Q.pop();
        auto b = Q.top().second; Q.pop();
        X[a] = convolution(X[a], X[b]);
        Q.push({ -int(X[a].size()),a });
    }

    auto a = Q.top().second;
    MLL ans = 0;
    rep(i, X[a].size()) {
        X[a][i] *= G[N / 2 - i];
        if (i % 2 == 0) ans += X[a][i];
        else ans -= X[a][i];
    }

    cout << ans.val() << endl;

    return 0;
}

