using mint = modint998244353;
const int MX = 100010;
mint f[MX + 10], fi[MX + 10], df[MX + 10];
mint com(int n, int k) { return f[n] * fi[n - k] * fi[k]; }
void init() {
  f[0] = f[1] = fi[0] = fi[1] = df[0] = df[1] = 1;
  REP(i, 2, MX) {
    f[i] = f[i - 1] * i;
    fi[i] = f[i].inv();
    df[i] = df[i - 2] * i;
  }
}
void answer() {
  init();
  int n;
  cin >> n;
  deque<vector<mint> > freq;
  {
    map<int, int> mp;
    rep(i, 2 * n) {
      int h;
      cin >> h;
      mp[h]++;
    }
    for (auto [k, v] : mp) {
      freq.emplace_back(vector<mint>());
      freq.back().emplace_back(1);
      for (int i = 1; 2 * i <= v; i++) {
        freq.back().emplace_back(com(v, 2 * i) * df[2 * i - 1]);
      }
    }
  }
  while (freq.size() > 1) {
    deque<vector<mint> > p;
    swap(freq, p);
    while (p.size() > 1) {
      auto a = p.front();
      p.pop_front();
      auto b = p.front();
      p.pop_front();
      freq.emplace_back(convolution(a, b));
    }
    if (p.size() == 1) freq.emplace_back(p.back());
  }
  freq[0].resize(n + 1, 0);
  mint ans = 0;
  repc(i, n) {
    mint cur = 1;
    if (i < n) cur = df[2 * (n - i) - 1];
    cur *= freq[0][i];
    if (i % 2) cur = -cur;
    ans += cur;
  }
  cout << ans.val() << '\n';
}

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  answer();
  return 0;
}

