int new_dp[2 * MAX_N + 1];

int f[2 * MAX_N + 1];
int inv_f[2 * MAX_N + 1];

int power(int a, int b) {
	if (b == 0) return 1;
	int result = power(a, b / 2);
	return (ll) result * result % MOD * (b % 2 == 1 ? a : 1) % MOD;
}

int C(int n, int r) {
	return (ll) f[n] * inv_f[n - r] % MOD * inv_f[r] % MOD;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	int n;
	cin >> n;
