        for(int i=1;i<v.size();i++){
            v[i] = perm(t, 2*i) * inv2pow[i] % MOD;
        }
        qu.emplace(v);
    }
    while(qu.size() >= 2){
        auto a = qu.top(); qu.pop();
        auto b = qu.top(); qu.pop();
        auto v = convolution(a, b);
        qu.emplace(v);
    }
    long long res = 0;
    auto v = qu.top();
    for(int i=0;i<v.size();i++){
        long long rest = N-i;
        long long cur = perm(2*rest, rest) * inv2pow[rest] % MOD;
        if(i%2){
            res = (res + MOD - cur * v[i] % MOD) % MOD;
        } else {
            res = (res + cur * v[i]) % MOD;
        }
    }
    cout << res << endl;
}

