using namespace std;


const int MOD = 998244353;

long long modPow(long long a, long long p){
    if(p == 0) return 1;
    auto res = modPow(a, p/2);
    res = (res*res)%MOD;
    if(p%2) res = (res*a)%MOD;
    return res;
}

long long calcInv(long long a){
    return modPow(a, MOD-2);
}

void ntt(vector<long long>& v, int inv){
    const int n = v.size();
    auto w = modPow(3, (MOD-1)/n);
    if(inv == -1) w = calcInv(w);
    int rev = 0;
    for(int i=1;i<n-1;i++){
        for(int j=n/2;j>(rev^=j);j/=2);
        if(i < rev) swap(v[i], v[rev]);
    }
    for(int m=1;m<n;m*=2){
        auto cur = 1;
        auto rot = modPow(w, n/(2*m));
        for(int i=0;i<m;i++){
            for(int j=i;j<n;j+=2*m){
                auto p = v[j];
                auto q = v[j+m] * cur % MOD;
                v[j] = (p + q) % MOD;
                v[j+m] = (p + MOD - q) % MOD;
            }
            cur = (cur * rot) % MOD;
        }
    }
}

vector<long long> convolution(const vector<long long>& a, const vector<long long>& b){
    int _n = a.size() + b.size();
    int n = 1;
    while(n < _n) n *= 2;
    vector<long long> na(n, 0), nb(n, 0);
    for(int i=0;i<a.size();i++) na[i] = a[i];
    for(int i=0;i<b.size();i++) nb[i] = b[i];
    ntt(na, 1);
    ntt(nb, 1);
    for(int i=0;i<n;i++) na[i] = na[i] * nb[i] % MOD;
    ntt(na, -1);
    auto inv = calcInv(n);
    for(int i=0;i<n;i++) na[i] = na[i] * inv % MOD;
    na.resize(a.size() + b.size() - 1);
    return na;
}

bool op(const vector<long long>& a, const vector<long long>& b){ return a.size() < b.size(); }

int main(){
    const int maxSize = 100001;
    vector<long long> inv(maxSize);
    vector<long long> fact(maxSize);
    vector<long long> factInv(maxSize);
    for(int i=0;i<2;i++) inv[i] = fact[i] = factInv[i] = 1;
    for(int i=2;i<maxSize;i++){
        inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
        fact[i] = fact[i-1] * i % MOD;
        factInv[i] = factInv[i-1] * inv[i] % MOD;
    }
    auto comb = [&](int n, int r){
        if(n < r || r < 0) return 0LL;
        return fact[n] * factInv[n-r] % MOD * factInv[r] % MOD;
    };
    auto perm = [&](int n, int r){
        if(n < r || r < 0) return 0LL;
        return fact[n] * factInv[n-r] % MOD;
    };
    vector<long long> inv2pow(maxSize);
    inv2pow[0] = 1;
    for(int i=1;i<maxSize;i++) inv2pow[i] = inv2pow[i-1] * inv[2] % MOD;
    int N; cin >> N;
    vector<int> cnt(100001, 0);
    for(int i=0;i<2*N;i++){
        int h; cin >> h;
        cnt[h]++;
    }
    vector<vector<long long>> p(100001);
    priority_queue<int, vector<int>, function<bool(int, int)>> qu(
        [&](int a, int b){ return p[a].size() > p[b].size(); }
    );
    p[0].push_back(1);
    qu.push(0);
    for(int i=0;i<cnt.size();i++){
        int t = cnt[i];
        if(t < 2) continue;
        vector<long long> v(t/2 + 1);
        v[0] = 1;
        for(int i=1;i<v.size();i++){
            v[i] = perm(t, 2*i) * inv2pow[i] % MOD * factInv[i] % MOD;
        }
        p[i] = v;
        qu.emplace(i);
    }
    while(qu.size() >= 2){
        auto a = qu.top(); qu.pop();
        auto b = qu.top(); qu.pop();
        p[a] = convolution(p[a], p[b]);
        qu.emplace(a);
    }
    long long res = 0;
    auto& v = p[qu.top()];
    for(int i=0;i<v.size();i++){
        long long rest = N-i;
        long long cur = perm(2*rest, rest) * inv2pow[rest] % MOD;
        if(i%2){
            res = (res + MOD - cur * v[i] % MOD) % MOD;
        } else {
            res = (res + cur * v[i]) % MOD;
        }
    }
    cout << res << endl;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e7 + 5;
int n, h[N], cnt[N], d[N], sd[N];
int *f[N], buf[N<<5], *np(buf);
int fac[N], ifac[N], g[N];
const int mod = 998244353, G = 3;
int up, w[N], rev[N];
int fpw(int a, int b)
{
	int ans = 1;
	while(b)
	{
		if(b&1) ans = 1ll*ans*a%mod;
		a = 1ll*a*a%mod;
		b >>= 1;
	}
	return ans;
}
namespace poly
{
	void init(int n)
	{
		up = 1; int l = 0;
		while(up<=n) up <<= 1, l++;
		for(int i=0; i<up; i++) rev[i] = (rev[i>>1]>>1)|((i&1)<<(l-1));
		int wn = fpw(G, mod>>l); w[up>>1] = 1;
		for(int i=(up>>1)+1; i<up; i++) w[i] = 1ll*w[i-1]*wn%mod;
		for(int i=(up>>1)-1; i>=1; i--) w[i] = w[i<<1];
	}
	void clear(int *a, int n) { memset(a, 0, n<<2); }
	int getlen(int n) { return 1<<(32-__builtin_clz(n)); }
	inline void mul(int *a, int n, int x, int *b) { while(n--) *b++ = 1ll**a++*x%mod; }
	inline void dot(int *a, int *b, int n, int *c) { while(n--) *c++ = 1ll**a++**b++%mod; }
	void DFT(int *a, int l)
	{
		static unsigned long long tmp[N];
		int u = __builtin_ctz(up/l), t;
		for(int i=0; i<l; i++) tmp[i] = a[rev[i]>>u];
		for(int i=1; i^l; i<<=1)
			for(int j=0, d=i<<1; j^l; j+=d)
				for(int k=0; k<i; k++)
					t = tmp[i|j|k]*w[i|k]%mod, tmp[i|j|k] = tmp[j|k]+mod-t, tmp[j|k] += t;
		for(int i=0; i<l; i++) a[i] = tmp[i]%mod;
	}
	void IDFT(int *a, int l)
	{
		reverse(a+1, a+l); DFT(a, l);
		mul(a, l, mod-mod/l, a);
	}
	inline void conv(int *a, int *b, int l) { DFT(a, l); DFT(b, l); dot(a, b, l, a); IDFT(a, l); }
	void mul(int *a, int n, int *b, int m, int *c)
	{
		static int l, ta[N], tb[N]; 
		l = getlen(n+m);
		for(int i=0; i<=n; i++) ta[i] = a[i];
		for(int i=0; i<=m; i++) tb[i] = b[i];
		conv(ta, tb, l);
		for(int i=0; i<=n+m; i++) c[i] = ta[i];
		clear(ta, l), clear(tb, l);
	}
}
void init(int n)
{
	fac[0] = 1;
	for(int i=1; i<=n; i++) fac[i] = 1ll*fac[i-1]*i%mod;
	ifac[n] = fpw(fac[n], mod-2);
	for(int i=n-1; i>=0; i--) ifac[i] = 1ll*ifac[i+1]*(i+1)%mod;
}
int comb(int a, int b)
{
	if(a<b||b<0||a<0) return 0;
	return 1ll*fac[a]*ifac[b]%mod*ifac[a-b]%mod;
}
void solve(int p, int l, int r)
{
	f[p] = np, np += sd[r] - sd[l-1] + 1;
	if(l==r)
	{
		int cur = 1;
		for(int i=0; i<=d[l]; i++)
		{
			f[p][i] = cur;
			cur = 1ll*cur*comb(cnt[l]-2*i, 2)%mod;
		}
		return;
	}
	int mid = (l+r)>>1;
	solve(p<<1, l, mid); solve(p<<1|1, mid+1, r);
	poly::mul(f[p<<1], sd[mid]-sd[l-1], f[p<<1|1], sd[r]-sd[mid], f[p]);
}
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cin >> n;
	int mx = 0;
	init(2*n);
	poly::init(n);
	for(int i=1; i<=2*n; i++) 
	{
		cin >> h[i];
		cnt[h[i]]++;
		mx = max(mx, h[i]);
	}
	for(int i=1; i<=mx; i++)
	{
		d[i] = cnt[i]/2;
		sd[i] = sd[i-1] + d[i];
	}
	solve(1, 1, mx);
	if(sd[mx]>n) while(1);
	for(int i=0; i<=sd[mx]; i++)
		g[i] = 1ll*f[1][i]*fac[2*n-2*i]%mod*ifac[n-i]%mod*fpw(fpw(2, n-i), mod-2)%mod;
	int ans = 0;
	for(int i=0; i<=sd[mx]; i++)
	{
		if(i&1) ans = (ans - g[i] + mod)%mod;
		else ans = (ans + g[i])%mod;
		//cout << g[i] << '\n';
	}
	cout << ans << '\n';
	return 0;
}

