    int m = cnt[i] / 2;
    FPS g(m + 1);
    for (int j = 0; j <= m; j++) {
      g[j] = Comb::nCr(cnt[i], 2 * j) * Comb::nPr(2 * j, j) / Mint(2).pow(j);
    }
    fs.emplace_back(g);
  }
  int n = fs.size();
  FPS f({1});
  for (int i = 0; i < n / 2; i++) f *= fs[i];
  FPS g({1});
  for (int i = n / 2; i < n; i++) g *= fs[i];
  f = f.pre(N + 1);
  g = g.pre(N + 1);
  auto h = f * g;
  h.resize(N + 1, 0);
  Mint ans = 0;
  for (int i = 0; i <= N; i++) {
    Mint tmp = h[i] * Comb::nPr(2 * N - 2 * i, N - i) / Mint(2).pow(N - i);
    ans += i & 1 ? -tmp : tmp;
  }
  cout << ans << '\n';
  return 0;
}

