template< typename T >
struct Combination {
  vector< T > _fact, _rfact, _inv;

  Combination(int sz) : _fact(sz + 1), _rfact(sz + 1), _inv(sz + 1) {
    _fact[0] = _rfact[sz] = _inv[0] = 1;
    for(int i = 1; i <= sz; i++) _fact[i] = _fact[i - 1] * i;
    _rfact[sz] /= _fact[sz];
    for(int i = sz - 1; i >= 0; i--) _rfact[i] = _rfact[i + 1] * (i + 1);
    for(int i = 1; i <= sz; i++) _inv[i] = _rfact[i] * _fact[i - 1];
  }

  inline T fac(int k) const { return _fact[k]; }

  inline T finv(int k) const { return _rfact[k]; }

  inline T inv(int k) const { return _inv[k]; }

  T P(int n, int r) const {
    if(r < 0 || n < r) return 0;
    return fac(n) * finv(n - r);
  }

  T C(int p, int q) const {
    if(q < 0 || p < q) return 0;
    return fac(p) * finv(q) * finv(p - q);
  }

  T H(int n, int r) const {
    if(n < 0 || r < 0) return (0);
    return r == 0 ? 1 : C(n + r - 1, r);
  }
};

using mint=modint<MOD>;
const int MAX_H=100010;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    Combination<mint> COM(MAX_H);
    int N; cin >> N;
    vector<int> cnt(MAX_H,0);
    for (int i=0;i<2*N;++i){
        int h; cin >> h;
        ++cnt[h];
    }

    vector<vector<mint>> a(MAX_H);
    vector<mint> POW(MAX_H+1,1);
    for (int i=0;i<MAX_H;++i){
        POW[i+1]=POW[i]*2;
        mint prod=1;
        for (int j=0;j<=cnt[i]/2;++j){
            a[i].emplace_back(prod);
            if (j+1>cnt[i]/2) break;
            prod*=COM.C(cnt[i]-2*j,2);
            prod*=COM.inv(j+1);
        }
    }

    NumberTheoreticTransform<MOD> NTT;
    auto dfs=[&](auto self,int l,int r)->vector<mint>{
        if (r-l==1) return a[l];
        int mid=(l+r)>>1;
        return NTT.multiply(self(self,l,mid),self(self,mid,r));
    };
    vector<mint> dp=dfs(dfs,0,MAX_H);

    mint ans=0;
    for (int i=0;i<dp.size();++i){
        dp[i]*=COM.fac(2*N-2*i)*COM.finv(N-i)/POW[N-i];
        if (i&1) ans-=dp[i];
        else ans+=dp[i];
    }

    cout << ans << '\n';
}

