  vector<ll> h(2 * n);
  rep(i, 2 * n) cin >> h[i];
  sort(h.begin(), h.end());
  vector<mint> f(2 * n + 1), ff(2 * n), finv(2 * n + 1);
  f[0] = ff[0] = ff[1] = finv[0] = 1;
  repr(i, 1, 2 * n + 1) {
    f[i] = f[i - 1] * i;
    finv[i] = finv[i - 1] / i;
  }
  repr(i, 2, 2 * n) ff[i] = ff[i - 2] * i;
  auto fbps_cp = [](const vector<mint>& a, const vector<mint>& b) { return a.size() > b.size(); };
  priority_queue<vector<mint>, vector<vector<mint>>, decltype(fbps_cp)> fbps(fbps_cp);
  ll _fs = 0;
  rep(i, 2 * n) {
    if (i + 1 >= 2 * n || h[i] != h[i + 1]) {
      ll _fw = i + 1 - _fs;
      if (_fw >= 2) {
        vector<mint> _fbs(_fw / 2 + 1);
        _fbs[0] = 1;
        repr(j, 1, _fw / 2 + 1) {
          _fbs[j] = f[_fw] * finv[j * 2] * finv[_fw - j * 2] * ff[j * 2 - 1];
        }
        fbps.push(move(_fbs));
      }
      _fs = i + 1;
    }
  }
  vector<mint> forbidden({1});
  while (!fbps.empty()) {
    auto top = fbps.top();
    forbidden = convolution(forbidden, top);
    fbps.pop();
  }
  mint ans = 0;
  rep(i, n + 1) {
    if (i >= forbidden.size()) break;
    mint counts = forbidden[i];
    mint v = counts * (i == n ? 1 : ff[2 * n - 1 - i * 2]);
    if (i % 2 == 0) {
      ans += v;
    } else {
      ans -= v;
    }
  }
  cout << ans.val() << endl;
}

