        static int h1[N],h2[N]; 
        int len=n-m+1,x=calc(len);
        copy(h1,a,n); copy(h2,b,m); 
        clear(h1,n,x); clear(h2,m,x);
        reverse(h1,h1+n); reverse(h2,h2+m); 
        getinv(h2,c,x); mult(c,h1,x,x); reverse(c,c+len); clear(c,len);
    }
}

