void init(int n) {
	jc[0]=1; for(int i=1;i<=n;i++) jc[i]=jc[i-1]*i%mod;
	inv[n]=power(jc[n]); for(int i=n;i;i--) inv[i-1]=inv[i]*i%mod;
}
ll C(int x,int y) {
	if(x<y || y<0) return 0;
	return jc[x]*inv[y]%mod*inv[x-y]%mod;
}

void solve(int l,int r) {
	if(l==r) return ;
	int mid=(l+r)/2;
	solve(l,mid);
	solve(mid+1,r);
	P::mult(f[l],f[mid+1],sz[l],sz[mid+1]);
}

