template<int S>
struct Comb
{
	LL r[S+1];
	LL f[S+1];
	LL inv[S+1];
	LL mod;
	Comb(int m)
	{
		mod=m;
		inv[1]=1;
		for(int i=2;i<=S;i++){
			inv[i]=(m-m/i)*inv[m%i]%m;
		}
		f[0]=1;
		r[0]=1;
		for(LL i=1;i<=S;i++){
			f[i]=i*f[i-1]%m;
			r[i]=inv[i]*r[i-1]%m;
		}
	}
	LL c(int n,int i){
		if(i<0||n<i)
		{
			//assert(0);
			return 0;
		}
		return f[n]*r[i]%mod*r[n-i]%mod;
	}
};
Comb<L> comb(M);
LL C(int n,int i){
	return comb.c(n,i);
}

LL df[L];
void solve(long long N, std::vector<long long> h){
	df[0]=1;
	for(int i=1;i<L;i++){
		df[i]=df[i-1]*(2*i-1)%M;
	}
	map<int,int> cnt;
	for(auto v:h){
		cnt[v]++;
	}
	vector<vector<LL>> cur,nex;
	for(auto p:cnt){
		int s=p.second;
		vector<LL> b;
		for(int i=0;2*i<=s;i++){
			b.push_back(C(s,2*i)*df[i]%M);
		}
		cur.push_back(b);
	}
	while(cur.size()>1){
		nex.clear();
		for(auto i=0;i<cur.size();i+=2){
			if (i+1<cur.size()){
				nex.push_back(atcoder::convolution(cur[i],cur[i+1]));
			}
			else{
				nex.push_back(cur[i]);
			}
		}
		nex.swap(cur);
	}
	LL ret=0;
	auto& cs=cur[0];
	LL sg=1;
	for(int i=0;i<cs.size();i++){
		ret+=(M+sg)*cs[i]%M*df[N-i]%M;
		ret%=M;
		sg=-sg;
	}
	cout << ret << endl;

}

