		mx = max(mx, h[i]);
	}
	for(int i=1; i<=mx; i++)
	{
		d[i] = cnt[i]/2;
		sd[i] = sd[i-1] + d[i];
	}
	solve(1, 1, mx);
	for(int i=0; i<=sd[mx]; i++)
		g[i] = 1ll*f[1][i]*fac[2*n-2*i]%mod*ifac[n-i]%mod*fpw(fpw(2, n-i), mod-2)%mod;
	int ans = 0;
	for(int i=0; i<=sd[mx]; i++)
	{
		if(i&1) ans = (ans - g[i] + mod)%mod;
		else ans = (ans + g[i])%mod;
		//cout << g[i] << '\n';
	}
	cout << ans << '\n';
	return 0;
}

