int base=1; vi roots = {0, 1}, rev = {0, 1};
int max_base=17; //x such that 2^x|(mod-1) & 2^x>max answer size(=2*n)
int root=202376916; //primitive root^((mod-1)/(2^max_base))
void ensure_base(int nbase) {
	if (nbase <= base) {return; }
	assert(nbase <= max_base);rev.resize(1<<nbase);
	for (int i=0; i<(1 << nbase); i++){
	  rev[i] = (rev[i >> 1] >> 1) + ((i & 1) << (nbase - 1)); }
	roots.resize(1 << nbase); 
	while (base < nbase) {
	  int z=power(root,1<<(max_base - 1 - base));
	  for (int i = 1 << (base - 1); i < (1 << base); i++) {
	    roots[(i << 1) | 1] = roots[i];
	    roots[(i << 1)] = mul(roots[i], z);
	  } base++; } }
void fft(vector<int> &a, bool invert=0) {
	int n=(int)a.size(); assert((n&(n - 1))==0);
	int zeros=__builtin_ctz(n); ensure_base(zeros);
	int shift = base-zeros;
	for (int i = 0; i < n; i++) {
	  if (i < (rev[i] >> shift)) 
	  	swap(a[i], a[rev[i] >> shift]); }
	for (int k = 1; k < n; k <<= 1) {
	  for (int i = 0; i < n; i += 2 * k) {
	    for (int j = 0; j < k; j++) {
	      int x = a[i + j];
	      int y = mul(a[i + j + k], (invert? inv(roots[j+k]):roots[j+k] ));
	      a[i + j] = x + y - mod;
	      if (a[i + j] < 0) a[i + j] += mod;
	      a[i + j + k] = x - y + mod;
	      if(a[i + j + k] >= mod)a[i+j+k] -= mod;
	}}}
	int inn=inv(n); 
	if(invert)for(auto &z:a)z=mul(z,inn); }
vector<int> multiply(vector<int> a, vector<int> b, int eq = 0) {
	int need=(int)(a.size()+b.size())-1; 
	int nbase=0; while((1 << nbase)<need) nbase++;
	ensure_base(nbase); int sz = 1 << nbase;
	a.resize(sz); b.resize(sz); fft(a);
	if (eq) b = a; else fft(b);
	int inv_sz = inv(sz);
	for (int i = 0; i < sz; i++) {
	  a[i] = mul(mul(a[i], b[i]) , inv_sz); }
	reverse(a.begin(), a.end()); fft(a, 0);
	a.insert(a.begin(), a.back());
	a.resize(need); return a; }	
