const int N = 2e5 + 10;
int cnt[N];

mint fact[N], i_f[N];

mint dp[N];
void preprocess(){
	fact[0] = 1;
	i_f[0] = 1;
	dp[0] = 1;
	for(int i = 1; i < N; ++i){
		fact[i] = fact[i - 1] * i;
		i_f[i] = i_f[i - 1] / i;
		if (~i & 1)
			dp[i] = dp[i - 2] * (i - 1);
	}
}

mint ncr(int n,int r){
	if (r < 0 || r > n)
		return 0;
	return fact[n] * i_f[r] * i_f[n - r];
}

mint ways(int y,int k){
	if (2 * k > y){
		return 0;
	}

	return ncr(y, 2 * k) * dp[2 * k];
}

vector<int> adj[4 * N];


void make_vec(vector<int>& A, int y){
	A.clear();
	for(int k = 0; 2 * k <= y; ++k){
		mint res = ways(y, k);
		A.push_back(res.value());
	}
}

int merge(int x,int y){
	assert(x != y);
	vector<int> cur = multiply(adj[x], adj[y]);
	if (adj[x].size() < adj[y].size()){
		swap(x, y);
	}
	adj[y].clear();
	adj[x].clear();
	for(auto e: cur){
		adj[x].push_back(e);
	}
	return x;
}
