		if (cnt[i] <= 1){
			continue;
		}
		values.push_back(cnt[i]);
	}
	if (values.size() == 0){
		cout << dp[2 * n] << endl;
		return;
	}
	sort(all(values));
	set<pair<int,int>> tot;

	for(int i = 0; i < values.size(); ++i){
		make_vec(adj[i], values[i]);
		tot.insert({adj[i].size(), i});
	}

	while(tot.size() > 1){
		auto X = *tot.begin();
		tot.erase(X);
		auto Y = *tot.begin();
		tot.erase(Y);
		int pos = merge(X.second, Y.second);
		tot.insert({adj[pos].size(), pos});
	}

	int pos = (*tot.begin()).second;


	mint ans = 0;
	assert(adj[pos].size() <= n + 1);
	mint mul = 1;
	for(int k = 0; k <= n && k < adj[pos].size(); ++k){
		mint cur = dp[2 * (n - k)];
		cur *= adj[pos][k];
		ans += cur * mul;

		mul *= -1;
	}	
	cout << ans << endl;


}
