const int mod = 998244353, root = 3;

ll pot (ll b, ll p) {
	if (p < 0) p += mod - 1;
	ll res = 1;
	while (p) {
		if (p & 1) (res *= b) %= mod;
		(b *= b) %= mod;
		p /= 2;
	}
	return res;
}

int nearestPowerOfTwo (int n) {
	int ans = 1;
	while (ans < n)
		ans <<= 1;
	return ans;
}

void ntt (vi &x, int inv) {
	int n = x.size();

	for(int i = 1, j = 0; i < n - 1; i++){
		for(int k = n >> 1; (j ^= k) < k; k >>= 1);
		if(i < j)
			swap(x[i], x[j]);
	}

	vl wp(n >> 1, 1);
	for(int k = 1; k < n; k <<= 1){
		ll wk = pot(root, inv * (mod - 1) / (k << 1));

		for (int j = 1; j < k; ++j)
			wp[j] = wp[j - 1] * wk % mod;

		for (int i = 0; i < n; i += k << 1) {
			for (int j = 0; j < k; ++j) {
				int u = x[i + j], v = x[i + j + k] * wp[j] % mod;
				x[i + j] = u + v < mod ? u + v : u + v - mod;
				x[i + j + k] = u - v < 0 ? u - v + mod : u - v;
			}
		}
	}

	if (inv == -1) {
		ll nrev = pot(n, mod - 2);
		for(int i = 0; i < n; i++)
			x[i] = x[i] * nrev % mod;
	}
}

void mul (vi &a, vi &b) {
	int sz = a.size() + b.size() - 1;
	int size = nearestPowerOfTwo(sz);

	a.resize(size), b.resize(size);
	ntt(a, 1), ntt(b, 1);

	for(int i = 0; i < size; i++)
		a[i] = 1ll * a[i] * b[i] % mod;

	ntt(a, -1);
	a.resize(sz);
}

const int MX = 100005;
int n, h[MX], cn[MX];
ll fac[MX], inv[MX], f[MX];
vi p[MX];
priority_queue<ii, vii, greater<ii>> pq;

ll comb (int n, int k) {
	return fac[n] * inv[k] % mod * inv[n - k] % mod;
}

int main () {
	ios_base::sync_with_stdio(0); cin.tie(0);

	fac[0] = inv[0] = 1;
	for (int i = 1; i < MX; i++) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = pot(fac[i], mod - 2);
	}

	cin >> n;
	forn (i, 2 * n) {
		int a;
		cin >> a;
		cn[a]++;
	}

	f[0] = f[1] = 1;
	for (int i = 2; i < MX; i++)
		f[i] = f[i - 1] * (2 * i - 1) % mod;

	forn (i, MX) {
		p[i].resize(cn[i] / 2 + 1);

		p[i][0] = 1;
		for (ll j = 1; j <= cn[i] / 2; j++)
			p[i][j] = comb(cn[i], 2 * j) * f[j] % mod;

		if (p[i].size() > 1) pq.emplace(p[i].size(), i);
	}

	while (pq.size() > 1) {
		int x = pq.top().se; pq.pop();
		int y = pq.top().se; pq.pop();

		mul(p[x], p[y]);
		p[y].clear();

		pq.emplace(p[x].size(), x);
	}

	ll res = 0;

	if (pq.size()) {
		int i = pq.top().se;

		for (int j = 0, s = 1; j < p[i].size(); j++, s *= -1)
			(res += s * p[i][j] * f[n - j]) %= mod;

		cout << MOD(res, mod) << endl;
	} else {
		cout << f[n] << endl;
	}

	return 0;
}

