const int MOD = 998244353;
const ld PI = acos((ld) -1);

typedef decay<decltype(MOD)>::type T;
struct mi {
    T val;
    explicit operator T() const { return val; }
    mi() { val = 0; }
    mi(const ll& v) {
        val = (-MOD <= v && v <= MOD) ? v : v % MOD;
        if (val < 0) val += MOD; }
    friend ostream& operator<<(ostream& os, const mi& a) { return os << a.val; }
    friend void pr(const mi& a) { pr(a.val); }
    friend void re(mi& a) { ll x; re(x); a = mi(x); }
    friend bool operator==(const mi& a, const mi& b) { return a.val == b.val; }
    friend bool operator!=(const mi& a, const mi& b) { return !(a == b); }
    friend bool operator<(const mi& a, const mi& b) { return a.val < b.val; }
    mi operator-() const { return mi(-val); }
    mi& operator+=(const mi& m) {
        if ((val += m.val) >= MOD) val -= MOD;
        return *this; }
    mi& operator-=(const mi& m) {
        if ((val -= m.val) < 0) val += MOD;
        return *this; }
    mi& operator*=(const mi& m) { val = (ll) val * m.val % MOD;
        return *this; }
    friend mi pow(mi a, ll p) {
        mi ans = 1; assert(p >= 0);
        for (; p; p /= 2, a *= a) if (p & 1) ans *= a;
        return ans; }
    friend mi inv(const mi& a) { assert(a != 0); return pow(a, MOD - 2); }
    mi& operator/=(const mi& m) { return (*this) *= inv(m); }
    friend mi operator+(mi a, const mi& b) { return a += b; }
    friend mi operator-(mi a, const mi& b) { return a -= b; }
    friend mi operator*(mi a, const mi& b) { return a *= b; }
    friend mi operator/(mi a, const mi& b) { return a /= b; }
};

typedef pair<mi,mi> pmi;
typedef vector<mi> vmi;
typedef vector<pmi> vpmi;
#include<atcoder/convolution>
using namespace atcoder;
int main(){
    setIO("");
    int n; re(n);
    vi h(2*n);
    f0r(i, 2*n) re(h[i]);
    n *= 2;
    sort(all(h));
    vmi fact(n+5);
    vmi ifact(n+5);
    fact[0] = ifact[0] = 1;
    f1r(i, 1, n+5){
        fact[i] = fact[i-1]*i;
        ifact[i] = ifact[i-1]/i;
    }
    auto choose = [&](int x, int y) -> mi {
        if(x<y) return 0;
        return fact[x]*ifact[x-y]*ifact[y];
    };
    map<int, int> cnt;
    f0r(i, n){
        cnt[h[i]]++;
    }
    vector<ll> res(1);
    res[0] = 1;
    for(auto x: cnt){
        int num = x.s;
        if(num==1)continue;
        vector<ll> use(num/2+1);
        int cur = num;
        mi run = 1;
        f0r(i, num/2+1){
            use[i] = (run*ifact[i]).val;
            run *= choose(cur,2);
            cur -= 2;
        }

        res = convolution<MOD>(res, use);
    }
    mi ans = 0;
    vmi comp(n+1);
    mi run = 1;
    for(int i = 0; i <= n; i += 2){
        comp[i] = run * ifact[i/2];
        run *= choose(i+2,2);
    }
    f0r(i, sz(res)){
        int num = n-2*i;
        ans += res[i]*comp[num]*(i%2==0?1:-1);
    }
    ps(ans);
    return 0;
}

