void solve() {
    ll n;
    cin >> n;
    map<ll, ll> mp;
    rep(i, 2 * n) {
        ll h;
        cin >> h;
        mp[h]++;
    }
    vector<vector<mint>> vvm;
    vvm.push_back({1});
    for(auto i = mp.begin(); i != mp.end(); ++i) {
        if(i->second == 1) continue;
        vector<mint> vm = {1};
        for(int j = 2; j <= i->second; j += 2) {
            mint k = i->second - j + 2;
            vm.push_back(vm.back() * k * (k - 1) / j);
        }
        vvm.push_back(vm);
    }
    set<pll> st;
    for(int i = 0; i < vvm.size(); ++i) {
        st.emplace(vvm.size(), i);
    }
    while(st.size() > 1) {
        int i1 = st.begin()->second;
        st.erase(st.begin());
        int i2 = st.begin()->second;
        st.erase(st.begin());
        vvm[i1] = convolution(vvm[i1], vvm[i2]);
        st.emplace(vvm[i1].size(), i1);
    }
    vector<mint> d = {1};
    for(ll i = 1; i <= n; ++i) {
        d.push_back(d.back() * (2 * i - 1));
    }
    mint ans = 0;
    mint pn = 1;
    vector<mint> &vm = vvm[st.begin()->second]; 
    for(ll i = 0; i < vm.size(); ++i) {
        ans += pn * d[n - i] * vm[i];
        pn *= -1;
    }
    cout << ans.val() << endl;
    return;
}

