  }

  //初めて0以外が現れるのが奇数次数or初めに現れる数が平方根でない場合不可能(size0のFPSを返す)
  FPS sqrt(int deg=-1){
    const int n = this->size();
    if(deg==-1) deg = n;
    if((*this)[0]==0){
      for(int i=1;i<n;i++) {
        if((*this)[i]!=0){
          if(i&1){
