    rep(i, cnt.size()) {
        int num = cnt[i];
        Poly<Mint> v(num + 1);
        Mint way = 1;
        v[0] = 1;
        for (int j = 1; j * 2 <= num; ++j) {
            way = way * (j * 2 - 1);
            v[j] = way * comb(num, j * 2);
        }
        vec.pb(v);
    }
