      vec.push_back(fact[c] * finv[i * 2] * finv[c - i * 2] * setting[i] * finv[i]);
    }
    meth = meth * fps(vec);
  }
  fp ans(0);
  rep(i,0,meth.size()) {
    if(i > N) break;
    fp res = meth[i] * setting[N - i] * finv[N - i];
    if(i % 2 == 0) {
      ans += res;
    }
    else {
      ans -= res;
    }
  }
  cout << ans.value() << endl;
}

