template <typename T>
vector<pair<T, int>> rle(const vector<T>& a) {
    vector<pair<T, int>> res;
    if (a.empty()) return res;
    res.emplace_back(a[0], 0);
    for (size_t i = 0; i < a.size(); ++i) {
        if (res.back().first == a[i]) res.back().second++;
        else res.emplace_back(a[i], 1);
    }
    return res;
}

