vector<mint> fft(vector<mint> a,bool inverse = false){
  int n = a.size();
  int h = 0;
  for(int i=0;(1<<i)<n;++i) ++h;

  rep(i,n){
    int j =0;
    rep(k,h) j |= (i>>k&1) << (h-1-k);
    if(i<j) swap(a[i],a[j]);
  }

  mint g = mint(3).pow((MOD-1)/n);
  for(int b=1;b<n;b*=2){
    mint w(1);
    mint base = g.pow(n/(2*b));
    if(inverse) base = base.inv();
    rep(j,b){
      for(int k=0;k<n;k+=b*2){
	mint s = a[j+k];
	mint t = a[j+k+b]*w;
	a[j+k] = s+t;
	a[j+k+b] = s-t;
      }
      w *= base;
    }
  }
  mint ninv = mint(n).inv();
  if(inverse) rep(i,n) a[i] *= ninv;;

  return a;
}

vector<mint> convolve(vector<mint> a,vector<mint> b){
  int s = a.size() + b.size() - 1;
  int t = 1;
  while(t<s) t*=2;
  a.resize(t);
  b.resize(t);
  vector<mint> A = fft(a);
  vector<mint> B = fft(b);
  rep(i,t){
    A[i] *= B[i];
  }
  A = fft(A,true);
  a.resize(s);
  rep(i,s) a[i] = A[i];
  return a;
}


