  constexpr int MAX = 100000;

  void solve(){
    int N; std::cin >> N;
    std::vector<int> h(2 * N); std::cin >> h;

    std::vector<int> count(MAX);
    for(int i = 0; i < 2 * N; ++i) count[h[i] - 1] += 1;

    count.erase(
      std::remove_if(count.begin(), count.end(), [](const auto &a){return a == 0;}),
      count.end()
    );

