    auto sf = semifactorial<mint>(2 * N);
    auto ft = factorial_table<mint>(2 * N);
    auto ntt = number_theoretic_transform<mint, PRIM, 1 << 20>();

    std::vector<std::vector<mint>> a;
    for(auto x : count){
      std::vector<mint> temp;

      temp.push_back(1);

      for(int i = 1; i <= x / 2; ++i){
        temp.push_back(ft.C(x, x - 2 * i) * sf(2 * i - 1));
      }

      //dump(temp);

      a.push_back(temp);
    }

    const int K = a.size();

    std::vector<int> len(K);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;

    for(int i = 0; i < K; ++i){
      len[i] = a[i].size();
      pq.emplace(len[i], i);
    }


    while(pq.size() > 1){
      auto [li, i] = pq.top(); pq.pop();
      auto [lj, j] = pq.top(); pq.pop();

      a[i] = ntt.convolve(a[i], a[j]);
      a[i].resize(li + lj - 1);

      pq.emplace(a[i].size(), i);
    }

    std::vector<mint> d = a[pq.top().second];

    d.resize(N + 1);

    dump(d);

    for(int i = 0; i < N; ++i){
      d[i] *= sf(2 * N - 2 * i - 1);
    }

    dump(d);

    mint ans = 0;
    for(int i = 0; i <= N; ++i){
      if(i % 2) ans -= d[i];
      else ans += d[i];
    }

    std::cout << ans << "\n";
  }
}

