		if(v<1 || v>100000)while(1);
		mx=max(mx,v);
		tong[v]++;
	}
	int sz=0;
	for(int i=1;i<=mx;i++){
		if(tong[i]<2)continue;
		colors[++sz].clear();
		int up=tong[i]/2;
		colors[sz].push_back(1);
		int now=1,left=tong[i],v;
		for(int j=1;j<=up;++j){
			now=1ll*now*C(left,2)%mod;
			v=1ll*now*finv[j]%mod;
			colors[sz].push_back(v);
			//printf("i:%d j:%d v:%d\n",i,j,v);
			left-=2;
		}
		heap.push(sz);
	}
	while (heap.size()>=2){
		int x=heap.top();
		heap.pop();
		int y=heap.top();
		heap.pop();
		NTT_times(colors[x],colors[y],colors[++sz]);
		colors[x].clear(),colors[y].clear();
		heap.push(sz);
	}
	ll ans=0;
	for(int i=0;i<=n;++i){
		ll v=1ll*colors[sz][i]*cal(n-i)%mod;
		if(i&1){
			ans=(ans-v+mod)%mod;
		}
		else{
			ans=(ans+v)%mod;
		}
	}
	printf("%lld\n",ans);
	return 0;
}

