typedef long long ll;
const int MOD = 998244353;
typedef decay<decltype(MOD)>::type T;
struct mi {
    T val;
    explicit operator T() const { return val; }
    mi() { val = 0; }
    mi(const long long& v) {
        val = (-MOD <= v && v <= MOD) ? v : v % MOD;
        if (val < 0) val += MOD; }
    friend ostream& operator<<(ostream& os, const mi& a) { return os << a.val; }
    friend bool operator==(const mi& a, const mi& b) { return a.val == b.val; }
    friend bool operator!=(const mi& a, const mi& b) { return !(a == b); }
    friend bool operator<(const mi& a, const mi& b) { return a.val < b.val; }
    mi operator-() const { return mi(-val); }
    mi& operator+=(const mi& m) {
        if ((val += m.val) >= MOD) val -= MOD;
        return *this; }
    mi& operator-=(const mi& m) {
        if ((val -= m.val) < 0) val += MOD;
        return *this; }
    mi& operator*=(const mi& m) { val = (long long) val * m.val % MOD;
        return *this; }
    friend mi pow(mi a, long long p) {
        mi ans = 1; assert(p >= 0);
        for (; p; p /= 2, a *= a) if (p & 1) ans *= a;
        return ans; }
    friend mi inv(const mi& a) { assert(a != 0); return pow(a, MOD - 2); }
    mi& operator/=(const mi& m) { return (*this) *= inv(m); }
    friend mi operator+(mi a, const mi& b) { return a += b; }
    friend mi operator-(mi a, const mi& b) { return a -= b; }
    friend mi operator*(mi a, const mi& b) { return a *= b; }
    friend mi operator/(mi a, const mi& b) { return a /= b; }
};
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> h(2 * n);
    for (int i = 0; i < 2 * n; i++) {
        cin >> h[i];
    }
    n *= 2;
    vector<mi> fact(n + 5);
    vector<mi> ifact(n + 5);
    fact[0] = ifact[0] = 1;
    for (int i = 1; i < n + 5; i++ ) {
        fact[i] = fact[i - 1] * i;
        ifact[i] = ifact[i - 1] / i;
    }
    auto choose = [&](int x, int y) -> mi {
        if (x < y) {
            return 0;
        }
        return fact[x] * ifact[x - y] * ifact[y];
    };
    map<int, int> cnt;
    for (int i = 0; i < n; i++) {
        cnt[h[i]]++;
    }
    vector<ll> res(1);
    res[0] = 1;
    multiset<pair<int, vector<ll>>> poly;
    poly.emplace(1, res);
    for(auto x: cnt){
        int num = x.second;
        if (num == 1) {
            continue;
        }
        vector<ll> use (num / 2 + 1);
        int cur = num;
        mi run = 1;
        for (int i = 0; i <= num / 2; i++) {
            use[i] = (run * ifact[i]).val;
            run *= choose(cur, 2);
            cur -= 2;
        }
        poly.emplace((int) use.size(), use);
    }
    while (poly.size() >= 2) {
        vector<ll> nxt = convolution<MOD>((*poly.begin()).second, (*next(poly.begin())).second);
        poly.erase(poly.begin());
        poly.erase(poly.begin());
        poly.emplace((int) nxt.size(), nxt);
    }
    res = (*poly.begin()).second;
    mi ans = 0;
    vector<mi> group(n + 1);
    mi run = 1;
    for (int i = 0; i <= n; i += 2) {
        group[i] = run * ifact[i / 2];
        run *= choose(i + 2, 2);
    }
    for (int i = 0; i < res.size(); i++) {
        int num = n - 2 * i;
        ans += res[i] * group[num] * (i % 2 == 0 ? 1 : -1);
    }
    cout << ans << '\n';
    return 0;
}

#include<cstdio>
#include<algorithm>
#include<vector>
const long long mod = 998244353;
int h[100005];
int count[100005];
long long f[100005], invf[100005];
long long dp[2][100005];

long long power(long long a,long long b){
    long long res = 1;
    while(b!=0){
        if(b%2) res = res*a%mod;
        a = a*a%mod;
        b /= 2;
    }
    return res;
}

void preWork(int n){
    f[0] = 1;
    for(long long i = 1; i <= n; i++) f[i] = f[i-1]*i%mod;
    invf[n] = power(f[n],mod-2);
    for(long long i = n-1; i >= 0; i--) invf[i] = invf[i+1]*(i+1ll)%mod;
}

long long comb(int n,int m){
    if(m>n || m<0) return 0;
    else return f[n]*invf[n-m]%mod*invf[m]%mod;
}

int min(int a,int b){ return a>b?b:a; }

long long getWay(int x,int y,int z){
    long long res = comb(x,z)*comb(y,z)%mod*f[z]%mod;
    return res;
}

int main(){
    preWork(100000);
    int n;
    scanf("%d",&n);
    n *= 2;
    for(int i = 1; i <= n; i++) scanf("%d",&h[i]);
    std::sort(h+1,h+1+n);
    int p = 1, size = 0;
    while(p<=n){
        int np = p;
        while(np+1<=n && h[np+1]==h[p]) np++;
        count[++size] = np-p+1;
        p = np+1;
    }
    std::sort(count+1,count+1+size);
    int sum = 0;
    dp[1][count[1]] = 1;
    for(int i = 1; i < size; i++){
        sum += count[i];
        int u = i%2, v = (i+1)%2;
        int nSum = sum+count[i+1];
        for(int j = 0; j <= nSum; j++) dp[v][j] = 0;
        for(int j = 0; j <= sum; j++){
            for(int k = 0; k <= min(j,count[i+1]); k++){
                int next = j+count[i+1]-2*k;
                long long add = dp[u][j]*getWay(j,count[i+1],k)%mod;
                dp[v][next] += add; if(dp[v][next]>=mod) dp[v][next] -= mod; 
            }
        }
    }
    printf("%lld\n",dp[size%2][0]);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1e7 + 5;
int n, h[N], cnt[N], d[N], sd[N];
