const double EPS = 1e-9;

ll egcd(ll a, ll b, ll& x, ll& y) {
  if(b == 0) { x = 1; y = 0; return a; }
  ll d = egcd(b, a % b, x, y);
  x -= a / b * y; swap(x, y); return d; }

ll mod_inv(ll a, ll m) {
  ll x, y, d = egcd(a, m, x, y);
  return d == 1 ? (x%m+m)%m : -1; }

ll mod_pow(ll b, ll e, ll m) {
  ll res = 1; while(e) {
    if(e & 1) res = (res*b%m+m)%m;
    b *= b; b %= m; e >>= 1; }
  return res; }

ll primitive_root(ll m) {
  vector<ll> div;
  for (ll i = 1; i*i <= m-1; i++) {
    if ((m-1) % i == 0) {
      if (i < m) div.push_back(i);
      if (m/i < m) div.push_back(m/i); } }
  rep(x,2,m) {
    bool ok = true;
    for(auto it : div) if (mod_pow(x, it, m) == 1) {
      ok = false; break; }
    if (ok) return x; }
  return -1; }

ll next2pow(ll n) {
    ll res = 1;
    while(res < n) res *= 2;
    return res;
}

ll mod = 998244353, g = primitive_root(mod),
  ginv = mod_pow(g, mod-2, mod),
  inv2 = mod_pow(2, mod-2, mod);
#define MAXN (1<<22)
struct Num {
  int x;
  Num(ll _x=0) { x = (_x%mod+mod)%mod; }
  Num operator +(const Num &b) { return x + b.x; }
  Num operator -(const Num &b) const { return x - b.x; }
  Num operator *(const Num &b) const { return (ll)x * b.x; }
  Num operator /(const Num &b) const {
    return (ll)x * b.inv().x; }
  Num inv() const { return mod_pow((ll)x, mod-2, mod); }
  Num pow(int p) const { return mod_pow((ll)x, p, mod); }
} T1[MAXN], T2[MAXN];
void ntt(Num x[], int n, bool inv = false) {
  Num z = inv ? ginv : g;
  z = z.pow((mod - 1) / n);
  for (ll i = 0, j = 0; i < n; i++) {
    if (i < j) swap(x[i], x[j]);
    ll k = n>>1;
    while (1 <= k && k <= j) j -= k, k >>= 1;
    j += k; }
  for (int mx = 1, p = n/2; mx < n; mx <<= 1, p >>= 1) {
    Num wp = z.pow(p), w = 1;
    for (int k = 0; k < mx; k++, w = w*wp) {
      for (int i = k; i < n; i += mx << 1) {
        Num t = x[i + mx] * w;
        x[i + mx] = x[i] - t;
        x[i] = x[i] + t; } } }
  if (inv) {
    Num ni = Num(n).inv();
    rep(i,0,n) { x[i] = x[i] * ni; } } }

vector<ll> fact;

ll binom(ll n, ll k) {
    if(k < 0 || k > n) return 0;
    ll res = fact[n];
    res *= mod_inv(fact[k], mod);
    res %= mod;
    res *= mod_inv(fact[n - k], mod);
    res %= mod;
    return res;
}

ll sol(ll n) {
    ll res = fact[2 * n];
    res *= mod_inv(fact[n], mod);
    res %= mod;
    res *= mod_inv(mod_pow(2, n, mod), mod);
    res %= mod;
    return res;
}

int main() {
    cin.sync_with_stdio(false);
    int n; cin >> n;
    vi h(2 * n); fact = vector<ll>(2 * n + 1, 1);
    rep(i,1,2*n+1) fact[i] = (i * fact[i - 1]) % mod;
    map<int,int> cnt;
    rep(i,0,2*n) {
        cin >> h[i];
        if(!cnt.count(h[i])) cnt[h[i]] = 0;
        cnt[h[i]]++;
    }
    ll n2 = 4 * next2pow(n);
    rep(i,0,n2) T1[i] = Num(0), T2[i] = Num(0);
    T1[0] = Num(1);
    ntt(T1, n2);
    for(auto p : cnt) {
        if(p.sc == 1) continue;
        rep(i,0,n2) T2[i] = Num(binom(p.sc, 2 * i));
        ntt(T2, n2);
        rep(i,0,n2) T1[i] = T1[i] * T2[i];
    }
    ntt(T1, n2, true);
    ll ans = 0, sgn = -1;
    rep(i,0,n) {
        sgn = -sgn;
        ans += ((ll) T1[i].x) * sgn * sol(n - i);
        ans = (ans%mod+mod)%mod;
    }
    cout << ans << '\n';
}

