        mvec num = S.back();
        REP(i, SZ(num)){
            if(i % 2 == 0) ans += G[2 * (N - i)] * num[i];
            else ans -= G[2 * (N - i)] * num[i];
        }
    }else{
        ans = G[2 * N];
    }
    Out(ans);

    return 0;
}

