int main() {
  ll N; cin >> N; N *= 2;
  ll h[N]; rep(i,N) cin >> h[i]; sort(h,h+N);
  map<ll, ll> m; rep(i,N) m[h[i]]++;

  for (auto x: m) {
    if (x.second>N/2) {
      cout << 0 << endl;
      return 0;
    }
  }

  c_fac();
  deque<vector<ll>> dq;
  for (auto x: m) {
    ll l = x.second/2+1;
    vector<ll> count(l);
    rep(i,l) count[i] = i==0 ? 1 : count[i-1]*nck(x.second-(i-1)*2,2)%MOD*inv(i)%MOD;
    if (count.size()>=2) dq.push_back(count);
  }

  while (dq.size()>=2) {
    FastNumberTheoreticTransform FNTT(dq[0].size()+dq[1].size());
    vector<ll> v = FNTT.calc(dq[0],dq[1]);
    dq.pop_front(); dq.pop_front(); dq.push_back(v);
  }
  vector<ll> mul;
  if (dq.size()) mul = dq[0];
  else mul = {1};
  vector<ll> num(N); rep(i,N) num[i] = i==0 ? 1 : num[i-1]*nck(i*2,2)%MOD*inv(i)%MOD;
  // debug(all(mul)); debug(all(num));

  ll result = 0;
  rep(i,mul.size()) result = i%2==0 ? (result+num[N/2-i]*mul[i]%MOD)%MOD : (result-num[N/2-i]*mul[i]%MOD+MOD)%MOD;
  cout << result << endl;
  return 0;
}

