VL differential(VL& f)
{  // f'(x)
    if (sz(f) == 1) return {0};
    VL g(sz(f) - 1);
    for (int i = 1; i < sz(f); i++) g[i - 1] = i * f[i];
    return g;
}
VL integral(VL& f)
{  // ∫f(x)dx
    int n = sz(f) + 1;
    VL g(n);  // g[0] = 0
    if (n == 1) return g;
    int bg = sz(inv) == 0 ? 2 : sz(inv);
    if (sz(inv) < n) inv.resize(n);
    inv[1] = 1;
    for (int i = bg; i < n; i++) inv[i] = inv[nttmod % i] * (nttmod - nttmod / i);
    for (int i = 1; i < n; i++) g[i] = f[i - 1] * inv[i];
    return g;
}
VL log(VL& f, int deg = -1)
{  // log(f(x))
    if (deg == -1) deg = sz(f);
    assert(deg && f[0] == 1);
    VL f_diff = differential(f);
    VL f_inv = Inv(f, deg);
    VL g = conv(f_diff, f_inv);
    g.resize(deg - 1);
    g = integral(g);
    return g;
}

VL exp(VL& f)  // too slow
{
    int n = sz(f);
    assert(sz(f) && f[0] == 0);
    int _n = getlen(n);
    VL g(1);
    f.resize(_n), g[0] = 1;
    for (int i = 2; i <= _n; i <<= 1)
    {
        VL h(g);
        g = log(g, i);

        for (int j = 0; j < i; j++) g[j] = f[j] - g[j];
        g[0] += 1;
        g = conv(g, h);
        g.resize(i);
    }
    return g.resize(n), g;
}

VL Exp(VL& a, int len = -1)
{
    if (len == -1) len = sz(a);
    assert(sz(a) && a[0] == 0);
    if (len == 1) return {1};

    VL g = Exp(a, (len + 1) >> 1);
    VL c = log(g, len);

    for (int i = 0; i < len; ++i) c[i] = a[i] - c[i];
    c[0] += 1;

    int nn = init_ntt(len, len);
    c.resize(nn), g.resize(nn);
    ntt(c, 1), ntt(g, 1);
    for (int i = 0; i < nn; ++i) g[i] = g[i] * c[i];
    ntt(g, -1);
    g.resize(len);
    return g;
}

VL shiftl(const VL& f, int c) { return VL{f.begin() + c, f.end()}; }

VL shiftr(const VL& f, int c)
{
    VL res(sz(f) + c);
    for (int i = 0; i < sz(f); i++) res[i + c] = f[i];
    return res;
}

