VL pow(const VL& f, LL k)
{
    int n = sz(f), pos = 0;
    while (pos < n && f[pos] == 0) pos++;
    if (pos == n || pos * k >= n) return VL(n, 0);

    VL g = shiftl(f, pos);
    mint b0 = f[pos];
    mint b0inv = b0.inv();
    for (auto& ai : g) ai *= b0inv;

    g = log(g);
    for (auto& ai : g) ai *= k;
    g = Exp(g);

    g = shiftr(g, pos * k);
    g.resize(n);

    mint a0 = b0.pow(k);  // k特别大用拓展欧拉定理 k = k % (phi(mod) + mod)
    for (auto& ai : g) ai *= a0;
    return g;
}

// VL ff, gg;
void cdqfft(VL& f, VL& g, int l, int r)
{
    // cal(l, mid) , res->[mid+1, r], cal(mid+1, r);
    if (l == r) return;

    int mid = (l + r) >> 1;
    cdqfft(f, g, l, mid);

    // f[l, mid] * g[0, r-l] -> [mid+1, r]
    VL ff(mid - l + 1), gg(r - l + 1);  // ff, gg must be half interval
    for (int i = l; i <= mid; i++) ff[i - l] = f[i];
    for (int i = 0; i <= r - l; i++) gg[i] = g[i];

    VL res = conv(ff, gg);
    for (int i = mid + 1; i <= r; i++) f[i] = (f[i] + res[i - l]);

    cdqfft(f, g, mid + 1, r);
}

