///===========================================  template  =======================================================


ll modexpo(ll x, ll n, ll m){
    ll ret = 1;
    while(n){
        if(n&1) ret = ret * x % m;
        x = x * x % m;
        n >>= 1;
    }
    return ret;
}

typedef ll T;
typedef vector<T> poly;
poly roots;					//precomputed roots
ll M;						//mod to be remembered
int N;						//size of stored roots
//m = prime mod, rt = primitve root, max_n = maximum root precal
int precal(ll m, ll rt, int max_n = bt(22)){
    ll k = (m-1);
    N = 1, M = m;
    while(!(k&1) && N < max_n)  k>>=1, N<<=1;
    roots.resize(N+1);
    rt = modexpo(rt, k, M);
    roots[0] = 1;
    for(int i = 1; i<=N; i++)
        roots[i] = roots[i-1] * rt % M;
    return N;				//returns how many precalculated
}

#define nxt(i, m) ( (i)^m^(bt( 31-__builtin_clz((i)^m) )-1) )
//^this returns next to i after reversing w.r.t mask m

void NTT(poly &coefs, poly &values, bool invert = false)	//invert -> inverse DFT
{
    int n = (int)coefs.size(), lg_n = __builtin_ctz(n), mask = (int)bt(lg_n) - 1;
    values.resize(n);		//coefs MUST BE of size 2^k

    for(int i = 0, j = 0; j<n; j++, i = (int)nxt(i, mask))
        values[j] = coefs[i];			//filling values with ordered coefficients

    for(int len = 2, hlen = 1; len<=n; len<<=1, hlen<<=1)		//recursions from base level
        for(int i = 0; i<n; i+=len)			//each part in a level
            for(int j = 0, r = N/len; j < hlen; j++)	//the recursion
            {
                T w = (invert)? roots[N-j*r] : roots[j*r];
                T u = values[i+j], v = values[i+j+hlen]*w % M;
                values[i+j] = u + v;
                if(values[i+j] >= M) values[i+j] -= M;
                values[i+j+hlen] = u - v;
                if(values[i+j+hlen] < 0) values[i+j+hlen] += M;
            }

    if(invert){
        ll inv_n = modexpo(n, M-2, M);
        for(auto &x: values) x = x*inv_n % M;		//final division if inverting
    }
}

void multiply(poly &A, poly &B, poly &C)	//result is stored in C
{
    poly va, vb;
