// Modulo
template<ll Modulo>
struct ModInt {
  using mint = ModInt;
  static constexpr ll modulo = Modulo;
  ll v;
  ModInt() : v{0} {}
  template<class T> ModInt(T x) : v{static_cast<ll>(x)} {}
  friend ostream& operator<<(ostream& ostr, const mint& self) { return ostr << self.v; }

  mint& operator+=(const mint& y) { v += y.v; while (v >= modulo) { v -= modulo; }; return *this; }
  mint& operator-=(const mint& y) { return *this += (modulo - y.v); }
  mint& operator*=(const mint& y) { v = ((v * y.v) % modulo); return *this; }
  mint& operator/=(const mint& y) { return *this *= y.inv(); }
  friend mint operator+(const mint& x, const mint& y) { return mint(x) += y; }
  friend mint operator-(const mint& x, const mint& y) { return mint(x) -= y; }
  friend mint operator*(const mint& x, const mint& y) { return mint(x) *= y; }
  friend mint operator/(const mint& x, const mint& y) { return mint(x) /= y; }
  friend bool operator==(const mint& x, const mint& y) { return x.v == y.v; }
  friend bool operator!=(const mint& x, const mint& y) { return x.v != y.v; }
  mint inv() const { return pow(modulo - 2); }
  mint pow(ll e) const {
    mint x = *this, res = 1;
    while (e > 0) {
      if (e & 1) { res *= x; }
      e >>= 1; x *= x;
    }
    return res;
  }

  // Factorial and binomial
  static inline vector<mint> facts, inv_facts;
  static void makeFactorials(int n) {
    if (!facts.empty()) { return; }
    facts.resize(n + 1); inv_facts.resize(n + 1);
    facts[0] = 1;
    inv_facts[0] = 1;
    FOR(i, 1, n + 1) {
      facts[i] = facts[i - 1] * mint(i);
      inv_facts[i] = inv_facts[i - 1] / mint(i);
    }
  }
  static mint binom(int n, int k) {
    return facts[n] * inv_facts[n - k] * inv_facts[k];
  }

  // Generator
  static constexpr ll const_pow(ll x, ll e, ll m) {
    ll res = 1;
    while (e > 0) {
      if (e & 1) { res = (res * x) % m; }
      e >>= 1; x = (x * x) % m;
    }
    return res;
  }
  static constexpr ll const_findGenerator(ll m) {
    // Factorize "m - 1"
    ll x = m - 1;
    int ps[16] = {};
    int ps_size = 0;
    for (int p = 2; p * p <= x; p++) {
      if (x % p == 0) {
        ps[ps_size++] = p;
        while (x % p == 0) { x /= p; }
      }
    }
    if (x > 1) { ps[ps_size++] = x; }
    // Brute force generator
    for (ll y = 1; y <= m - 1; y++)  {
      bool ok = 1;
      for (int i = 0; i < ps_size; i++) {
        if (const_pow(y, (m - 1) / ps[i], m) == 1) { ok = 0; break; }
      }
      if (ok) { return y; }
    }
    return -1; // assert(0)
  }
  static inline constexpr ll generator_ll     = const_findGenerator(modulo);
  static inline constexpr ll generator_inv_ll = const_pow(generator_ll, modulo - 2, modulo);
  static inline const mint generator          = mint(generator_ll);
  static inline const mint generator_inv      = mint(generator_inv_ll);

  // Precomputation for FFT
  static inline mint roots[32][2] = {};
  static void findRoots() {
    if (roots[0][0] != 0) { return; }
    for (int b = 0; (modulo - 1) % (1 << b) == 0; b++) {
      roots[b][0] = generator.pow((modulo - 1) >> b);
      roots[b][1] = generator_inv.pow((modulo - 1) >> b);
    }
  }

  static inline mint pow2Invs[30] = {};
  static void findPow2Invs() {
    if (pow2Invs[0] != 0) { return; }
    for (int b = 0; b < 30; b++) {
      pow2Invs[b] = mint(1 << b).inv();
    }
  }
};

// FFT
uint32_t reverse32(uint32_t x) {
  x = ((x & 0x55555555U) <<  1) | ((x & 0xaaaaaaaaU) >>  1); // 0101 = 0x5, 1010 = 0xa
  x = ((x & 0x33333333U) <<  2) | ((x & 0xccccccccU) >>  2); // 0011 = 0x3, 1100 = 0xc
  x = ((x & 0x0f0f0f0fU) <<  4) | ((x & 0xf0f0f0f0U) >>  4);
  x = ((x & 0x00ff00ffU) <<  8) | ((x & 0xff00ff00U) >>  8);
  x = ((x & 0x0000ffffU) << 16) | ((x & 0xffff0000U) >> 16);
  return x;
}

template<class mint>
void fft(vector<mint>& f, bool inv) {
  int n = f.size();
  int nb = 0;
  while ((1 << nb) < n) { nb++; }
  FOR(i, 0, n) {
    int j = reverse32(i) >> (32 - nb);
    if (i < j) { swap(f[i], f[j]); }
  }
  for (int lb = 1; lb <= nb; lb++) {
    int l = 1 << lb;
    mint::findRoots();
    mint u = mint::roots[lb][inv];
    for (int i = 0; i < n; i += l) {
      mint z = 1;
      for (int k = 0; k < l / 2; k++) {
        auto& x = f[i + k];
        auto& y = f[i + k + l / 2];
        tie(x, y) = make_tuple(x + z * y, x - z * y);
        z *= u;
      }
    }
  }
  if (inv) {
    mint::findPow2Invs();
    mint inv_n = mint::pow2Invs[nb];
    for (auto& x : f) { x *= inv_n; }
  }
}

constexpr ll modulo = 998244353;
using mint = ModInt<modulo>;

void polymulPow2(vector<mint>& p, vector<mint>& q, vector<mint>& r) {
  fft(p, 0); fft(q, 0);
  FOR(i, 0, (int)p.size()) { r[i] = p[i] * q[i]; }
  fft(r, 1);
}

int pow2Ceil(int n) {
  int b = 0;
  while ((1 << b) < n) { b++; }
  return 1 << b;
}

void polymul(vector<mint>& p, vector<mint>& q, vector<mint>& r) {
  int n = 2 * pow2Ceil(max(p.size(), q.size()));
  p.resize(n); q.resize(n), r.resize(n);
  polymulPow2(p, q, r);
  while (r.size() >= 2 && r.back() == 0) { r.pop_back(); }
}

vector<mint> polymulAll(const vector<vector<mint>>& ps) {
  // Multiply together from small degrees
  auto compare = [](auto& x, auto& y) { return x.size() < y.size(); };
  multiset<vector<mint>, decltype(compare)> heap(compare);
  heap.insert(ALL(ps));
  while (heap.size() >= 2) {
    auto p = *heap.begin(); heap.erase(heap.begin());
    auto q = *heap.begin(); heap.erase(heap.begin());
    polymul(p, q, q);
    heap.insert(q);
  }
  return *heap.begin();
}

