  //   Define
  //     p(x | c) = 1 + x f(2) binom(c, 2) + x^2 f(4) binom(c, 4) + ...
  //   Then,
  //     ∏_j p(x | cnts[j]) = g(0) + x g(1) + x^2 g(2) + ....
  //

  // Define f
  mint::makeFactorials(2 * n);
  const mint inv_2 = mint(2).inv();
  auto f = [&](int k) { return mint::facts[2 * k] * mint::inv_facts[k] * inv_2.pow(k); };

