    for(int i=1;i<=2*n;i++)
    {
        if(i%2==1)
        {
            fun[i]=0;
        }
        else
        {
            fun[i]=(pref * (mod_int)(i-1));
            pref = fun[i];
        }
    }
    vector<vector<mod_int> > p;
