    rep(t,0,len-1)
    {
        int step=1<<t,step2=1<<t+1;
        ll w=wn[t+1][opt];
        for(int i=0;i<n2;i+=step2)
        {
            ll wj=1;
            rep(j,0,step-1)
            {
                ll tmp=wj*a[i+j+step]%mod;
                a[i+j+step]=(a[i+j]-tmp+mod)%mod;
                a[i+j]=(a[i+j]+tmp)%mod;
                wj=wj*w%mod;
            }
