    }
}

void conv(vector<ll> &A,vector<ll> &B)
{
    int n=A.size()+B.size()-1;
    len=0;
    for(n2=1;n2<n;n2<<=1) len++;
    rep(i,0,n2-1) r[i]=(r[i>>1]>>1)|((i&1)<<len-1);
    A.resize(n2,0);
    B.resize(n2,0);
    NTT(A,0);
    NTT(B,0);
    rep(i,0,n2-1) A[i]=A[i]*B[i]%mod;
    NTT(A,1);
    rep(i,0,n2-1) A[i]=A[i]*inv[n2]%mod;
    A.resize(n);
}

