auto main() -> i32 {
	i32 n;
	scanf("%d", &n);
	for (i32 i = 0; i < 2 * n; ++i) {
		i32 h;
		scanf("%d", &h);
		bucket[h] += 1;
	}
	fac[0] = mint(1);
	for (i32 i = 1; i <= n; ++i) {
		fac[i] = mint(i) * fac[i - 1];
	}
	ifac[n] = fac[n].inv();
	for (i32 i = n - 1; i >= 0; --i) {
		ifac[i] = ifac[i + 1] * mint(i + 1);
	}
	std::vector<mint> poly;
	std::vector<mint> poly2;
	poly.emplace_back(1);
	poly2.emplace_back(1);
	i32 p = 0;
	for (i32 i = 0; i < 100000; ++i) {
		if (i64 k = bucket[i]; k >= 2) {
			p += bucket[i] / 2;
			std::vector<mint> b;
			b.emplace_back(1);
			mint x = mint(1);
			for (i64 i = 2; i <= k; i += 2) {
				x *= mint((k - i + 2) * (k - i + 1) / 2) / mint(i / 2);
				b.emplace_back(x);
			}
			if (poly.size() <= n / 2) {
				poly = atcoder::convolution(poly, b);
			} else {
				poly2 = atcoder::convolution(poly2, b);
			}
		}
	}
	poly = atcoder::convolution(poly, poly2);
	std::vector<mint> table;
	table.emplace_back(1);
	for (i32 i = 1; i <= n; ++i) {
		mint x = table[i - 1] * mint(2 * i - 1);
		table.emplace_back(x);
	}
	mint ans = mint(0);
	for (i32 i = 0; i <= p; ++i) {
		ans = ans + (i % 2 == 0 ? poly[i] : -poly[i]) * table[n - i];
	}
	printf("%d\n", ans.val());
	return 0;
}

