void create_mod_tables(int num){
    fact.assign(num+1, 1);
    fact_inv.assign(num+1, 1);
    for(int i=1; i<=num; i++) fact[i] = fact[i-1] * i;
    fact_inv[num] = fact[num].inv();
    for(int i=num; i>0; i--) fact_inv[i-1] = fact_inv[i] * i;
}

modint comb_mod(int n, int k){
    return fact[n] * fact_inv[n-k] * fact_inv[k];
}

int main(){
