	// 二重階乗
	vector<modint> ff(2*N+1, 1);
	for(int i=2; i<=2*N; i++) ff[i] = ff[i-2] * i;

	queue<vector<modint>> que;
	for(auto [k, a] : mp){
		vector<modint> v(a/2+1);
		for(int i=0; i<=a/2; i++){
			v[i] = comb_mod(a, 2*i);
			if(i) v[i] *= ff[2*i-1];
