	rep(i,1,2*n)h[i]=lower_bound(bk+1,bk+1+2*n,h[i])-bk,cnt[h[i]]++;
	rep(i,1,mxid){
		rep(j,0,cnt[i]/2){//use j pair
			gen[i].pb(1ll*C(2*j,cnt[i])*g(j)%mod);
		}
	}
