mint f[2 * MAX_N + 1];

int cnt[MAX_H + 1] = {0};
mint p[MAX_N + 1];

int h[2 * MAX_N];

mint C(int n, int m) {
    return f[n] * (f[n - m] * f[m]).inv();
}

int main(int, char **) {
