        f[i] = f[i - 1] * i;
    }
    p[0] = 1;
    for (int i = 1; i <= MAX_N; i++) {
        p[i] = p[i - 1] * mint(2 * i - 1);
    }

    queue<vector<mint>> q;
    q.push(vector<mint>(1, 1));
    for (int i = 0; i <= MAX_H; i++) {
        if (cnt[i] < 2) continue;
        vector<mint> v(cnt[i] / 2 + 1);
