int f[N], xx[N], yy[N], fact[N], pwr[N];


int pow(int a, int b, int mod, int r = 1) {
	for(int i = b; i; i >>= 1, a = (1LL * a * a) % mod) if(i & 1) r = (1LL * r * a) % mod;
	return r;
}

int get(int n, int y) {
	int x = fact[n] * pow(fact[n - 2 * y], mod - 2, mod) % mod;
	x = x * pow(pwr[y], mod - 2, mod) % mod;
	return x;
}

vector <int> mul(vector <int> a, vector <int> b) {
	vector <int> c(a.size() + b.size(), 0);
	for(int i = 0; i < a.size(); i++) {
		for(int j = 0; j < b.size(); j++) {
			c[i + j] += a[i] * b[j] % mod;
			c[i + j] %= mod;
		}
	}
	return c;
}


int32_t main() {
	ios_base :: sync_with_stdio(0); cin.tie(0); cout.tie(0);
	int n; cin >> n;
	fact[0] = pwr[0] = 1;
	for(int i = 1; i <= 2 * n; i++) {
		int x; cin >> x;
		f[x]++;
		fact[i] = (fact[i - 1] * i) % mod;
		pwr[i] = (pwr[i - 1] * 2) % mod;
	}

	xx[0] = xx[1] = 1;
	yy[0] = yy[1] = 1;

	for(int i = 3; i < N; i += 2) {
		xx[i] = (xx[i - 2] * i) % mod;
		xx[i + 1] = xx[i];
	}

	vector <int> res(1, 1);

	for(int i = 1; i < N; i++) if(f[i] > 1) {
		vector <int> v(f[i] + 1, 0);
		v[0] = 1;
		for(int j = 1; j * 2 <= f[i]; j++) {
			v[j * 2] = get(f[i], j);
		}
		res = atcoder :: convolution <mod> (res, v);
	}

	int ans = xx[2 * n - 1]; //cout << ans << endl;

	for(int i = 1; i <= n; i++) {
		int lft = 2 * n - 2 * i;
		int kk = res[2 * i] * xx[lft] % mod;
		if(i & 1) ans = (ans + mod - kk) % mod;
		else ans = (ans + kk) % mod;
	}

	cout << ans << endl;
}

