using mint = modint998244353;

int main(){

    // 二項係数
    const int n_max = 200000;
    std::vector<mint> fact(n_max);
    fact[0] = 1;
    for (int i = 1; i < n_max; ++i) {
        fact[i] = fact[i - 1] * i;
    }
    const auto comb = [&fact](int n, int r) {
        if(n<r or n<0 or r<0) return mint(0);
        return fact[n] / fact[r] / fact[n - r];
    };
    //

    ll N;
    cin >> N;
    V<ll> h(2*N);
    REP(i, 2*N){
        cin >> h[i];
    }

    map<ll, ll> mp;
    REP(i, 2*N){
        mp[h[i]]++;
    }
    V<ll> cnt;
    for(auto x: mp) cnt.push_back(x.second);
    ll sz = cnt.size();

    // dump(cnt)

    V<mint> tp(n_max);
    tp[0] = 1;
    REP(i, n_max-1) tp[i+1] = tp[i] * 2; 

    V<V<mint>> x(sz);

    REP(i, sz){
        REP(k, cnt[i]/2+1){
            mint res = 1;
            res *= comb(cnt[i], 2*k);
            res *= fact[2*k];
            res /= fact[k];
            res /= tp[k];
            x[i].push_back(res);
        }
    }

    // REP(i, sz){
    //     REP(j, x[i].size()) cout << x[i][j].val() << " ";
    //     cout << endl;
    // }

    queue<ll> qu;
    REP(i, sz) qu.push(i);    

    while((int)qu.size()>1){
        ll q1 = qu.front();qu.pop();
        ll q2 = qu.front();qu.pop();
        x[q1] = convolution(x[q1], x[q2]);
        qu.push(q1);
    }

    ll q = qu.front();
    auto v = x[q];

    sz = v.size();

    REP(k, sz){
        ll t = 2*N - 2*k;
        v[k] *= fact[t];
        v[k] /= fact[t/2];
        v[k] /= tp[t/2];
    }

    // for(auto x: v) cout << x.val() << " ";
    // cout << endl;

    mint res = 0;
    mint mo = mod-1;
    mint kei = 1;
    for(auto x: v){
        res += kei * x;
        kei *= mo;
    }

    cout << res.val() << endl;

    return 0;
}

