signed main() {
    int N;
    cin >> N;
    int M = 100000;
    vint h(2 * N), cnt(M);
    rep(i, 2 * N) { cin >> h[i], h[i]--, cnt[h[i]]++; }
    using mint = modint998244353;
    vector<mint> fact(2 * N + 1), dfact(N + 1);
    fact[0] = dfact[0] = 1;
    reps(i, 2 * N) { fact[i] = fact[i - 1] * i; }
    reps(i, N) { dfact[i] = dfact[i - 1] * (i * 2 - 1); }
    auto rec = [&](auto &&rec, int l, int r) -> vector<mint> {
        if (r - l == 1) {
            int K = cnt[l] / 2 + 1;
            vector<mint> ret(K);
            rep(i, K) { ret[i] = fact[cnt[l]] / fact[2 * i] / fact[cnt[l] - 2 * i] * dfact[i]; }
            return ret;
        }
        int mid = (l + r) / 2;
        return convolution(rec(rec, l, mid), rec(rec, mid, r));
    };
    vector<mint> res = rec(rec, 0, M);
    mint ans = 0;
    rep(i, res.size() - 1) { ans += (i & 1 ? -1 : 1) * res[i] * dfact[N - i]; }
    cout << ans.val() << endl;
}

