ll nCr(ll n,ll r,vector<ll>& fac){
    if (r == 0 || n == r) return 1;
    else if (r==1 || n == r+1) return n;
    else if (n < r) return 0;
    ll ret = fac[n] * inv_mod(fac[n-r],mod) % mod;
    return ret * inv_mod(fac[r],mod) % mod;
}

