ll fact[fact_table + 5], rfact[fact_table + 5];

void c3_init() {
    fact[0] = rfact[0] = 1;
    for (ll i = 1; i <= fact_table; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
    rfact[fact_table] = mypow(fact[fact_table], mod - 2, mod);
    for (ll i = fact_table; i >= 1; i--) {
        rfact[i - 1] = rfact[i] * i;
        rfact[i - 1] %= mod;
    }
    return;
}
ll c3(ll n, ll r) {
    return (((fact[n] * rfact[r]) % mod ) * rfact[n - r]) % mod;
}


bool multicase = false;

ll cnt[100005], dp[50005];

ll c2table[100005], rc2table[100005];

ll makepair(ll size, ll num) {
    ll res1 = c2table[size];
    ll res2 = rc2table[size - num * 2];
    ll res = res1 * res2 % mod;
    return res;
}

void pre_calc() {
    c2table[1] = c2table[0] = 1;
    c2table[2] = 1, c2table[3] = 3;
    for (int i = 4; i <= 100000; i++) {
        c2table[i] = c2table[i - 2] * c3(i, 2);
        c2table[i] %= mod;
        /// p(c2table[i]);
    }
    rc2table[100000] = mypow(c2table[100000], mod - 2, mod);
    rc2table[99999] = mypow(c2table[99999], mod - 2, mod);
    for (int i = 99998; i >= 1; i--) {
        rc2table[i] = rc2table[i + 2] * c3(i + 2, 2);
        rc2table[i] %= mod;
    }
    return;
}

void solve() {
    ll n;
    cin >> n;
    c3_init();
    pre_calc();
    for (int i = 0; i < 2 * n; i++) {
        ll val;
        cin >> val;
        cnt[val] ++;
    }
    dp[0] = 1;
    for (int i = 1; i <= 100000; i++) {
        ll size = cnt[i];
        if (size <= 1) continue;
        for (int j = n; j >= 0; j--) {
            // もらうDP
            for (int k = 1; k * 2ll <= size; k++) {
                if (j - k < 0) break;
                if (dp[j - k] == 0) continue;
                ll p = makepair(size, k);
                // pe('!');pe(j);p(j-k);
                dp[j] += (dp[j - k] * p) % mod;
                dp[j] %= mod;
            }
        }

    }
    ll value = 1ll, s = 2 * n;
    ll chose = n;
    for (int i = 0; i <= n; i++) {

        dp[i] *= (value * c2table[s]) % mod;
        dp[i] %= mod;

        value *= chose;
        chose --;

        s -= 2;
    }
    ll sign = 1ll, ans = 0;
    for (int i = 0; i <= n; i++) {
        ans += (sign * dp[i] + mod);
        ans %= mod;
        sign *= -1;
    }
    ans *= mypow(fact[n], mod - 2, mod);
    ans %= mod;
    p(ans);
    return;
}


