      _fbs[0] = 1;
      repr(j, 1, _fw / 2 + 1) {
        _fbs[j] = f[_fw] * finv[j * 2] * finv[_fw - j * 2] * ff[j * 2 - 1];
      }
      forbidden = convolution(forbidden, _fbs);
      _fs = i + 1;
    }
  }
