template <typename T>
struct Compress {
  vector<T> vec;

  explicit Compress(vector<T> v) : vec(v) {
    sort(vec.begin(), vec.end());
    vec.erase(unique(vec.begin(), vec.end()), vec.end());
  }
  int index(T x) {
    return (int)(lower_bound(vec.begin(), vec.end(), x) - vec.begin());
  }
  int size() { return vec.size(); }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int N;
  cin >> N;
  V<int> H(2 * N);
  cin >> H;
  Compress comp(H);
  const int M = comp.size();
  V<int> cnts(M);
  REP(i, 2 * N) { ++cnts[comp.index(H[i])]; }

  auto f = [&](auto self, int cur) -> Mint {
    if (cur == M) {
      return 1;
    }
    if (cnts[cur] == 0) {
      return self(self, cur + 1);
    }
    cnts[cur]--;
    Mint res = 0;
    map<int, Mint> memo;
    for (int i = cur + 1; i < M; ++i) {
      if (cnts[i] == 0) continue;
      auto it = memo.find(cnts[i]);
      if (it != memo.end()) {
        res += it->second;
        continue;
      }
      cnts[i]--;
      Mint r = self(self, cur);
      cnts[i]++;
      r *= cnts[i];
      memo[cnts[i]] = r;
      res += r;
    }
    cnts[cur]++;
    DEBUG(cur, cnts, res);
    return res;
  };
  cout << f(f, 0) << endl;
}

