        vector<mint> vec(sz / 2 + 1, 1);
        FOR(i, 1, vec.size())
        {
            vec[i] = mint(sz).nCr(i * 2) * mint(i * 2 - 1).doublefac();
        }
        pq.emplace(sz, vec);
    }
    while (pq.size() > 1)
    {
        auto [s1, v1] = pq.top();
        pq.pop();
        auto [s2, v2] = pq.top();
        pq.pop();
        pq.emplace(s1 + s2, nttconv(v1, v2));
