                               montgomery_add_128(T0P1, T2P3, m2, m0));
              _mm_store_si128((__m128i *)(a + j2),
                               montgomery_sub_128(T0P1, T2P3, m2, m0));
              _mm_store_si128((__m128i *)(a + j1),
