/*
 * @title CombinationMod - mod上の二項係数・階乗
 * @docs md/math/CombinationMod.md
 */
template<long long mod> class CombinationMod {
	vector<long long> fac,finv,inv;
public:
	CombinationMod(int N) : fac(N + 1), finv(N + 1), inv(N + 1) {
		fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
		for (int i = 2; i <= N; ++i) {
			fac[i] = fac[i - 1] * i % mod;
			inv[i] = mod - inv[mod%i] * (mod / i) % mod;
			finv[i] = finv[i - 1] * inv[i] % mod;
		}
	}
	inline long long binom(int n, int k) {
		return ((n < 0 || k < 0 || n < k) ? 0 : fac[n] * (finv[k] * finv[n - k] % mod) % mod);
	}
	inline long long factorial(int n) {
		return fac[n];
	}
};

int main() {
    cin.tie(0);ios::sync_with_stdio(false);
    int N; cin >> N;

    int M = 100000;
    vector<int> cnt(M+1,0);
    for(int i=0;i<2*N;++i) {
        int h; cin >> h; cnt[h]++;
    }

    vector<modint> fact_odd(2*N,0);
    fact_odd[1]=1;
    for(int i=3; i<2*N;i+=2) fact_odd[i] = fact_odd[i-2]*i;

    CombinationMod<MOD2> CM(2*N);

    vector<fps> vf;
    priority_queue_reverse<pair<int,int>> pq;
    for(int i=1; i<= M; ++i) {
        if(!cnt[i]) continue;
        int n = cnt[i];
        int m = n/2;
        fps f(m+1,0);
        f[0]=1;
        for(int j=1;j<=m;++j) {
            // n人から2j人選ぶ-> n_C_2j
            // 2j人からjペア作る-> (2j-1)*(2j-3)*...*3*1;
            f[j] = fact_odd[2*j-1]*CM.binom(n,2*j);
        }
        vf.push_back(f);
        pq.push({f.size(),vf.size()-1});
    }
    while(pq.size()>=2) {
        auto l = pq.top().second; pq.pop();
        auto r = pq.top().second; pq.pop();
        auto f = vf[l]*vf[r];
        vf.push_back(f);
        pq.push({f.size(),vf.size()-1});
    }
    modint ans = 0;
    {
        auto c = pq.top().second; pq.pop();
        auto f = vf[c];
        for(int i=0;i<f.size();++i) f[i] *= fact_odd[2*(N-i)-1];
        for(int i=0;i<f.size();++i) ans += f[i]*(1 - 2*(i%2));
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int P = 998244353;
const int N = 1000005;

class Comb {
	public:
    vector<int> fac;
    vector<int> inv;
    vector<int> facinv;
    int P;

    Comb() {}
    Comb(int N, int P) : fac(N + 1), inv(N + 1), facinv(N + 1), P(P) {
        fac[0] = 1;
        for(int i = 1; i <= N; ++i) {
            fac[i] = 1LL * fac[i - 1] * i % P;
        }
        inv[1] = 1;
        for(int i = 2; i <= N; ++i) {
            inv[i] = 1LL * (P - P / i) * inv[P % i] % P;
        }
        facinv[0] = 1;
        for(int i = 1; i <= N; ++i) {
            facinv[i] = 1LL * facinv[i - 1] * inv[i] % P;
        }
    }

    int C(int n, int m) {
        if(n < m) {
            return 0;
        }
        return 1LL * fac[n] * facinv[m] % P * facinv[n - m] % P;
    }

    int Inv(int n) {
        return inv[n];
    }
};

namespace poly { //method : use c = multiply(a, b)
    vector<int> rev = {0, 1};
    vector<int> Root = {0, 1};

    const int P = 998244353;
    const int G = 3;

    int power(int x, int t) {
        int ret = 1;
        for(; t; t >>= 1, x = 1LL * x * x % P) {
            if(t & 1) {
                ret = 1LL * ret * x % P;
            }
        }
        return ret;
    }

    void init(int n) {
        if(n <= Root.size()) {
            return;
        }
        rev.resize(n);
        for(int i = 0; i < n; ++i) {
            rev[i] = (rev[i >> 1] | ((i & 1) * n)) >> 1;
        }
        if((int)Root.size() < n) {
            int k = __builtin_ctz(Root.size());
            Root.resize(n);
            while((1 << k) < n) {
                int z = power(G, (P - 1) >> (k + 1));
                for(int i = 1 << (k - 1); i < (1 << k); ++i) {
                    Root[2 * i] = Root[i];
                    Root[2 * i + 1] = 1LL * Root[i] * z % P;
                }
                k += 1;
            }
        }
    }

    void dft(vector<int> &a, int n) {
        init(n);
        int s = __builtin_ctz(rev.size() / n);
        for(int i = 0; i < n; ++i) {
            if(i < rev[i] >> s) {
                swap(a[i], a[rev[i] >> s]);
            }
        }
        for(int k = 1; k < n; k = k * 2) {
            for(int i = 0; i < n; i = i + k * 2) {
                for(int j = 0; j < k; ++j) {
                    int t = 1LL * Root[j + k] * a[i + j + k] % P;
                    a[i + j + k] = (a[i + j] - t + P) % P;
                    a[i + j] = (a[i + j] + t) % P; 
                }
            }
        }
    }

    void idft(vector<int> &a, int n) {
        reverse(a.begin() + 1, a.end());
        dft(a, n);
        int inv = power(n, P - 2);
        for(int i = 0; i < n; ++i) {
            a[i] = 1LL * a[i] * inv % P;
        }
    }

    vector<int> multiply(vector<int> a, vector<int> b) { // return a * b size = sz(a) + sz(b)
        int s = a.size() + b.size() - 1;
        if(s <= 0) {
            return {};
        }
        int L = s > 1 ? 32 - __builtin_clz(s - 1) : 0;
        int n = 1 << L;
        a.resize(n);
        dft(a, n);
        b.resize(n);
        dft(b, n);
        for(int i = 0; i < n; ++i) {
            a[i] = 1LL * a[i] * b[i] % P;
        }
        idft(a, n);
        a.resize(s);
        return a;
    }
}

long long power(long long x, long long t) {
	long long ret = 1;
	for(; t; t >>= 1, x = x * x % P) {
		if(t & 1) {
			ret = ret * x % P;
		}
	}
	return ret;
}

class Poly {
	public:
	vector<int> a;

	Poly() {}
	Poly(const vector<int> &_a) : a(_a) {}

	bool friend operator < (const Poly &a, const Poly &b) {
		return a.a.size() > b.a.size();
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int n;
	cin >> n;

	vector<int> h(n * 2);
	for(int i = 0; i < n * 2; ++i) {
		cin >> h[i];
	}

	Comb C(n * 2, P);		

	vector<int> cnt(N);
	for(int i : h) {
		cnt[i] += 1;
	}

	int sum = 0;
	priority_queue<Poly> q;

	auto calc = [&] (int n) {
		long long tmp = power(2, n);
		return 1LL * C.fac[2 * n] * C.facinv[n] % P * power(tmp, P - 2) % P;
	};	

	for(int i = 0; i < N; ++i) {
		if(cnt[i] >= 2) {
			Poly tmp;
			tmp.a.resize(cnt[i] / 2 + 1);
			for(int j = 0; j + j <= cnt[i]; ++j) {
				long long x = C.C(cnt[i], j * 2);
				tmp.a[j] = x * calc(j) % P;
			}
			q.emplace(tmp);
		}
	}

	while(q.size() > 1) {
		Poly a = q.top();
		q.pop();
		Poly b = q.top();
		q.pop();
		Poly c;
		c.a = poly::multiply(a.a, b.a);
		q.emplace(c);
	}

	vector<int> dp = q.top().a;

	for(int i = 0; i < min(n + 1, (int)dp.size()); ++i) {
		dp[i] = 1LL * dp[i] * calc(n - i) % P;
	}

	long long ans = 0;
	for(int i = 0; i < dp.size(); ++i) {
		ans = (ans + 1LL * (i % 2 == 0 ? 1 : -1) * dp[i] + P) % P;
	}

	cout << ans << '\n';

	return 0;
}

