ll jc[N],inv[N];
void init(int n) {
	jc[0]=1; for(int i=1;i<=n;i++) jc[i]=jc[i-1]*i%mod;
	inv[n]=power(jc[n]); for(int i=n;i;i--) inv[i-1]=inv[i]*i%mod;
}
ll C(int x,int y) {
	if(x<y || y<0) return 0;
	return jc[x]*inv[y]%mod*inv[x-y]%mod;
}

int n,a[N],sum,m;
ll f[N],g[N],t[N];

void solve() {
	qr(n); m=2*n;
	for(int i=1,x;i<=m;i++) qr(x),a[x]++;
	f[0]=g[0]=1; init(2*n);
	for(int i=1,j=1;i<=n;i++) g[i]=(ll)j*(j+1)/2%mod*g[i-1]%mod,j += 2;
	for(int i=1;i<=n;i++) g[i]=g[i]*inv[i]%mod;
	for(int i=1,len;i<N;i++) if(a[i]>1) {
		len = a[i]/2;
		for(int k=1;k<=len;k++) t[k]=C(a[i],2*k)*g[k]%mod;
		for(int j=sum;j>=0;j--)
			for(int k=1;k<=len;k++)
				f[j+k]=(f[j+k]+f[j]*t[k])%mod;
		sum += len;
	}
	ll ans=0;
	for(int i=0;i<=n;i++)
		ans += (i&1?mod-1:1)*f[i]%mod*g[n-i]%mod;
	pr2((ans%mod+mod)%mod);
}

