	for(int i=1; i<=n; i++) fac[i] = 1ll*fac[i-1]*i%mod;
	ifac[n] = fpw(fac[n], mod-2);
	for(int i=n-1; i>=0; i--) ifac[i] = 1ll*ifac[i+1]*(i+1)%mod;
}
int comb(int a, int b)
{
	if(a<b||b<0||a<0) return 0;
	return 1ll*fac[a]*ifac[b]%mod*ifac[a-b]%mod;
}
