    setting.push_back(now);
    rep(i,1,N + 1) {
      now *= fact[i * 2] * finv[i * 2 - 2] * finv[2];
      setting.push_back(now);
    }
  }

  priority_queue<fps, vector<fps>, greater<fps>> que;
  rep(x,0,101010) {
    if(cnt[x] <= 1) continue;
    vector<fp> vec;
    i64 c = cnt[x];
    for(i64 i = 0; i * 2 <= c; i++) {
      vec.push_back(fact[c] * finv[i * 2] * finv[c - i * 2] * setting[i] * finv[i]);
