            if(i % 2 == 0) {
                crse[k] = crse[k - 1] * com(2 * k, 2) % MOD;
                rep(j, co[i]) {
                    dp = NTT.multiply(dp, crse);
                }
            } else {
                crso[k] = crso[k - 1] * com(2 * k + 1, 2) % MOD;
                rep(j, co[i]) {
                    dp = NTT.multiply(dp, crse);
                }
            }
            dp.resize(100100);
        // }
    }
    for(int i = 1; i < 100100; ++ i) {
        if(i % 2 == 1) {
