void compare_fact(int n, int mod) {
	int i;

	inv[1] = 1;
	for (i = 2; i <= n; i++) {
		inv[i] = -inv[mod % i] * (mod / i);
	}

	fact[0] = finv[0] = 1;
	for (i = 1; i <= n; i++) {
		fact[i] = i * fact[i - 1];
		finv[i] = inv[i] * finv[i - 1];
	}

	_fact2[0] = _fact2[1] = 1;
	for (i = 2; i <= n; i++) {
		_fact2[i] = i * _fact2[i - 2];
	}
}

mint fact2(int n) {
	if (n < 0) return 1;
	return _fact2[n];
}

mint comb(int n, int k) {
	return fact[n] * finv[k] * finv[n - k];
}

