                cp[j+k]+=dp[j]*COM(sum-j*2,k)%MOD*fac[k];
                cp[j+k]%=MOD;
            }
        }
        sum+=mem[i];
        REP(j,0,sum/2){
            dp[j]=cp[j];
            cp[j]=0;
        }
    }
    ll ans=dp[N];
    cout<<ans<<endl;
}

