//コンビネーション
const int MAXcomb = 2000010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll disit(ll s, ll base = 10){
  ll res = 0;
  while(s){
    res++;
    s /= base;
  }
  return res;
}

ll kaikai[100010];
void make_kaikai(){
  kaikai[0] = 1;
  kaikai[1] = 1;
  for(int i = 2; i < 100010; i++){
    kaikai[i] = kaikai[i-2] * i % MOD;
  }
}

ll N;
ll h[100010];
ll cnt[100010];
vector<ll> A;

vector<ll> merge(vector<vector<ll>>& B){
  int n = len(B);
  if(n == 1){
    return B[0];
  }
  vector<vector<ll>> L, R;
  rep(i, n){
    if(i & 1) L.pb(B[i]);
    else R.pb(B[i]);
  }
  vector<ll> left = merge(L);
  vector<ll> right = merge(R);
  vector<ll> res = atcoder::convolution(left, right);
  return res;
}

void solve(){
  COMinit();
  make_kaikai();
  cin >> N;
  rep(i, 2*N) cin >> h[i];
  rep(i, 2*N) cnt[h[i]]++;

  rep(i, 100010){
    if(cnt[i] != 0) A.pb(cnt[i]);
  }


  vector<vector<ll>> B;
  rep(i, len(A)){
    vector<ll> a;
    rep(j, A[i]/2+1){
      //jペア
      a.pb(comb(A[i], 2*j) * kaikai[max(2*j-1, 0)]);
    }
    B.pb(a);
  }
  vector<ll> C = merge(B);

  ll ans = 0;
  rep(i, len(C)){
    if(i & 1) ans += MOD - C[i] * kaikai[2*N-i*2-1] % MOD;
    else ans += C[i] * kaikai[2*N-i*2-1] % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

