class Factorial {
public:
    vector<mint> fact, finv, doubleFact;
    Factorial(long long n) : fact(n + 1, 1), finv(n + 1, 1), doubleFact(n + 1, 0) {
        doubleFact[1] = 1;
        for (int i = 2; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
            finv[i] = finv[i - 1] / i;
            doubleFact[i] = doubleFact[i - 2] * i;
        }
    }
    mint perm(const long long n, const long long k) {
        return fact[n] * finv[n - k];
    }
    mint com(const long long n, const long long k) {
        if (n < k || n < 0 || k < 0)
            return mint(0);
        return fact[n] * finv[k] * finv[n - k];
    }
};

