  rep(i,2*N) cin>>A[i];

  vector<ll> cb(L+1,0);
  cb[0]=1;
  for(int i=2;i<=L;i+=2){
      //cb[i]=comb(i,i/2)%MOD;
      //mul(cb[i],inv[2]);
      cb[i]=comb(i,2)*cb[i-2]%MOD;
  }
  for(int i=2;i<=L;i+=2) mul(cb[i],ifac[i/2]);

  vector<int> num(L+1,0);
  rep(i,2*N) num[A[i]]++;

  for(int i=1;i<=L;i++){
      if(num[i]>N){
          cout<<0<<endl;
          return 0;
      }
  }

  vector<vector<ll>> dp(L+1);
  for(int i=1;i<=L;i++){
      if(num[i]==0) continue;
      vector<ll> tmp(num[i]/2+1,0);
      tmp[0]=1;
      for(int k=1;k<=num[i]/2;k++){
          ll coef=comb(num[i],2*k);
          mul(coef,cb[2*k]);
          tmp[k]=coef;
      }
      dp[i]=tmp;
  }

  priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> PQ;
  for(int i=1;i<=L;i++){
      if(num[i]==0) continue;
      PQ.push(mkp(num[i],i));
  }

  while(PQ.size()>=2){
      auto f=PQ.top();
      PQ.pop();
      auto s=PQ.top();
      PQ.pop();

      int ft=f.second;
      int st=s.second;
      dp[ft]=convolute(dp[ft],dp[st]);
      PQ.push(mkp(dp[ft].size(),ft));
      dp[st].clear();
  }
  auto f=PQ.top();
  PQ.pop();
  vector<ll> table=dp[f.second];

  ll ans=cb[2*N];
  for(int i=1;i<=N;i++){
      ll res=0;
      if(i<table.size()) res=table[i];
      mul(res,cb[2*N-2*i]);

      if(i%2) add(ans,MOD-res);
      else add(ans,res);
  }
  cout<<ans<<endl;

  return 0;
}

