      else a[tot][i]=1ll*C(b[l],i)*C(b[l]-i,i)%mod*fac[i]%mod;
      */
      a[tot][i]=1ll*fac[b[l]]*ifac[b[l]-2*i]%mod*ifac[i]%mod*ipw[i]%mod;
