struct CoordinateCompressor {
private:
    vector<ll> _i2v;
    map<ll, ll> _v2i;
public:
    CoordinateCompressor(const vector<ll>& v) : _i2v(v) {
        sort(_i2v.begin(), _i2v.end());
        _i2v.erase(unique(_i2v.begin(), _i2v.end()), _i2v.end());
        for(ll i = 0; i < _i2v.size(); ++i){ _v2i[_i2v.at(i)] = i; }
    }
    size_t size() const { return _i2v.size(); }
    ll i2v(ll i) const { return _i2v.at(i); }
    ll v2i(ll v) const { return _v2i.at(v); }
};

struct mintcomb{
    vector<mint> fact;
    vector<mint> ifact;
    mintcomb(ll n) : fact(n + 1, 1), ifact(n + 1, 1) {
        for(ll i = 2; i <= n; ++i){
            fact.at(i) = fact.at(i - 1) * i;
            ifact.at(i) = fact.at(i).inv();
        }
    }

    mint factorial(ll k) const { return fact.at(k); }
    mint combination(ll k, ll l) const {
        return fact.at(k) * ifact.at(l) * ifact.at(k - l);
    }
};


int main(){
    ll n;
    cin >> n;
    vector<ll> h(2 * n);
    REP(i, 2 * n){ cin >> h.at(i); }

    CoordinateCompressor cc(h);
    REP(i, 2 * n){ h.at(i) = cc.v2i(h.at(i)); }

    vector<ll> count(cc.size(), 0);
    REP(i, 2 * n){ count.at(h.at(i))++; }

    vector<ll> cs(count.size(), 0);
    REP(i, count.size()){
        cs.at(i) = count.at(i);
        if(i > 0){ cs.at(i) += cs.at(i - 1); }
    }

    mintcomb mc(2 * n);

    vector<vector<mint>> dp(cc.size(), vector<mint>(2 * n + 1, 0));

    dp.at(0).at(count.at(0)) = 1;
    for(ll h = 1; h < cc.size(); ++h){
        const ll m = count.at(h);
        for(ll r = 0; r <= cs.at(h - 1); ++r){
            if(dp.at(h - 1).at(r) == 0){ continue; }
            for(ll u = 0; u <= min(m, r); ++u){
                const ll new_r = r - u + m - u;
                if(new_r > 2 * n){ continue; }
                mint tmp = dp.at(h - 1).at(r);
                tmp *= mc.combination(m, u) * mc.factorial(u) * mc.combination(r, u);
                dp.at(h).at(new_r) += tmp;
            }
        }
    }

    cout << dp.at(cc.size() - 1).at(0).val() << endl;
    return 0;
}

