public void solve() {
	int num = ni();
	long h[] = nl(num * 2);
	Arrays.sort(h);
	List<Integer> len = new ArrayList<>();
	int tmp = 1;
	for(int i = 1; i <= num * 2; i ++) {
		if(i == num * 2 || h[i] != h[i - 1]) {
			len.add(tmp);
			tmp = 0;
		}
		tmp ++;
	}
	Collections.sort(len);
	int size = len.size();
	pow_2 = pows_m(inv(2), num * 2 + 10);
	prepareFact();
	Convolution cnv = new Convolution(MOD);
	Deque<long[]> dq = new ArrayDeque<>();
	dq.addLast(new long[]{1});
	for(int i = 0; i < size; i ++) {
		tmp = len.get(i);
		if(tmp <= 1) continue;
		long f[] = new long[tmp / 2 + 1];
		for(int j = 0; j * 2 <= tmp; j ++) {
			f[j] = cal(tmp, j);
		}
		dq.addLast(f);
	}
	while(dq.size() > 1) dq.addLast(cnv.convolution(dq.removeFirst(), dq.removeFirst()));
	long crt[] = dq.removeFirst();
	long ans = 0;
	for(int i = 0; i < crt.length; i ++) {
		ans += mod(crt[i] * cal(num * 2 - i * 2, num - i)) * (i % 2 == 0 ? 1 : -1);
		ans = mod(ans);
	}
	prtln(ans);
}

long pow_2[];
long cal(int n, int i) { return mod(mod(P(n, i * 2) * pow_2[i]) * invFact[i]); }

class Convolution { // M=mod
	long mod;
	long g;
	long sumE[];
	long sumIE[];
	static final int size = 30;
	Convolution(long mod) { // O(logM)
		positiveCheck(mod, "mod");
		this.mod = mod;
		g = primitiveRoot(mod);
		sumE = new long[size];
		sumIE = new long[size];
		prepareSum();
	}

	long primitiveRoot(long mod) { // O(1) or O(遶丞銅)
		if(mod == 2) return 1;
		if(mod == 167772161) return 3;
		if(mod == 469762049) return 3;
		if(mod == 754974721) return 11;
		if(mod == 998244353) return 3;

		PairLL factor[] = factor(mod - 1);
		outer: for(long g = 2; ; g ++) {
			for(PairLL p : factor) if(pow_m(g, (mod - 1) / p.a, mod) == 1) continue outer;
			return g;
		}
	}

	void prepareSum() { // O(logM)
		long[] es = new long[size];
		long[] ies = new long[size];
		int len = Long.numberOfTrailingZeros(mod - 1);
		long e = pow_m(g, (mod - 1) >> len, mod);
		long ie = pow_m(e, mod - 2, mod);
		for(int i = len - 2; i >= 0; i --) {
			es[i] = e;
			ies[i] = ie;
			e = mod(e * e, mod);
			ie = mod(ie * ie, mod);
		}
		long tmpE = 1;
		long tmpIE = 1;
		for(int i = 0; i < len - 2; i++) {
			sumE[i] = mod(es[i] * tmpE, mod);
			tmpE = mod(tmpE * ies[i], mod);
			sumIE[i] = mod(ies[i] * tmpIE, mod);
			tmpIE = mod(tmpIE * es[i], mod);
		}
	}

	void butterfly(long[] a) { // O(NlogN)
		int n = a.length;
		int h = 0;
		while((1L << h) < n) h ++;

		for(int ph = 1; ph <= h; ph ++) {
			int w = 1 << (ph - 1);
			int p = 1 << (h - ph);
			long tmp = 1;
			for(int s = 0; s < w; s ++) {
				int offset = s << (h - ph + 1);
				for(int i = 0; i < p; i ++) {
					long l = a[i + offset];
					long r = mod(a[i + offset + p] * tmp, mod);
					a[i + offset] = mod(l + r, mod);
					a[i + offset + p] = mod(l - r, mod);
				}
				int x = Integer.numberOfTrailingZeros(~s);
				tmp = mod(tmp * sumE[x], mod);
			}
		}
	}
	void butterflyInv(long[] a) { // O(NlogN)
		int n = a.length;
		int h = 0;
		while((1L << h) < n) h ++;

		for(int ph = h; ph >= 1; ph --) {
			int w = 1 << (ph - 1);
			int p = 1 << (h - ph);
			long tmp = 1;
			for(int s = 0; s < w; s ++) {
				int offset = s << (h - ph + 1);
				for (int i = 0; i < p; i++) {
					long l = a[i + offset];
					long r = a[i + offset + p];
					a[i + offset] = mod(l + r, mod);
					a[i + offset + p] = mod((l - r) * tmp, mod);
				}
				int x = Integer.numberOfTrailingZeros(~s);
				tmp = mod(tmp * sumIE[x], mod);
			}
		}
	}

	long[] convolution(long[] a, long[] b) { // O((N+M)log(N+M))
		int n = a.length;
		int m = b.length;
		if (n == 0 || m == 0) return new long[0];

		int len = 1;
		while(len < n + m - 1) len <<= 1;
		long g[] = resize(a, len, 0);
		long h[] = resize(b, len, 0);

		butterfly(g);
		butterfly(h);

		long f[] = new long[len];
		for(int i = 0; i < len; i ++) f[i] = mod(g[i] * h[i], mod);
		butterflyInv(f);
		f = resize(f, n + m - 1, 0);

		long invLen = inv(len, mod);
		for(int i = 0; i < f.length; i ++) f[i] = mod(f[i] * invLen, mod);
		return f;
	}
}

	}
}

