		final int mod = 998244353;

		int[][] fif = enumFIF(150000, mod);
		PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> x.length - y.length);
		for(int v : uc){
			long[] a = new long[v/2+1];
			for(int i = 0;i <= v/2;i++){
				a[i] = C(v, 2*i, mod, fif) * fif[0][2*i] % mod * invl(pow(2, i, mod), mod) % mod * fif[1][i] % mod;
			}
			pq.add(a);
		}
		while(pq.size() > 1){
			long[] A = pq.poll();
			long[] B = pq.poll();
			long[] C = convoluteSimply(A, B, mod, 3);
			pq.add(Arrays.copyOf(C, A.length+B.length-1));
		}
		long[] D = pq.poll();
		long ans = 0;
		for(int i = 0;i < D.length;i++){
			ans += (i % 2 == 0 ? 1 : mod-1) * D[i] % mod * fif[0][2*n-2*i] % mod * invl(pow(2, n-i, mod), mod) % mod * fif[1][n-i] % mod;
		}
		out.println(ans%mod);
	}

	public static final int[] NTTPrimes = {1053818881, 1051721729, 1045430273, 1012924417, 1007681537, 1004535809, 998244353, 985661441, 976224257, 975175681};
	public static final int[] NTTPrimitiveRoots = {7, 6, 3, 5, 3, 3, 3, 3, 3, 17};
