public void solve() {
	int num = ni();
	int h[] = ni(num * 2);
	int cnt[] = new int[100100];
	for(int i = 0; i < num * 2; i ++) cnt[h[i]] ++;

	pow_2 = pows_m(inv(2), num * 2 + 10);
	prepareFact();
	Convolution cnv = new Convolution(MOD);

	Deque<long[]> dq = new ArrayDeque<>();
	dq.addLast(new long[]{1});
	for(int i = 0; i < cnt.length; i ++) {
		if(cnt[i] <= 1) continue;
		long f[] = new long[cnt[i] / 2 + 1];
		for(int j = 0; j * 2 <= cnt[i]; j ++) {
			f[j] = cal(cnt[i], j);
		}
		dq.addLast(f);
	}

	while(dq.size() > 1) dq.addLast(cnv.convolution(dq.removeFirst(), dq.removeFirst()));
	long crt[] = dq.removeFirst();
	long ans = 0;
	for(int i = 0; i < crt.length; i ++) {
		ans += mod(crt[i] * cal(num * 2 - i * 2, num - i)) * (i % 2 == 0 ? 1 : -1);
		ans = mod(ans);
	}
	prtln(ans);
}

long pow_2[];
long cal(int n, int i) { return mod(mod(P(n, i * 2) * pow_2[i]) * invFact[i]); }

class Convolution { // M=mod
	long mod;
	long g;
	long sumE[];
	long sumIE[];
	static final int size = 30;
	Convolution(long mod) { // O(logM)
		positiveCheck(mod, "mod");
		this.mod = mod;
		g = primitiveRoot(mod);
		sumE = new long[size];
		sumIE = new long[size];
		prepareSum();
	}

	long primitiveRoot(long mod) { // O(1) or O(遶丞銅)
		if(mod == 2) return 1;
		if(mod == 167772161) return 3;
		if(mod == 469762049) return 3;
		if(mod == 754974721) return 11;
		if(mod == 998244353) return 3;

		PairLL factor[] = factor(mod - 1);
		outer: for(long g = 2; ; g ++) {
			for(PairLL p : factor) if(pow_m(g, (mod - 1) / p.a, mod) == 1) continue outer;
			return g;
		}
	}

	void prepareSum() { // O(logM)
		long[] es = new long[size];
		long[] ies = new long[size];
		int len = Long.numberOfTrailingZeros(mod - 1);
		long e = pow_m(g, (mod - 1) >> len, mod);
		long ie = pow_m(e, mod - 2, mod);
		for(int i = len - 2; i >= 0; i --) {
			es[i] = e;
			ies[i] = ie;
			e = mod(e * e, mod);
			ie = mod(ie * ie, mod);
		}
		long tmpE = 1;
		long tmpIE = 1;
		for(int i = 0; i < len - 2; i++) {
			sumE[i] = mod(es[i] * tmpE, mod);
			tmpE = mod(tmpE * ies[i], mod);
			sumIE[i] = mod(ies[i] * tmpIE, mod);
			tmpIE = mod(tmpIE * es[i], mod);
		}
	}

	void butterfly(long[] a) { // O(NlogN)
		int n = a.length;
		int h = 0;
		while((1L << h) < n) h ++;

		for(int ph = 1; ph <= h; ph ++) {
			int w = 1 << (ph - 1);
			int p = 1 << (h - ph);
			long tmp = 1;
			for(int s = 0; s < w; s ++) {
				int offset = s << (h - ph + 1);
				for(int i = 0; i < p; i ++) {
					long l = a[i + offset];
					long r = mod(a[i + offset + p] * tmp, mod);
					a[i + offset] = mod(l + r, mod);
					a[i + offset + p] = mod(l - r, mod);
				}
				int x = Integer.numberOfTrailingZeros(~s);
				tmp = mod(tmp * sumE[x], mod);
			}
		}
	}
	void butterflyInv(long[] a) { // O(NlogN)
		int n = a.length;
		int h = 0;
		while((1L << h) < n) h ++;

		for(int ph = h; ph >= 1; ph --) {
			int w = 1 << (ph - 1);
			int p = 1 << (h - ph);
			long tmp = 1;
			for(int s = 0; s < w; s ++) {
				int offset = s << (h - ph + 1);
				for (int i = 0; i < p; i++) {
					long l = a[i + offset];
					long r = a[i + offset + p];
					a[i + offset] = mod(l + r, mod);
					a[i + offset + p] = mod((l - r) * tmp, mod);
				}
				int x = Integer.numberOfTrailingZeros(~s);
				tmp = mod(tmp * sumIE[x], mod);
			}
		}
	}

	long[] convolution(long[] a, long[] b) { // O((N+M)log(N+M))
		int n = a.length;
		int m = b.length;
		if (n == 0 || m == 0) return new long[0];

		int len = 1;
		while(len < n + m - 1) len <<= 1;
		long g[] = resize(a, len, 0);
		long h[] = resize(b, len, 0);

		butterfly(g);
		butterfly(h);

		long f[] = new long[len];
		for(int i = 0; i < len; i ++) f[i] = mod(g[i] * h[i], mod);
		butterflyInv(f);
		f = resize(f, n + m - 1, 0);

		long invLen = inv(len, mod);
		for(int i = 0; i < f.length; i ++) f[i] = mod(f[i] * invLen, mod);
		return f;
	}
}

	}
}

import java.util.*;
import java.io.*;
import java.text.*;

class Main{
    //SOLUTION BEGIN
    //Into the Hardware Mode
    final long MOD = 998244353;
    int GEN = 3;
    long[] fact, ifact, pow2;
    int mx = (int)1e5+2;
    void pre() throws Exception{
        fact = new long[mx];
        ifact = new long[mx];
        pow2 = new long[mx];
        fact[0] = ifact[0] = pow2[0] = 1;
        long inv2 = (MOD+1)/2;
        for(int i = 1; i< mx; i++){
            fact[i] = fact[i-1] * i %MOD;
            pow2[i] = pow2[i-1] * inv2 %MOD;
        }
        ifact[mx-1] = pow(fact[mx-1], MOD-2);
        for(int i = mx-2; i > 0; i--)ifact[i] = ifact[i+1] * (i+1) %MOD;
    }
    long pow(long x, long p){
        long o = 1;
        for(; p> 0; p>>=1){
            if((p&1)==1)o = o*x%MOD;
            x = x*x%MOD;
        }
        return o;
    }
    void solve(int TC) throws Exception{
        int N = ni();
        int[] h = new int[mx];
        for(int i = 0; i< 2*N; i++)h[ni()]++;

        int c = 0;
        for(int i = 0; i< mx; i++)if(h[i] > 0){
            h[c++] = h[i];
        }
        h = Arrays.copyOf(h, c);

        PriorityQueue<long[]> pq = new PriorityQueue<>((long[] l1, long[] l2) -> Integer.compare(l1.length, l2.length));
        for(int i:h)pq.add(getP(i));
        while(pq.size() > 1)pq.add(Convolution.convolution(pq.poll(), pq.poll(), (int)MOD));


        long[] ways = Arrays.copyOf(pq.poll(), 1+N);

        for(int i = 0; i<= N; i++){
            ways[i] = ways[i] * numPairs(2*(N-i), (N-i)) %MOD;
        }
        long total = 0;
        for(int i = 0; i<= N; i++){
            if(i%2 == 0)total += ways[i];
            else total += MOD-ways[i];
            if(total >= MOD)total -= MOD;
        }
        pn(total);

    }
    long[] getP(int x){
        long[] P = new long[1+x/2];
        for(int i = 0; i<= x/2; i++)P[i] = numPairs(x, i);
        return P;
    }
    long numPairs(int N, int K){
        if(N < 2*K)return 0;
        return fact[N] * ifact[N-2*K] %MOD * ifact[K] %MOD * pow2[K] %MOD;
    }

    //https://raw.githubusercontent.com/NASU41/AtCoderLibraryForJava/master/Convolution/Convolution.java
    /**
     * Convolution.
     *
     * @verified https://atcoder.jp/contests/practice2/tasks/practice2_f
     * @verified https://judge.yosupo.jp/problem/convolution_mod_1000000007
     */
    static class Convolution {
        /**
         * Find a primitive root.
         *
         * @param m A prime number.
         * @return Primitive root.
         */
        private static int primitiveRoot(int m) {
            if (m == 2) return 1;
            if (m == 167772161) return 3;
            if (m == 469762049) return 3;
            if (m == 754974721) return 11;
            if (m == 998244353) return 3;

            int[] divs = new int[20];
            divs[0] = 2;
            int cnt = 1;
            int x = (m - 1) / 2;
            while (x % 2 == 0) x /= 2;
            for (int i = 3; (long) (i) * i <= x; i += 2) {
                if (x % i == 0) {
                    divs[cnt++] = i;
                    while (x % i == 0) {
                        x /= i;
                    }
                }
            }
            if (x > 1) {
                divs[cnt++] = x;
            }
            for (int g = 2; ; g++) {
                boolean ok = true;
                for (int i = 0; i < cnt; i++) {
                    if (pow(g, (m - 1) / divs[i], m) == 1) {
                        ok = false;
                        break;
                    }
                }
                if (ok) return g;
            }
        }

        /**
         * Power.
         *
         * @param x Parameter x.
         * @param n Parameter n.
         * @param m Mod.
         * @return n-th power of x mod m.
         */
        private static long pow(long x, long n, int m) {
            if (m == 1) return 0;
            long r = 1;
            long y = x % m;
            while (n > 0) {
                if ((n & 1) != 0) r = (r * y) % m;
                y = (y * y) % m;
                n >>= 1;
            }
            return r;
        }

        /**
         * Ceil of power 2.
         *
         * @param n Value.
         * @return Ceil of power 2.
         */
        private static int ceilPow2(int n) {
            int x = 0;
            while ((1L << x) < n) x++;
            return x;
        }

        /**
         * Garner's algorithm.
         *
         * @param c    Mod convolution results.
         * @param mods Mods.
         * @return Result.
         */
        private static long garner(long[] c, int[] mods) {
            int n = c.length + 1;
            long[] cnst = new long[n];
            long[] coef = new long[n];
            java.util.Arrays.fill(coef, 1);
            for (int i = 0; i < n - 1; i++) {
                int m1 = mods[i];
                long v = (c[i] - cnst[i] + m1) % m1;
                v = v * pow(coef[i], m1 - 2, m1) % m1;

                for (int j = i + 1; j < n; j++) {
                    long m2 = mods[j];
                    cnst[j] = (cnst[j] + coef[j] * v) % m2;
                    coef[j] = (coef[j] * m1) % m2;
                }
            }
            return cnst[n - 1];
        }

        /**
         * Pre-calculation for NTT.
         *
         * @param mod NTT Prime.
         * @param g   Primitive root of mod.
         * @return Pre-calculation table.
         */
        private static long[] sumE(int mod, int g) {
            long[] sum_e = new long[30];
            long[] es = new long[30];
            long[] ies = new long[30];
            int cnt2 = Integer.numberOfTrailingZeros(mod - 1);
            long e = pow(g, (mod - 1) >> cnt2, mod);
            long ie = pow(e, mod - 2, mod);
            for (int i = cnt2; i >= 2; i--) {
                es[i - 2] = e;
                ies[i - 2] = ie;
                e = e * e % mod;
                ie = ie * ie % mod;
            }
            long now = 1;
            for (int i = 0; i < cnt2 - 2; i++) {
                sum_e[i] = es[i] * now % mod;
                now = now * ies[i] % mod;
            }
            return sum_e;
        }

        /**
         * Pre-calculation for inverse NTT.
         *
         * @param mod Mod.
         * @param g   Primitive root of mod.
         * @return Pre-calculation table.
         */
        private static long[] sumIE(int mod, int g) {
            long[] sum_ie = new long[30];
            long[] es = new long[30];
            long[] ies = new long[30];

            int cnt2 = Integer.numberOfTrailingZeros(mod - 1);
            long e = pow(g, (mod - 1) >> cnt2, mod);
            long ie = pow(e, mod - 2, mod);
            for (int i = cnt2; i >= 2; i--) {
                es[i - 2] = e;
                ies[i - 2] = ie;
                e = e * e % mod;
                ie = ie * ie % mod;
            }
            long now = 1;
            for (int i = 0; i < cnt2 - 2; i++) {
                sum_ie[i] = ies[i] * now % mod;
                now = now * es[i] % mod;
            }
            return sum_ie;
        }

        /**
         * Inverse NTT.
         *
         * @param a     Target array.
         * @param sumIE Pre-calculation table.
         * @param mod   NTT Prime.
         */
        private static void butterflyInv(long[] a, long[] sumIE, int mod) {
            int n = a.length;
            int h = ceilPow2(n);

            for (int ph = h; ph >= 1; ph--) {
                int w = 1 << (ph - 1), p = 1 << (h - ph);
                long inow = 1;
                for (int s = 0; s < w; s++) {
                    int offset = s << (h - ph + 1);
                    for (int i = 0; i < p; i++) {
                        long l = a[i + offset];
                        long r = a[i + offset + p];
                        a[i + offset] = (l + r) % mod;
                        a[i + offset + p] = (mod + l - r) * inow % mod;
                    }
                    int x = Integer.numberOfTrailingZeros(~s);
                    inow = inow * sumIE[x] % mod;
                }
            }
        }

        /**
         * Inverse NTT.
         *
         * @param a    Target array.
         * @param sumE Pre-calculation table.
         * @param mod  NTT Prime.
         */
        private static void butterfly(long[] a, long[] sumE, int mod) {
            int n = a.length;
            int h = ceilPow2(n);

            for (int ph = 1; ph <= h; ph++) {
                int w = 1 << (ph - 1), p = 1 << (h - ph);
                long now = 1;
                for (int s = 0; s < w; s++) {
                    int offset = s << (h - ph + 1);
                    for (int i = 0; i < p; i++) {
                        long l = a[i + offset];
                        long r = a[i + offset + p] * now % mod;
                        a[i + offset] = (l + r) % mod;
                        a[i + offset + p] = (l - r + mod) % mod;
                    }
                    int x = Integer.numberOfTrailingZeros(~s);
                    now = now * sumE[x] % mod;
                }
            }
        }

        /**
         * Convolution.
         *
         * @param a   Target array 1.
         * @param b   Target array 2.
         * @param mod NTT Prime.
         * @return Answer.
         */
        public static long[] convolution(long[] a, long[] b, int mod) {
            int n = a.length;
            int m = b.length;
            if (n == 0 || m == 0) return new long[0];

            int z = 1 << ceilPow2(n + m - 1);
            {
                long[] na = new long[z];
                long[] nb = new long[z];
                System.arraycopy(a, 0, na, 0, n);
                System.arraycopy(b, 0, nb, 0, m);
                a = na;
                b = nb;
            }

            int g = primitiveRoot(mod);
            long[] sume = sumE(mod, g);
            long[] sumie = sumIE(mod, g);

            butterfly(a, sume, mod);
            butterfly(b, sume, mod);
            for (int i = 0; i < z; i++) {
                a[i] = a[i] * b[i] % mod;
            }
            butterflyInv(a, sumie, mod);
            a = java.util.Arrays.copyOf(a, n + m - 1);

            long iz = pow(z, mod - 2, mod);
            for (int i = 0; i < n + m - 1; i++) a[i] = a[i] * iz % mod;
            return a;
        }

        /**
         * Convolution.
         *
         * @param a   Target array 1.
         * @param b   Target array 2.
         * @param mod Any mod.
         * @return Answer.
         */
        public static long[] convolutionLL(long[] a, long[] b, int mod) {
            int n = a.length;
            int m = b.length;
            if (n == 0 || m == 0) return new long[0];

            int mod1 = 754974721;
            int mod2 = 167772161;
            int mod3 = 469762049;

            long[] c1 = convolution(a, b, mod1);
            long[] c2 = convolution(a, b, mod2);
            long[] c3 = convolution(a, b, mod3);

            int retSize = c1.length;
            long[] ret = new long[retSize];
            int[] mods = {mod1, mod2, mod3, mod};
            for (int i = 0; i < retSize; ++i) {
                ret[i] = garner(new long[]{c1[i], c2[i], c3[i]}, mods);
            }
            return ret;
        }

        /**
         * Convolution by ModInt.
         *
         * @param a Target array 1.
         * @param b Target array 2.
         * @return Answer.
         */
        public static java.util.List<ModIntFactory.ModInt> convolution(
                java.util.List<ModIntFactory.ModInt> a,
                java.util.List<ModIntFactory.ModInt> b
        ) {
            int mod = a.get(0).mod();
            long[] va = a.stream().mapToLong(ModIntFactory.ModInt::value).toArray();
            long[] vb = b.stream().mapToLong(ModIntFactory.ModInt::value).toArray();
            long[] c = convolutionLL(va, vb, mod);

            ModIntFactory factory = new ModIntFactory(mod);
            return java.util.Arrays.stream(c).mapToObj(factory::create).collect(java.util.stream.Collectors.toList());
        }

        /**
         * Naive convolution. (Complexity is O(N^2)!!)
         *
         * @param a   Target array 1.
         * @param b   Target array 2.
         * @param mod Mod.
         * @return Answer.
         */
        public static long[] convolutionNaive(long[] a, long[] b, int mod) {
            int n = a.length;
            int m = b.length;
            int k = n + m - 1;
            long[] ret = new long[k];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i + j] += a[i] * b[j] % mod;
                    ret[i + j] %= mod;
                }
            }
            return ret;
        }
    }

