using System;
using System.Linq;
using CompLib.Util;
using System.Threading;
using CompLib.Algorithm;
using CompLib.Mathematics;

public class Program
{
    private int N;
    private int[] H;
    private const int MaxH = 100000;
    private const int Lg = 16;
    private const int Len = 1 << Lg;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        H = new int[2 * N];
        for (int i = 0; i < 2 * N; i++)
        {
            H[i] = sc.NextInt();
        }

        int[] cnt = new int[MaxH + 1];
        foreach (int i in H)
        {
            cnt[i]++;
        }

        var p = new ModInt[N + 1];
        p[0] = 1;
        for (int i = 1; i <= N; i++)
        {
            p[i] = p[i - 1] * (2 * i - 1);
        }

        var a = new ModInt[Len];
        a[0] = 1;
        var map = new ModInt[MaxH + 1][];
        FastFourierTransform.Transform(a, Lg, Len, false);
        for (int i = 0; i <= MaxH; i++)
        {
            if (cnt[i] < 2) continue;
            if (map[cnt[i]] == null)
            {
                map[cnt[i]] = new ModInt[Len];
                for (int j = 0; j * 2 <= cnt[i]; j += 1)
                {
                    map[cnt[i]][j] = Combinatorics.C(cnt[i], j * 2) * p[j];
                }

                FastFourierTransform.Transform(map[cnt[i]], Lg, Len, false);
            }

            for (int j = 0; j < Len; j++)
            {
                a[j] *= map[cnt[i]][j];
            }
        }

        FastFourierTransform.Transform(a, Lg, Len, true);

        var invLen = ModInt.Inverse(Len);
        for (int i = 0; i < Len; i++)
        {
            a[i] *= invLen;
        }




        ModInt ans = 0;

        for (int i = 0; i <= N; i++)
        {
            // iペア
            // N-iペア かぶる
            ans += p[i] * a[(N - i)] * ((N - i) % 2 == 0 ? 1 : -1);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
    // public static void Main(string[] args) => new Thread(new Program().Solve, 1 << 27).Start();
}

