using System;
using System.Linq;
using CompLib.Util;
using System.Threading;
using CompLib.Algorithm;
using CompLib.Mathematics;

public class Program
{
    private int N;
    private int[] H;
    private const int MaxH = 100000;
    private const int Lg = 17;
    private const int Len = 1 << Lg;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        H = new int[2 * N];
        for (int i = 0; i < 2 * N; i++)
        {
            H[i] = sc.NextInt();
        }

        int[] cnt = new int[MaxH + 1];
        foreach (int i in H)
        {
            cnt[i]++;
        }

        ModInt[] G = new ModInt[N + 1];
        G[0] = 1;
        for (int i = 1; i <= N; i++)
        {
            G[i] = G[i - 1] * (2 * i - 1);
        }

        int[] cnt2 = new int[2 * N + 1];
        foreach (int i in cnt)
        {
            cnt2[i]++;
        }

        ModInt[] a = new ModInt[Len];
        a[0] = 1;
        FastFourierTransform.Transform(a, Lg, Len, false);
        for (int i = 2; i <= 2 * N; i++)
        {
            if (cnt2[i] == 0) continue;
            var c = new ModInt[Len];
            c[0] = 1;
            c[1] = Combinatorics.C(i, 2);
            FastFourierTransform.Transform(c, Lg, Len, false);
            int tmp2 = cnt2[i];
            while (tmp2 > 0)
            {
                if (tmp2 % 2 == 1)
                {
                    for (int j = 0; j < Len; j++)
                    {
                        a[j] *= c[j];
                    }
                }

                for (int j = 0; j < Len; j++)
                {
                    c[j] *= c[j];
                }

                tmp2 /= 2;
            }
        }

        var invLen = ModInt.Inverse(Len);
        for (int i = 0; i < Len; i++)
        {
            a[i] *= invLen;
        }

        FastFourierTransform.Transform(a, Lg, Len, true);

        ModInt ans = 0;

        for (int i = 0; i <= N; i++)
        {
            // Console.WriteLine($"{i} {a[i]} {tmp}");
            ans += a[i] * G[N - i] * ((i) % 2 == 0 ? 1 : -1);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
    // public static void Main(string[] args) => new Thread(new Program().Solve, 1 << 27).Start();
}

