internal partial class Solver {
    public void Run() {
        var n = ni();
        var h = ni(2 * n);
        var a = h.GroupBy(x => x)
            .Select(g => g.Count())
            .ToArray();
        var mod = ModInt.SetMod998244353();
        var B = new Binomial(2 * n + 1, mod);
        var dp = new ModInt[n + 1];
        dp[0] = 1;
        var fact = ModInt.Factorials(2 * n + 1);

        //dp : pairnum
        dp[0] = 1;
        foreach (var x in a) {
            for (int pair = 1; 2 * pair <= x; pair++) {
                var pattern = B.C(x, pair * 2) * fact[pair];
                for (int i = n - 1; i >= 0; i--) {
                    if (i + pair <= n) {
                        dp[i + pair] += dp[i] * pattern;
                    }
                }
            }
        }
        var f = new ModInt[2 * n + 1];
        f[0] = 1;
        for (int i = 2; i < f.Length; i++) {
            f[i] = (i - 1) * f[i - 2];
        }

        ModInt ans = 0;
        for (int i = 0; i < dp.Length; i++) {
            var p = dp[i] * f[2 * n - 2 * i];
            if (i % 2 == 0) ans += p;
            else ans -= p;
        }
        cout.WriteLine(ans);
    }
}

