        }
        pub fn sub_assign(&mut self, rhs: &Self) {
            if self.len() < rhs.len() {
                self.a.resize(rhs.len(), ModInt::zero());
            }
            for (a, b) in self.a.iter_mut().zip(rhs.a.iter()) {
