            let mut b = Vec::with_capacity(len);
            b.push(self.a[0].inv());
            let mut f = Vec::with_capacity(2 * len);
            let mut g = Vec::with_capacity(2 * len);
            let mut size = 1;
            while b.len() < n {
                size <<= 1;
                f.clear();
                f.extend_from_slice(&b);
                f.resize(2 * size, ModInt::zero());
