use modint::*;

struct P;
impl ConstantModulo for P {
    const MOD: u32 = 998_244_353;
}

impl transform::NTTFriendly for P {
    fn order() -> usize {
        1 << 23
    }
    fn zeta() -> u32 {
        let p = Self::MOD as u64;
        mod_pow(3, (p - 1) >> 23, p) as u32
    }
}

type M = ModInt<P>;

use proconio::*;
use proconio::marker::*;
use std::collections::*;
use std::cmp::*;
use std::ops::Bound::*;

fn calc(a: &[Vec<M>]) -> Vec<M> {
    if a.len() == 1 {
        a[0].clone()
    } else {
        let m = a.len() / 2;
        let (l, r) = a.split_at(m);
        transform::multiply(&calc(l), &calc(&r))
    }
}

#[fastout]
fn run() {
    input! {
        n: usize,
        h: [usize; 2 * n],
    }
    let w = 100_000;
    let mut cnt = vec![0; w + 1];
    for h in h {
        cnt[h] += 1;
    }
    let pc = precalc::Precalc::new(w + 1);
    let mut memo = vec![];
    for c in cnt {
        if c < 2 {
            continue;
        }
        let mut a = vec![M::one()];
        for i in 1.. {
            if i * 2 > c {
                break;
            }
            a.push(pc.comb(c, 2 * i) * pc.fact(2 * i) * M::new(2).inv().pow(i as u64) * pc.ifact(i));
        }
        memo.push(a);
    }
    if memo.is_empty() {
        let ans = pc.fact(2 * n) * pc.inv(2).pow(n as u64);
        println!("{}", ans);
        return;
    }
    let a = calc(&memo);
    let mut ans = M::zero();
    let mut sign = M::one();
    for (i, a) in a.into_iter().enumerate() {
        ans += sign * a * pc.fact(2 * n - 2 * i) * pc.inv(2).pow((n - i) as u64) * pc.ifact(n - i);
        sign = -sign;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

use factorial::Factorial;
#[allow(unused_imports)]
use ngtio::prelude::*;

use polynomial::Poly;
use std::collections::BinaryHeap;
use type_traits::One;

type Fp = fp::F998244353;

fn g(k: usize, fact: &Factorial<Fp>, pow_2_inv: &[Fp]) -> Poly<Fp> {
    Poly::new(
        (0..)
            .take_while(|&i| 2 * i <= k)
            .map(|i| fact[k] * fact.inv(k - 2 * i) * fact.inv(i) * pow_2_inv[i])
            .collect(),
    )
}

use std::cmp::{Ord, Ordering};

#[derive(Debug, Clone, PartialEq, Eq)]
struct Len(Poly<Fp>);
impl Ord for Len {
    fn cmp(&self, rhs: &Self) -> Ordering {
        (self.0).0.len().cmp(&(rhs.0).0.len())
    }
}
impl PartialOrd for Len {
    fn partial_cmp(&self, rhs: &Self) -> Option<Ordering> {
        (self.0).0.len().partial_cmp(&(rhs.0).0.len())
    }
}

fn main() {
    let mut buf = ngtio::with_stdin();
    let n = buf.usize();
    let fact = Factorial::new(2 * n + 1, |x| Fp::new(x as i64));
    let pow_2_inv = std::iter::successors(Some(Fp::one()), |x| Some(x * Fp::new(2).inv()))
        .take(2 * n + 1)
        .collect::<Vec<_>>();
    let mut double_factorial = vec![Fp::one(); 2 * n + 1];
    for i in 2..=2 * n {
        double_factorial[i] = double_factorial[i - 2] * Fp::new(i as i64);
    }

    let mut m = vec![0; 100_000];
    for _ in 0..2 * n {
        let x = buf.parse::<Usize1>();
        m[x] += 1;
    }
    let mut heap = m
        .iter()
        .copied()
        .filter(|&x| 2 <= x)
        .map(|x| g(x, &fact, &pow_2_inv))
        .map(Len)
        .collect::<BinaryHeap<_>>();
    while 1 < heap.len() {
        let x = heap.pop().unwrap().0;
        let y = heap.pop().unwrap().0;
        heap.push(Len(fft::multiply(x, y)));
    }
    let mul = heap.pop().map(|len| len.0).unwrap_or_else(Poly::one);
    assert!(heap.is_empty());
    let ans = mul
        .into_inner()
        .iter()
        .enumerate()
        .map(|(i, &x)| {
            let sign = if i % 2 == 0 { Fp::one() } else { -Fp::one() };
            x * sign * double_factorial[(2 * (n - i)).saturating_sub(1)]
        })
        .sum::<Fp>();
    println!("{}", ans);
}

