use modint::*;

struct P;
impl ConstantModulo for P {
    const MOD: u32 = 998_244_353;
}

impl transform::NTTFriendly for P {
    fn order() -> usize {
        1 << 23
    }
    fn zeta() -> u32 {
        let p = Self::MOD as u64;
        mod_pow(3, (p - 1) >> 23, p) as u32
    }
}

type M = ModInt<P>;

use proconio::*;
use proconio::marker::*;
use std::collections::*;
use std::cmp::*;
use std::ops::Bound::*;

fn calc(a: &[Vec<M>]) -> Vec<M> {
    if a.len() == 1 {
        a[0].clone()
    } else {
        let m = a.len() / 2;
        let (l, r) = a.split_at(m);
        transform::multiply(&calc(l), &calc(&r))
    }
}

#[fastout]
fn run() {
    input! {
        n: usize,
        h: [usize; 2 * n],
    }
    let w = 100_000;
    let mut cnt = vec![0; w + 1];
    for h in h {
        cnt[h] += 1;
    }
    let pc = precalc::Precalc::new(w + 1);
    let mut memo = vec![];
    for c in cnt {
        if c < 2 {
            continue;
        }
        let mut a = vec![M::one()];
        for i in 1.. {
            if i * 2 > c {
                break;
            }
            a.push(pc.comb(c, 2 * i) * pc.fact(2 * i) * M::new(2).inv().pow(i as u64) * pc.ifact(i));
        }
        memo.push(a);
    }
    if memo.is_empty() {
        let ans = pc.fact(2 * n) * pc.inv(2).pow(n as u64) * pc.ifact(n);
        println!("{}", ans);
        return;
    }
    let a = calc(&memo);
    let mut ans = M::zero();
    let mut sign = M::one();
    for (i, a) in a.into_iter().enumerate() {
        ans += sign * a * pc.fact(2 * n - 2 * i) * pc.inv(2).pow((n - i) as u64) * pc.ifact(n - i);
        sign = -sign;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

