#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, $var:ident $($r:tt)*) => {
        let $var = parse_val!($it, usize);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: tt),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

pub fn get_double_factorials<M: Modulus>(n: usize) -> Vec<StaticModInt<M>> {
    let mut ret = vec![0.into(); n];
    ret[0] = 1.into();
    ret[1] = 1.into();
    for i in 2..n {
        ret[i] = ret[i - 2] * StaticModInt::new(i);
    }
    ret
}

type Mint = ModInt998244353;
type M = Mod998244353;
fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut values = HashMap::<usize, usize>::new();
    for _ in 0..2 * n {
        parse!(it, h: usize);
        *values.entry(h).or_default() += 1usize;
    }
    let cm = CombMod::<M>::new(2 * n + 10);
    let df = get_double_factorials::<M>(2 * n + 10);
    let mut q = BTreeMap::new();
    for (h, n) in values {
        let mut p = vec![];
        for i in 0..=(n / 2) {
            p.push(cm.c(n, 2 * i) * if i > 0 { df[2 * i - 1] } else { 1.into() });
        }
        q.insert((!0 - p.len(), h), p);
    }
    while q.len() > 1 {
        let mut it = q.iter();
        let (&k0, p0) = it.next().unwrap();
        let (&k1, p1) = it.next().unwrap();
        let p = convolution(&p0, &p1);
        q.remove(&k0);
        q.remove(&k1);
        q.insert((p.len(), k0.1), p);
    }
    let (_, p) = q.into_iter().next().unwrap();
    let mut ret = Mint::new(0);
    for (i, v) in p.into_iter().enumerate() {
        let x = v * if i < n {
            df[2 * n - 2 * i - 1]
        } else {
            1.into()
        };
        if i % 2 == 0 {
            ret += x
        } else {
            ret -= x;
        }
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

