mod transform {
    use super::modint::*;
    pub trait NTTFriendly: ConstantModulo {
        fn order() -> usize;
        fn zeta() -> u32;
    }
    pub fn ntt<T: NTTFriendly>(f: &mut [ModInt<T>]) {
        let n = f.len();
        assert!(n.count_ones() == 1);
        assert!(n <= T::order());
        let len = n.trailing_zeros() as usize;
        let mut zeta = Vec::with_capacity(len);
        let mut r = ModInt::new_unchecked(T::zeta()).pow((T::order() >> len) as u64);
        for _ in 0..len {
            zeta.push(r);
            r = r * r;
        }
        for (k, &z) in zeta.iter().rev().enumerate().rev() {
            let m = 1 << k;
            for f in f.chunks_exact_mut(2 * m) {
                let mut q = ModInt::one();
                let (x, y) = f.split_at_mut(m);
                for (x, y) in x.iter_mut().zip(y.iter_mut()) {
                    let a = *x;
                    let b = *y;
                    *x = a + b;
                    *y = (a - b) * q;
                    q *= z;
                }
            }
        }
    }
    pub fn intt<T: NTTFriendly>(f: &mut [ModInt<T>]) {
        let n = f.len();
        assert!(n.count_ones() == 1);
        assert!(n <= T::order());
        let len = n.trailing_zeros() as usize;
        let mut zeta = Vec::with_capacity(len);
        let mut r = ModInt::new_unchecked(T::zeta()).inv().pow((T::order() >> len) as u64);
        for _ in 0..len {
            zeta.push(r);
            r = r * r;
        }
        for (k, &z) in zeta.iter().rev().enumerate() {
            let m = 1 << k;
            for f in f.chunks_exact_mut(2 * m) {
                let mut q = ModInt::one();
                let (x, y) = f.split_at_mut(m);
                for (x, y) in x.iter_mut().zip(y.iter_mut()) {
                    let a = *x;
                    let b = *y * q;
                    *x = a + b;
                    *y = a - b;
                    q *= z;
                }
            }
        }
        let ik = ModInt::new_unchecked((T::MOD + 1) >> 1).pow(len as u64);
        for f in f.iter_mut() {
            *f *= ik;
        }
    }
    pub fn multiply<T: NTTFriendly>(a: &[ModInt<T>], b: &[ModInt<T>]) -> Vec<ModInt<T>> {
        if a.is_empty() || b.is_empty() {
            return vec![];
        }
        let n = a.len() + b.len() - 1;
        let k = n.next_power_of_two();
        assert!(k <= T::order());
        let mut f = Vec::with_capacity(k);
        let mut g = Vec::with_capacity(k);
        f.extend_from_slice(a);
        f.resize(k, ModInt::zero());
        ntt(&mut f);
        g.extend_from_slice(b);
        g.resize(k, ModInt::zero());
        ntt(&mut g);
        for (f, g) in f.iter_mut().zip(g.iter()) {
            *f *= *g;
        }
        intt(&mut f);
        f.truncate(n);
        f
    }
}
// ---------- end NTT ----------

use proconio::*;

use modint::*;

struct P;
impl ConstantModulo for P {
    const MOD: u32 = 998_244_353;
}

impl transform::NTTFriendly for P {
    fn order() -> usize {
        1 << 23
    }
    fn zeta() -> u32 {
        let p = Self::MOD as u64;
        mod_pow(3, (p - 1) >> 23, p) as u32
    }
}

type M = ModInt<P>;

fn calc(a: &[Vec<M>]) -> Vec<M> {
    if a.len() == 1 {
        a[0].clone()
    } else {
        let m = a.len() / 2;
        let (l, r) = a.split_at(m);
        transform::multiply(&calc(l), &calc(&r))
    }
}

#[fastout]
fn run() {
    input! {
        n: usize,
        h: [usize; 2 * n],
    }
    let w = 100_000;
    let mut cnt = vec![0; w + 1];
    for h in h {
        cnt[h] += 1;
    }
    let pc = precalc::Precalc::new(w + 1);
    let mut memo = vec![vec![M::one()]];
    for c in cnt {
        if c < 2 {
            continue;
        }
        let mut a = vec![M::one()];
        for i in 1.. {
            if i * 2 > c {
                break;
            }
            a.push(pc.comb(c, 2 * i) * pc.fact(2 * i) * M::new(2).inv().pow(i as u64) * pc.ifact(i));
        }
        memo.push(a);
    }
    let a = calc(&memo);
    let mut ans = M::zero();
    let mut sign = M::one();
    for (i, a) in a.into_iter().enumerate() {
        ans += sign * a * pc.fact(2 * n - 2 * i) * pc.inv(2).pow((n - i) as u64) * pc.ifact(n - i);
        sign = -sign;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

