// Depends on ModInt.rs
fn fact_init(w: usize) -> (Vec<ModInt>, Vec<ModInt>) {
    let mut fac = vec![ModInt::new(1); w];
    let mut invfac = vec![0.into(); w];
    for i in 1 .. w {
        fac[i] = fac[i - 1] * i as i64;
    }
    invfac[w - 1] = fac[w - 1].inv();
    for i in (0 .. w - 1).rev() {
        invfac[i] = invfac[i + 1] * (i as i64 + 1);
    }
    (fac, invfac)
}

fn upd(dp: Vec<ModInt>, f: usize, comb: &[ModInt],
       fac: &[ModInt], invfac: &[ModInt]) -> Vec<ModInt> {
    let n = dp.len() - 1;
    let mut ep = vec![ModInt::new(0); n + f + 1];
    for i in 0..n + 1 {
        for j in 0..f + 1 {
            if i + f >= 2 * j && i >= j {
                let t = fac[i] * invfac[i - j];
                ep[i + f - 2 * j] += dp[i] * comb[j] * t;
            }
        }
    }
    ep
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        n: usize,
        h: [usize; 2 * n],
    }
    let (fac, invfac) = fact_init(2 * n + 1);
    const M: usize = 100_100;
    let mut freq = vec![0; M];
    for &h in &h {
        freq[h] += 1;
    }
    freq.sort();
    let mut dp = vec![ModInt::new(1)];
    for f in freq {
        if f == 0 {
            continue;
        }
        let mut comb = vec![ModInt::new(0); f + 1];
        for i in 0..f + 1 {
            comb[i] = fac[f] * invfac[i] * invfac[f - i];
        }
        dp = upd(dp, f, &comb, &fac, &invfac);
    }
    puts!("{}\n", dp[0]);
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

