pub fn get_double_factorials<M: Modulus>(n: usize) -> Vec<StaticModInt<M>> {
    let mut ret = vec![0.into(); n];
    ret[0] = 1.into();
    ret[1] = 1.into();
    for i in 2..n {
        ret[i] = ret[i - 2] * StaticModInt::new(i);
    }
    ret
}

type Mint = ModInt998244353;
type M = Mod998244353;
fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut values = HashMap::<usize, usize>::new();
    for _ in 0..2 * n {
        parse!(it, h: usize);
        *values.entry(h).or_default() += 1usize;
    }
    let cm = CombMod::<M>::new(2 * n + 10);
    let df = get_double_factorials::<M>(2 * n + 10);
    let mut q = vec![];
    for (h, n) in values {
        let mut p = vec![];
        for i in 0..=(n / 2) {
            p.push(cm.c(n, 2 * i) * if i > 0 { df[2 * i - 1] } else { 1.into() });
        }
        q.push(p);
    }
    use std::mem::swap;
    let mut s = vec![];
    while q.len() > 1 {
        s.clear();
        for i in (0..q.len()).step_by(2) {
            let j = i + 1;
            if j >= q.len() {
                s.push(q.pop().unwrap());
                break;
            }
            s.push(convolution(&q[i], &q[j]));
        }
        swap(&mut s, &mut q);
    }
    let p = q.pop().unwrap();
    let mut ret = Mint::new(0);
    for (i, v) in p.into_iter().enumerate() {
        let x = v * if i < n {
            df[2 * n - 2 * i - 1]
        } else {
            1.into()
        };
        if i % 2 == 0 {
            ret += x
        } else {
            ret -= x;
        }
    }
    println!("{}", ret);
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

