use convolution::*;
use modint::*;

pub fn get_factorials<M: Modulus>(n: usize) -> Vec<StaticModInt<M>> {
    let mut facts = vec![0.into(); n];
    facts[0] = 1.into();
    for i in 1..n {
        facts[i] = facts[i - 1] * StaticModInt::<M>::new(i);
    }
    facts
}

pub fn get_facinvs<M: Modulus>(n: usize, facts: &Vec<StaticModInt<M>>) -> Vec<StaticModInt<M>> {
    let mut invs = vec![0.into(); n];
    invs[n - 1] = facts[n - 1].inv();
    for i in (0..(n - 1)).rev() {
        invs[i] = invs[i + 1] * StaticModInt::new(i + 1)
    }
    invs
}

pub fn gcd(a: usize, b: usize) -> usize {
    match b {
        0 => a,
        _ => gcd(b, a % b),
    }
}

pub fn prime_factors(x: usize) -> Vec<usize> {
    let mut res = vec![];
    let mut y = x;
    let mut p = 2;
    let upper = (y as f64).sqrt() as usize;
    while y > 1 && p <= upper {
        match y % p {
            0 => {
                res.push(p);
                y /= p;
            }
            _ => {
                p += 1;
            }
        }
    }
    if y > 1 {
        res.push(y)
    }
    return res;
}

pub struct CombMod<M: Modulus> {
    facts: Vec<StaticModInt<M>>,
    invs: Vec<StaticModInt<M>>,
}

impl<M: Modulus> CombMod<M> {
    pub fn new(n: usize) -> Self {
        let facts = get_factorials(n);
        let invs = get_facinvs(n, &facts);
        CombMod {
            facts: facts,
            invs: invs,
        }
    }
    pub fn c(&self, a: usize, b: usize) -> StaticModInt<M> {
        if a < b {
            0.into()
        } else {
            (self.facts[a] * self.invs[b]) * self.invs[a - b]
        }
    }
    pub fn p(&self, a: usize, b: usize) -> StaticModInt<M> {
        if b > a {
            0.into()
        } else {
            self.facts[a] * self.invs[a - b]
        }
    }
}

use factorial::Factorial;
#[allow(unused_imports)]
use ngtio::prelude::*;

use polynomial::Poly;
use type_traits::One;

type Fp = fp::F998244353;

fn g(k: usize, fact: &Factorial<Fp>, pow_2_inv: &[Fp]) -> Poly<Fp> {
    Poly::new(
        (0..)
            .take_while(|&i| 2 * i <= k)
            .map(|i| fact[k] * fact.inv(k - 2 * i) * fact.inv(i) * pow_2_inv[i])
            .collect(),
    )
}

fn main() {
    let mut buf = ngtio::with_stdin();
    let n = buf.usize();
    let fact = Factorial::new(2 * n + 1, |x| Fp::new(x as i64));
    let pow_2_inv = std::iter::successors(Some(Fp::one()), |x| Some(x * Fp::new(2).inv()))
        .take(2 * n + 1)
        .collect::<Vec<_>>();
    let mut double_factorial = vec![Fp::one(); 2 * n + 1];
    for i in 2..=2 * n {
        double_factorial[i] = double_factorial[i - 2] * Fp::new(i as i64);
    }

    let mut m = vec![0; 100_000];
    for _ in 0..2 * n {
        let x = buf.parse::<Usize1>();
        m[x] += 1;
    }
    let mut polies = m
        .iter()
        .copied()
        .filter(|&x| 2 <= x)
        .map(|x| g(x, &fact, &pow_2_inv))
        .collect::<Vec<_>>();
    polies.sort_by_key(|v| v.0.len());
    let mul = polies
        .iter()
        .cloned()
        .fold(Poly::one(), |x, y| fft::multiply(x, y));
    let ans = mul
        .into_inner()
        .iter()
        .enumerate()
        .map(|(i, &x)| {
            let sign = if i % 2 == 0 { Fp::one() } else { -Fp::one() };
            x * sign * double_factorial[(2 * (n - i)).saturating_sub(1)]
        })
        .sum::<Fp>();
    println!("{}", ans);
}

